(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("phdr-e",[{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ φίλε Φαῖδρε, ποῖ δὴ καὶ πόθεν;","st":"227a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παρὰ Λυσίου, ὦ Σώκρατες, τοῦ Κεφάλου, πορεύομαι δὲ πρὸς περίπατον ἔξω τείχους· συχνὸν γὰρ ἐκεῖ διέτριψα χρόνον καθήμενος ἐξ ἑωθινοῦ. τῷ δὲ σῷ καὶ ἐμῷ ἑταίρῳ πειθόμενος Ἀκουμενῷ κατὰ τὰς ὁδοὺς ποιοῦμαι τοὺς περιπάτους· φησὶ γὰρ ἀκοπωτέρους εἶναι τῶν ἐν τοῖς","st":"227a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δρόμοις.","st":"227b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς γάρ, ὦ ἑταῖρε, λέγει. ἀτὰρ Λυσίας ἦν, ὡς ἔοικεν, ἐν ἄστει.","st":"227b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί, παρ᾽ Ἐπικράτει, ἐν τῇδε τῇ πλησίον τοῦ Ὀλυμπίου οἰκίᾳ τῇ Μορυχίᾳ.","st":"227b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν δὴ ἦν ἡ διατριβή; ἢ δῆλον ὅτι τῶν λόγων ὑμᾶς Λυσίας εἱστία;","st":"227b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πεύσῃ, εἴ σοι σχολὴ προϊόντι ἀκούειν.","st":"227b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; οὐκ ἂν οἴει με κατὰ Πίνδαρον καὶ ἀσχολίας ὑπέρτερον πρᾶγμα ποιήσασθαι τὸ τεήν τε καὶ Λυσίου διατριβὴν ἀκοῦσαι;","st":"227b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πρόαγε δή.","st":"227c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγοις ἄν.","st":"227c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μήν, ὦ Σώκρατες, προσήκουσα γέ σοι ἡ ἀκοή· ὁ γάρ τοι λόγος ἦν, περὶ ὃν διετρίβομεν, οὐκ οἶδ᾽ ὅντινα τρόπον ἐρωτικός. γέγραφε γὰρ δὴ ὁ Λυσίας πειρώμενόν τινα τῶν καλῶν, οὐχ ὑπ᾽ ἐραστοῦ δέ, ἀλλ᾽ αὐτὸ δὴ τοῦτο καὶ κεκόμψευται· λέγει γὰρ ὡς χαριστέον μὴ ἐρῶντι μᾶλλον ἢ ἐρῶντι.","st":"227c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὢ γενναῖος. εἴθε γράψειεν ὡς χρὴ πένητι μᾶλλον ἢ πλουσίῳ, καὶ πρεσβυτέρῳ ἢ νεωτέρῳ, καὶ ὅσα ἄλλα","st":"227c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμοί τε πρόσεστι καὶ τοῖς πολλοῖς ἡμῶν· ἦ γὰρ ἂν ἀστεῖοι καὶ δημωφελεῖς εἶεν οἱ λόγοι. ἔγωγ᾽ οὖν οὕτως ἐπιτεθύμηκα ἀκοῦσαι, ὥστ᾽ ἐὰν βαδίζων ποιῇ τὸν περίπατον Μέγαράδε καὶ κατὰ Ἡρόδικον προσβὰς τῷ τείχει πάλιν ἀπίῃς, οὐ μή σου ἀπολειφθῶ.","st":"227d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς λέγεις, ὦ βέλτιστε Σώκρατες; οἴει με, ἃ","st":"227d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> Λυσίας ἐν πολλῷ χρόνῳ κατὰ σχολὴν συνέθηκε, δεινότατος ὢν τῶν νῦν γράφειν, ταῦτα ἰδιώτην ὄντα ἀπομνημονεύσειν ἀξίως ἐκείνου; πολλοῦ γε δέω· καίτοι ἐβουλόμην γ᾽ ἂν μᾶλλον ἤ μοι πολὺ χρυσίον γενέσθαι.","st":"228a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ Φαῖδρε, εἰ ἐγὼ Φαῖδρον ἀγνοῶ, καὶ ἐμαυτοῦ ἐπιλέλησμαι. ἀλλὰ γὰρ οὐδέτερά ἐστι τούτων· εὖ οἶδα ὅτι Λυσίου λόγον ἀκούων ἐκεῖνος οὐ μόνον ἅπαξ ἤκουσεν, ἀλλὰ πολλάκις ἐπαναλαμβάνων ἐκέλευέν οἱ λέγειν, ὁ δὲ ἐπείθετο","st":"228a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προθύμως. τῷ δὲ οὐδὲ ταῦτα ἦν ἱκανά, ἀλλὰ τελευτῶν παραλαβὼν τὸ βιβλίον ἃ μάλιστα ἐπεθύμει ἐπεσκόπει, καὶ τοῦτο δρῶν ἐξ ἑωθινοῦ καθήμενος ἀπειπὼν εἰς περίπατον ᾔει, ὡς μὲν ἐγὼ οἶμαι, νὴ τὸν κύνα, ἐξεπιστάμενος τὸν λόγον, εἰ μὴ πάνυ τι ἦν μακρός. ἐπορεύετο δ᾽ ἐκτὸς τείχους ἵνα μελετῴη. ἀπαντήσας δὲ τῷ νοσοῦντι περὶ λόγων ἀκοήν, ἰδὼν μέν, ἰδών, ἥσθη ὅτι ἕξοι τὸν συγκορυβαντιῶντα,","st":"228b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ προάγειν ἐκέλευε. δεομένου δὲ λέγειν τοῦ τῶν λόγων ἐραστοῦ, ἐθρύπτετο ὡς δὴ οὐκ ἐπιθυμῶν λέγειν· τελευτῶν δὲ ἔμελλε καὶ εἰ μή τις ἑκὼν ἀκούοι βίᾳ ἐρεῖν. σὺ οὖν, ὦ Φαῖδρε, αὐτοῦ δεήθητι ὅπερ τάχα πάντως ποιήσει νῦν ἤδη ποιεῖν.","st":"228c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐμοὶ ὡς ἀληθῶς πολὺ κράτιστόν ἐστιν οὕτως ὅπως δύναμαι λέγειν, ὥς μοι δοκεῖς σὺ οὐδαμῶς με ἀφήσειν πρὶν ἂν εἴπω ἁμῶς γέ πως.","st":"228c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάνυ γάρ σοι ἀληθῆ δοκῶ.","st":"228c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὑτωσὶ τοίνυν ποιήσω. τῷ ὄντι γάρ, ὦ Σώκρατες, παντὸς μᾶλλον τά γε ῥήματα οὐκ ἐξέμαθον· τὴν μέντοι διάνοιαν σχεδὸν ἁπάντων, οἷς ἔφη διαφέρειν τὰ τοῦ ἐρῶντος ἢ τὰ τοῦ μή, ἐν κεφαλαίοις ἕκαστον ἐφεξῆς δίειμι, ἀρξάμενος ἀπὸ τοῦ πρώτου.","st":"228d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δείξας γε πρῶτον, ὦ φιλότης, τί ἄρα ἐν τῇ ἀριστερᾷ ἔχεις ὑπὸ τῷ ἱματίῳ· τοπάζω γάρ σε ἔχειν τὸν λόγον αὐτόν. εἰ δὲ τοῦτό ἐστιν, οὑτωσὶ διανοοῦ περὶ ἐμοῦ, ὡς","st":"228d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγώ σε πάνυ μὲν φιλῶ, παρόντος δὲ καὶ Λυσίου, ἐμαυτόν σοι ἐμμελετᾶν παρέχειν οὐ πάνυ δέδοκται. ἀλλ᾽ ἴθι, δείκνυε.","st":"228e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παῦε. ἐκκέκρουκάς με ἐλπίδος, ὦ Σώκρατες, ἣν εἶχον ἐν σοὶ ὡς ἐγγυμνασόμενος. ἀλλὰ ποῦ δὴ βούλει καθιζόμενοι ἀναγνῶμεν;","st":"228e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεῦρ᾽ ἐκτραπόμενοι κατὰ τὸν Ἰλισὸν ἴωμεν, εἶτα ὅπου ἂν δόξῃ ἐν ἡσυχίᾳ καθιζησόμεθα.","st":"229a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἰς καιρόν, ὡς ἔοικεν, ἀνυπόδητος ὢν ἔτυχον· σὺ μὲν γὰρ δὴ ἀεί. ῥᾷστον οὖν ἡμῖν κατὰ τὸ ὑδάτιον βρέχουσι τοὺς πόδας ἰέναι, καὶ οὐκ ἀηδές, ἄλλως τε καὶ τήνδε τὴν ὥραν τοῦ ἔτους τε καὶ τῆς ἡμέρας.","st":"229a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρόαγε δή, καὶ σκόπει ἅμα ὅπου καθιζησόμεθα.","st":"229a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ὁρᾷς οὖν ἐκείνην τὴν ὑψηλοτάτην πλάτανον;","st":"229a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί μήν;","st":"229a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐκεῖ σκιά τ᾽ ἐστὶν καὶ πνεῦμα μέτριον, καὶ πόα καθίζεσθαι ἢ ἂν βουλώμεθα κατακλινῆναι.","st":"229b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προάγοις ἄν.","st":"229b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἰπέ μοι, ὦ Σώκρατες, οὐκ ἐνθένδε μέντοι ποθὲν ἀπὸ τοῦ Ἰλισοῦ λέγεται ὁ Βορέας τὴν Ὠρείθυιαν ἁρπάσαι;","st":"229b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγεται γάρ.","st":"229b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἆρ᾽ οὖν ἐνθένδε; χαρίεντα γοῦν καὶ καθαρὰ καὶ διαφανῆ τὰ ὑδάτια φαίνεται, καὶ ἐπιτήδεια κόραις παίζειν παρ᾽ αὐτά.","st":"229b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔκ, ἀλλὰ κάτωθεν ὅσον δύ᾽ ἢ τρία στάδια, ᾗ πρὸς τὸ ἐν Ἄγρας διαβαίνομεν· καὶ πού τίς ἐστι βωμὸς αὐτόθι Βορέου.","st":"229c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐ πάνυ νενόηκα· ἀλλ᾽ εἰπὲ πρὸς Διός, ὦ Σώκρατες, σὺ τοῦτο τὸ μυθολόγημα πείθῃ ἀληθὲς εἶναι;","st":"229c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ εἰ ἀπιστοίην, ὥσπερ οἱ σοφοί, οὐκ ἂν ἄτοπος εἴην, εἶτα σοφιζόμενος φαίην αὐτὴν πνεῦμα Βορέου κατὰ τῶν πλησίον πετρῶν σὺν Φαρμακείᾳ παίζουσαν ὦσαι, καὶ οὕτω δὴ τελευτήσασαν λεχθῆναι ὑπὸ τοῦ Βορέου ἀνάρπαστον","st":"229c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γεγονέναι—ἢ ἐξ Ἀρείου πάγου· λέγεται γὰρ αὖ καὶ οὗτος ὁ λόγος, ὡς ἐκεῖθεν ἀλλ᾽ οὐκ ἐνθένδε ἡρπάσθη. ἐγὼ δέ, ὦ Φαῖδρε, ἄλλως μὲν τὰ τοιαῦτα χαρίεντα ἡγοῦμαι, λίαν δὲ δεινοῦ καὶ ἐπιπόνου καὶ οὐ πάνυ εὐτυχοῦς ἀνδρός, κατ᾽ ἄλλο μὲν οὐδέν, ὅτι δ᾽ αὐτῷ ἀνάγκη μετὰ τοῦτο τὸ τῶν Ἱπποκενταύρων εἶδος ἐπανορθοῦσθαι, καὶ αὖθις τὸ τῆς Χιμαίρας, καὶ ἐπιρρεῖ δὲ ὄχλος τοιούτων Γοργόνων καὶ Πηγάσων καὶ","st":"229d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλων ἀμηχάνων πλήθη τε καὶ ἀτοπίαι τερατολόγων τινῶν φύσεων· αἷς εἴ τις ἀπιστῶν προσβιβᾷ κατὰ τὸ εἰκὸς ἕκαστον, ἅτε ἀγροίκῳ τινὶ σοφίᾳ χρώμενος, πολλῆς αὐτῷ σχολῆς δεήσει.","st":"229e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμοὶ δὲ πρὸς αὐτὰ οὐδαμῶς ἐστι σχολή· τὸ δὲ αἴτιον, ὦ φίλε, τούτου τόδε. οὐ δύναμαί πω κατὰ τὸ Δελφικὸν γράμμα γνῶναι ἐμαυτόν· γελοῖον δή μοι φαίνεται","st":"229e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο ἔτι ἀγνοοῦντα τὰ ἀλλότρια σκοπεῖν. ὅθεν δὴ χαίρειν ἐάσας ταῦτα, πειθόμενος δὲ τῷ νομιζομένῳ περὶ αὐτῶν, ὃ νυνδὴ ἔλεγον, σκοπῶ οὐ ταῦτα ἀλλ᾽ ἐμαυτόν, εἴτε τι θηρίον ὂν τυγχάνω Τυφῶνος πολυπλοκώτερον καὶ μᾶλλον ἐπιτεθυμμένον, εἴτε ἡμερώτερόν τε καὶ ἁπλούστερον ζῷον, θείας τινὸς καὶ ἀτύφου μοίρας φύσει μετέχον. ἀτάρ, ὦ ἑταῖρε, μεταξὺ τῶν λόγων, ἆρ᾽ οὐ τόδε ἦν τὸ δένδρον ἐφ᾽ ὅπερ ἦγες ἡμᾶς;","st":"230a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοῦτο μὲν οὖν αὐτό.","st":"230b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νὴ τὴν Ἥραν, καλή γε ἡ καταγωγή. ἥ τε γὰρ πλάτανος αὕτη μάλ᾽ ἀμφιλαφής τε καὶ ὑψηλή, τοῦ τε ἄγνου τὸ ὕψος καὶ τὸ σύσκιον πάγκαλον, καὶ ὡς ἀκμὴν ἔχει τῆς ἄνθης, ὡς ἂν εὐωδέστατον παρέχοι τὸν τόπον· ἥ τε αὖ πηγὴ χαριεστάτη ὑπὸ τῆς πλατάνου ῥεῖ μάλα ψυχροῦ ὕδατος, ὥστε γε τῷ ποδὶ τεκμήρασθαι. Νυμφῶν τέ τινων καὶ Ἀχελῴου ἱερὸν ἀπὸ τῶν κορῶν τε καὶ ἀγαλμάτων ἔοικεν εἶναι.","st":"230b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δ᾽ αὖ βούλει, τὸ εὔπνουν τοῦ τόπου ὡς ἀγαπητὸν καὶ σφόδρα ἡδύ· θερινόν τε καὶ λιγυρὸν ὑπηχεῖ τῷ τῶν τεττίγων χορῷ. πάντων δὲ κομψότατον τὸ τῆς πόας, ὅτι ἐν ἠρέμα προσάντει ἱκανὴ πέφυκε κατακλινέντι τὴν κεφαλὴν παγκάλως ἔχειν. ὥστε ἄριστά σοι ἐξενάγηται, ὦ φίλε Φαῖδρε.","st":"230c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> σὺ δέ γε, ὦ θαυμάσιε, ἀτοπώτατός τις φαίνῃ. ἀτεχνῶς γάρ, ὃ λέγεις, ξεναγουμένῳ τινὶ καὶ οὐκ ἐπιχωρίῳ","st":"230c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἔοικας· οὕτως ἐκ τοῦ ἄστεος οὔτ᾽ εἰς τὴν ὑπερορίαν ἀποδημεῖς, οὔτ᾽ ἔξω τείχους ἔμοιγε δοκεῖς τὸ παράπαν ἐξιέναι.","st":"230d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> συγγίγνωσκέ μοι, ὦ ἄριστε. φιλομαθὴς γάρ εἰμι· τὰ μὲν οὖν χωρία καὶ τὰ δένδρα οὐδέν μ᾽ ἐθέλει διδάσκειν, οἱ δ᾽ ἐν τῷ ἄστει ἄνθρωποι. σὺ μέντοι δοκεῖς μοι τῆς ἐμῆς ἐξόδου τὸ φάρμακον ηὑρηκέναι. ὥσπερ γὰρ οἱ τὰ πεινῶντα θρέμματα θαλλὸν ἤ τινα καρπὸν προσείοντες ἄγουσιν, σὺ ἐμοὶ λόγους οὕτω προτείνων ἐν βιβλίοις τήν τε","st":"230d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> Ἀττικὴν φαίνῃ περιάξειν ἅπασαν καὶ ὅποι ἂν ἄλλοσε βούλῃ. νῦν δ᾽ οὖν ἐν τῷ παρόντι δεῦρ᾽ ἀφικόμενος ἐγὼ μέν μοι δοκῶ κατακείσεσθαι, σὺ δ᾽ ἐν ὁποίῳ σχήματι οἴει ῥᾷστα ἀναγνώσεσθαι, τοῦθ᾽ ἑλόμενος ἀναγίγνωσκε.","st":"230e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἄκουε δή.","st":"230e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> περὶ μὲν τῶν ἐμῶν πραγμάτων ἐπίστασαι, καὶ ὡς νομίζω συμφέρειν ἡμῖν γενομένων τούτων ἀκήκοας· ἀξιῶ δὲ μὴ διὰ","st":"230e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοῦτο ἀτυχῆσαι ὧν δέομαι, ὅτι οὐκ ἐραστὴς ὤν σου τυγχάνω. ὡς ἐκείνοις μὲν τότε μεταμέλει ὧν ἂν εὖ ποιήσωσιν, ἐπειδὰν τῆς ἐπιθυμίας παύσωνται· τοῖς δὲ οὐκ ἔστι χρόνος ἐν ᾧ μεταγνῶναι προσήκει. οὐ γὰρ ὑπ᾽ ἀνάγκης ἀλλ᾽ ἑκόντες, ὡς ἂν ἄριστα περὶ τῶν οἰκείων βουλεύσαιντο, πρὸς τὴν δύναμιν τὴν αὑτῶν εὖ ποιοῦσιν. ἔτι δὲ οἱ μὲν ἐρῶντες σκοποῦσιν ἅ τε κακῶς διέθεντο τῶν αὑτῶν διὰ τὸν ἔρωτα καὶ ἃ πεποιήκασιν εὖ, καὶ ὃν εἶχον πόνον προστιθέντες","st":"231a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἡγοῦνται πάλαι τὴν ἀξίαν ἀποδεδωκέναι χάριν τοῖς ἐρωμένοις· τοῖς δὲ μὴ ἐρῶσιν οὔτε τὴν τῶν οἰκείων ἀμέλειαν διὰ τοῦτο ἔστιν προφασίζεσθαι, οὔτε τοὺς παρεληλυθότας πόνους ὑπολογίζεσθαι, οὔτε τὰς πρὸς τοὺς προσήκοντας διαφορὰς αἰτιάσασθαι· ὥστε περιῃρημένων τοσούτων κακῶν οὐδὲν ὑπολείπεται ἀλλ᾽ ἢ ποιεῖν προθύμως ὅτι ἂν αὐτοῖς οἴωνται πράξαντες χαριεῖσθαι. ἔτι δὲ εἰ διὰ τοῦτο ἄξιον","st":"231b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοὺς ἐρῶντας περὶ πολλοῦ ποιεῖσθαι, ὅτι τούτους μάλιστά φασιν φιλεῖν ὧν ἂν ἐρῶσιν, καὶ ἕτοιμοί εἰσι καὶ ἐκ τῶν λόγων καὶ ἐκ τῶν ἔργων τοῖς ἄλλοις ἀπεχθανόμενοι τοῖς ἐρωμένοις χαρίζεσθαι, ῥᾴδιον γνῶναι, εἰ ἀληθῆ λέγουσιν, ὅτι ὅσων ἂν ὕστερον ἐρασθῶσιν, ἐκείνους αὐτῶν περὶ πλείονος ποιήσονται, καὶ δῆλον ὅτι, ἐὰν ἐκείνοις δοκῇ, καὶ τούτους κακῶς ποιήσουσιν. καίτοι πῶς εἰκός ἐστι τοιοῦτον πρᾶγμα προέσθαι","st":"231c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοιαύτην ἔχοντι συμφοράν, ἣν οὐδ᾽ ἂν ἐπιχειρήσειεν οὐδεὶς ἔμπειρος ὢν ἀποτρέπειν; καὶ γὰρ αὐτοὶ ὁμολογοῦσι νοσεῖν μᾶλλον ἢ σωφρονεῖν, καὶ εἰδέναι ὅτι κακῶς φρονοῦσιν, ἀλλ᾽ οὐ δύνασθαι αὑτῶν κρατεῖν· ὥστε πῶς ἂν εὖ φρονήσαντες ταῦτα καλῶς ἔχειν ἡγήσαιντο περὶ ὧν οὕτω διακείμενοι βουλεύονται; καὶ μὲν δὴ εἰ μὲν ἐκ τῶν ἐρώντων τὸν βέλτιστον αἱροῖο, ἐξ ὀλίγων ἄν σοι ἡ ἔκλεξις εἴη· εἰ δ᾽ ἐκ τῶν ἄλλων τὸν σαυτῷ ἐπιτηδειότατον, ἐκ πολλῶν· ὥστε πολὺ","st":"231d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πλείων ἐλπὶς ἐν τοῖς πολλοῖς ὄντα τυχεῖν τὸν ἄξιον τῆς σῆς φιλίας.","st":"231e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἰ τοίνυν τὸν νόμον τὸν καθεστηκότα δέδοικας, μὴ πυθομένων τῶν ἀνθρώπων ὄνειδός σοι γένηται, εἰκός ἐστι","st":"231e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοὺς μὲν ἐρῶντας, οὕτως ἂν οἰομένους καὶ ὑπὸ τῶν ἄλλων ζηλοῦσθαι ὥσπερ αὐτοὺς ὑφ᾽ αὑτῶν, ἐπαρθῆναι τῷ λέγειν καὶ φιλοτιμουμένους ἐπιδείκνυσθαι πρὸς ἅπαντας ὅτι οὐκ ἄλλως αὐτοῖς πεπόνηται· τοὺς δὲ μὴ ἐρῶντας, κρείττους αὑτῶν ὄντας, τὸ βέλτιστον ἀντὶ τῆς δόξης τῆς παρὰ τῶν ἀνθρώπων αἱρεῖσθαι. ἔτι δὲ τοὺς μὲν ἐρῶντας πολλοὺς ἀνάγκη πυθέσθαι καὶ ἰδεῖν ἀκολουθοῦντας τοῖς ἐρωμένοις καὶ ἔργον τοῦτο ποιουμένους, ὥστε ὅταν ὀφθῶσι διαλεγόμενοι","st":"232a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀλλήλοις, τότε αὐτοὺς οἴονται ἢ γεγενημένης ἢ μελλούσης ἔσεσθαι τῆς ἐπιθυμίας συνεῖναι· τοὺς δὲ μὴ ἐρῶντας οὐδ᾽ αἰτιᾶσθαι διὰ τὴν συνουσίαν ἐπιχειροῦσιν, εἰδότες ὅτι ἀναγκαῖόν ἐστιν ἢ διὰ φιλίαν τῳ διαλέγεσθαι ἢ δι᾽ ἄλλην τινὰ ἡδονήν. καὶ μὲν δὴ εἴ σοι δέος παρέστηκεν ἡγουμένῳ χαλεπὸν εἶναι φιλίαν συμμένειν, καὶ ἄλλῳ μὲν τρόπῳ διαφορᾶς γενομένης κοινὴν ἂν ἀμφοτέροις καταστῆναι τὴν","st":"232b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> συμφοράν, προεμένου δέ σου ἃ περὶ πλείστου ποιῇ μεγάλην ἄν σοι βλάβην ἂν γενέσθαι, εἰκότως ἂν τοὺς ἐρῶντας μᾶλλον ἂν φοβοῖο· πολλὰ γὰρ αὐτούς ἐστι τὰ λυποῦντα, καὶ πάντ᾽ ἐπὶ τῇ αὑτῶν βλάβῃ νομίζουσι γίγνεσθαι. διόπερ καὶ τὰς πρὸς τοὺς ἄλλους τῶν ἐρωμένων συνουσίας ἀποτρέπουσιν, φοβούμενοι τοὺς μὲν οὐσίαν κεκτημένους μὴ χρήμασιν αὐτοὺς ὑπερβάλωνται, τοὺς δὲ πεπαιδευμένους μὴ συνέσει κρείττους γένωνται· τῶν δὲ ἄλλο τι κεκτημένων","st":"232c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀγαθὸν τὴν δύναμιν ἑκάστου φυλάττονται. πείσαντες μὲν οὖν ἀπεχθέσθαι σε τούτοις εἰς ἐρημίαν φίλων καθιστᾶσιν, ἐὰν δὲ τὸ σεαυτοῦ σκοπῶν ἄμεινον ἐκείνων φρονῇς, ἥξεις αὐτοῖς εἰς διαφοράν· ὅσοι δὲ μὴ ἐρῶντες ἔτυχον, ἀλλὰ δι᾽ ἀρετὴν ἔπραξαν ὧν ἐδέοντο, οὐκ ἂν τοῖς συνοῦσι φθονοῖεν, ἀλλὰ τοὺς μὴ ἐθέλοντας μισοῖεν, ἡγούμενοι ὑπ᾽ ἐκείνων μὲν ὑπερορᾶσθαι, ὑπὸ τῶν συνόντων δὲ ὠφελεῖσθαι, ὥστε πολὺ","st":"232d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πλείων ἐλπὶς φιλίαν αὐτοῖς ἐκ τοῦ πράγματος ἢ ἔχθραν γενέσθαι.","st":"232e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μὲν δὴ τῶν μὲν ἐρώντων πολλοὶ πρότερον τοῦ σώματος ἐπεθύμησαν ἢ τὸν τρόπον ἔγνωσαν καὶ τῶν ἄλλων οἰκείων ἔμπειροι ἐγένοντο, ὥστε ἄδηλον αὐτοῖς εἰ ἔτι τότε βουλήσονται φίλοι εἶναι, ἐπειδὰν τῆς ἐπιθυμίας παύσωνται·","st":"232e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοῖς δὲ μὴ ἐρῶσιν, οἳ καὶ πρότερον ἀλλήλοις φίλοι ὄντες ταῦτα ἔπραξαν, οὐκ ἐξ ὧν ἂν εὖ πάθωσι ταῦτα εἰκὸς ἐλάττω τὴν φιλίαν αὐτοῖς ποιῆσαι, ἀλλὰ ταῦτα μνημεῖα καταλειφθῆναι τῶν μελλόντων ἔσεσθαι. καὶ μὲν δὴ βελτίονί σοι προσήκει γενέσθαι ἐμοὶ πειθομένῳ ἢ ἐραστῇ. ἐκεῖνοι μὲν γὰρ καὶ παρὰ τὸ βέλτιστον τά τε λεγόμενα καὶ τὰ πραττόμενα ἐπαινοῦσιν, τὰ μὲν δεδιότες μὴ ἀπέχθωνται, τὰ δὲ","st":"233a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ αὐτοὶ χεῖρον διὰ τὴν ἐπιθυμίαν γιγνώσκοντες. τοιαῦτα γὰρ ὁ ἔρως ἐπιδείκνυται· δυστυχοῦντας μέν, ἃ μὴ λύπην τοῖς ἄλλοις παρέχει, ἀνιαρὰ ποιεῖ νομίζειν· εὐτυχοῦντας δὲ καὶ τὰ μὴ ἡδονῆς ἄξια παρ᾽ ἐκείνων ἐπαίνου ἀναγκάζει τυγχάνειν· ὥστε πολὺ μᾶλλον ἐλεεῖν τοῖς ἐρωμένοις ἢ ζηλοῦν αὐτοὺς προσήκει. ἐὰν δέ μοι πείθῃ, πρῶτον μὲν οὐ τὴν παροῦσαν ἡδονὴν θεραπεύων συνέσομαί σοι, ἀλλὰ καὶ","st":"233b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὴν μέλλουσαν ὠφελίαν ἔσεσθαι, οὐχ ὑπ᾽ ἔρωτος ἡττώμενος ἀλλ᾽ ἐμαυτοῦ κρατῶν, οὐδὲ διὰ σμικρὰ ἰσχυρὰν ἔχθραν ἀναιρούμενος ἀλλὰ διὰ μεγάλα βραδέως ὀλίγην ὀργὴν ποιούμενος, τῶν μὲν ἀκουσίων συγγνώμην ἔχων, τὰ δὲ ἑκούσια πειρώμενος ἀποτρέπειν· ταῦτα γάρ ἐστι φιλίας πολὺν χρόνον ἐσομένης τεκμήρια. εἰ δ᾽ ἄρα σοι τοῦτο παρέστηκεν, ὡς οὐχ οἷόν τε ἰσχυρὰν φιλίαν γενέσθαι ἐὰν μή τις ἐρῶν τυγχάνῃ,","st":"233c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐνθυμεῖσθαι χρὴ ὅτι οὔτ᾽ ἂν τοὺς ὑεῖς περὶ πολλοῦ ἐποιούμεθα οὔτ᾽ ἂν τοὺς πατέρας καὶ τὰς μητέρας, οὔτ᾽ ἂν πιστοὺς φίλους ἐκεκτήμεθα, οἳ οὐκ ἐξ ἐπιθυμίας τοιαύτης γεγόνασιν ἀλλ᾽ ἐξ ἑτέρων ἐπιτηδευμάτων. ἔτι δὲ εἰ χρὴ τοῖς δεομένοις μάλιστα χαρίζεσθαι, προσήκει καὶ τοῖς ἄλλοις μὴ τοὺς βελτίστους ἀλλὰ τοὺς ἀπορωτάτους εὖ ποιεῖν· μεγίστων γὰρ ἀπαλλαγέντες κακῶν πλείστην χάριν αὐτοῖς εἴσονται. καὶ μὲν δὴ καὶ ἐν ταῖς","st":"233d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἰδίαις δαπάναις οὐ τοὺς φίλους ἄξιον παρακαλεῖν, ἀλλὰ τοὺς προσαιτοῦντας καὶ τοὺς δεομένους πλησμονῆς· ἐκεῖνοι γὰρ καὶ ἀγαπήσουσιν καὶ ἀκολουθήσουσιν καὶ ἐπὶ τὰς θύρας ἥξουσι καὶ μάλιστα ἡσθήσονται καὶ οὐκ ἐλαχίστην χάριν εἴσονται καὶ πολλὰ ἀγαθὰ αὐτοῖς εὔξονται.","st":"233e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀλλ᾽ ἴσως προσήκει οὐ τοῖς σφόδρα δεομένοις χαρίζεσθαι, ἀλλὰ τοῖς μάλιστα ἀποδοῦναι χάριν δυναμένοις· οὐδὲ τοῖς προσαιτοῦσι","st":"233e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> μόνον, ἀλλὰ τοῖς τοῦ πράγματος ἀξίοις· οὐδὲ ὅσοι τῆς σῆς ὥρας ἀπολαύσονται, ἀλλ᾽ οἵτινες πρεσβυτέρῳ γενομένῳ τῶν σφετέρων ἀγαθῶν μεταδώσουσιν· οὐδὲ οἳ διαπραξάμενοι πρὸς τοὺς ἄλλους φιλοτιμήσονται, ἀλλ᾽ οἵτινες αἰσχυνόμενοι πρὸς ἅπαντας σιωπήσονται· οὐδὲ τοῖς ὀλίγον χρόνον σπουδάζουσιν, ἀλλὰ τοῖς ὁμοίως διὰ παντὸς τοῦ βίου φίλοις ἐσομένοις· οὐδὲ οἵτινες παυόμενοι τῆς ἐπιθυμίας ἔχθρας πρόφασιν ζητήσουσιν, ἀλλ᾽ οἳ παυσαμένου τῆς ὥρας τότε","st":"234a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὴν αὑτῶν ἀρετὴν ἐπιδείξονται. σὺ οὖν τῶν τε εἰρημένων μέμνησο καὶ ἐκεῖνο ἐνθυμοῦ, ὅτι τοὺς μὲν ἐρῶντας οἱ φίλοι νουθετοῦσιν ὡς ὄντος κακοῦ τοῦ ἐπιτηδεύματος, τοῖς δὲ μὴ ἐρῶσιν οὐδεὶς πώποτε τῶν οἰκείων ἐμέμψατο ὡς διὰ τοῦτο κακῶς βουλευομένοις περὶ ἑαυτῶν. ἴσως ἂν οὖν ἔροιό με εἰ ἅπασίν σοι παραινῶ τοῖς μὴ ἐρῶσι χαρίζεσθαι. ἐγὼ μὲν οἶμαι οὐδ᾽ ἂν τὸν ἐρῶντα πρὸς ἅπαντάς σε κελεύειν τοὺς ἐρῶντας ταύτην ἔχειν τὴν","st":"234b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> διάνοιαν. οὔτε γὰρ τῷ λαμβάνοντι χάριτος ἴσης ἄξιον, οὔτε σοὶ βουλομένῳ τοὺς ἄλλους λανθάνειν ὁμοίως δυνατόν· δεῖ δὲ βλάβην μὲν ἀπ᾽ αὐτοῦ μηδεμίαν, ὠφελίαν δὲ ἀμφοῖν γίγνεσθαι. ἐγὼ μὲν οὖν ἱκανά μοι νομίζω τὰ εἰρημένα· εἰ δ᾽ ἔτι τι σὺ ποθεῖς, ἡγούμενος παραλελεῖφθαι, ἐρώτα. τί σοι φαίνεται, ὦ Σώκρατες, ὁ λόγος; οὐχ ὑπερφυῶς τά τε ἄλλα καὶ τοῖς ὀνόμασιν εἰρῆσθαι;","st":"234c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δαιμονίως μὲν οὖν, ὦ ἑταῖρε, ὥστε με ἐκπλαγῆναι. καὶ τοῦτο ἐγὼ ἔπαθον διὰ σέ, ὦ Φαῖδρε, πρὸς σὲ ἀποβλέπων, ὅτι ἐμοὶ ἐδόκεις γάνυσθαι ὑπὸ τοῦ λόγου μεταξὺ ἀναγιγνώσκων· ἡγούμενος γὰρ σὲ μᾶλλον ἢ ἐμὲ ἐπαΐειν περὶ τῶν τοιούτων σοὶ εἱπόμην, καὶ ἑπόμενος συνεβάκχευσα μετὰ σοῦ τῆς θείας κεφαλῆς.","st":"234d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἶεν· οὕτω δὴ δοκεῖ παίζειν;","st":"234d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δοκῶ γάρ σοι παίζειν καὶ οὐχὶ ἐσπουδακέναι;","st":"234d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> μηδαμῶς, ὦ Σώκρατες, ἀλλ᾽ ὡς ἀληθῶς εἰπὲ πρὸς Διὸς φιλίου, οἴει ἄν τινα ἔχειν εἰπεῖν ἄλλον τῶν Ἑλλήνων ἕτερα τούτων μείζω καὶ πλείω περὶ τοῦ αὐτοῦ πράγματος;","st":"234e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; καὶ ταύτῃ δεῖ ὑπ᾽ ἐμοῦ τε καὶ σοῦ τὸν λόγον ἐπαινεθῆναι, ὡς τὰ δέοντα εἰρηκότος τοῦ ποιητοῦ, ἀλλ᾽ οὐκ ἐκείνῃ μόνον, ὅτι σαφῆ καὶ στρογγύλα, καὶ ἀκριβῶς ἕκαστα τῶν ὀνομάτων ἀποτετόρνευται; εἰ γὰρ δεῖ, συγχωρητέον χάριν σήν, ἐπεὶ ἐμέ γε ἔλαθεν ὑπὸ τῆς ἐμῆς","st":"234e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδενίας· τῷ γὰρ ῥητορικῷ αὐτοῦ μόνῳ τὸν νοῦν προσεῖχον, τοῦτο δὲ οὐδ᾽ ἂν αὐτὸν ᾤμην Λυσίαν οἴεσθαι ἱκανὸν εἶναι. καὶ οὖν μοι ἔδοξεν, ὦ Φαῖδρε, εἰ μή τι σὺ ἄλλο λέγεις, δὶς καὶ τρὶς τὰ αὐτὰ εἰρηκέναι, ὡς οὐ πάνυ εὐπορῶν τοῦ πολλὰ λέγειν περὶ τοῦ αὐτοῦ, ἢ ἴσως οὐδὲν αὐτῷ μέλον τοῦ τοιούτου· καὶ ἐφαίνετο δή μοι νεανιεύεσθαι ἐπιδεικνύμενος ὡς οἷός τε ὢν ταὐτὰ ἑτέρως τε καὶ ἑτέρως λέγων ἀμφοτέρως εἰπεῖν ἄριστα.","st":"235a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐδὲν λέγεις, ὦ Σώκρατες· αὐτὸ γὰρ τοῦτο καὶ μάλιστα ὁ λόγος ἔχει. τῶν γὰρ ἐνόντων ἀξίως ῥηθῆναι ἐν τῷ πράγματι οὐδὲν παραλέλοιπεν, ὥστε παρὰ τὰ ἐκείνῳ εἰρημένα μηδέν᾽ ἄν ποτε δύνασθαι εἰπεῖν ἄλλα πλείω καὶ πλείονος ἄξια.","st":"235b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο ἐγώ σοι οὐκέτι οἷός τ᾽ ἔσομαι πιθέσθαι· παλαιοὶ γὰρ καὶ σοφοὶ ἄνδρες τε καὶ γυναῖκες περὶ αὐτῶν εἰρηκότες καὶ γεγραφότες ἐξελέγξουσί με, ἐάν σοι χαριζόμενος συγχωρῶ.","st":"235b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τίνες οὗτοι; καὶ ποῦ σὺ βελτίω τούτων ἀκήκοας;","st":"235c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν μὲν οὕτως οὐκ ἔχω εἰπεῖν· δῆλον δὲ ὅτι τινῶν ἀκήκοα, ἤ που Σαπφοῦς τῆς καλῆς ἢ Ἀνακρέοντος τοῦ σοφοῦ ἢ καὶ συγγραφέων τινῶν. πόθεν δὴ τεκμαιρόμενος λέγω; πλῆρές πως, ὦ δαιμόνιε, τὸ στῆθος ἔχων αἰσθάνομαι παρὰ ταῦτα ἂν ἔχειν εἰπεῖν ἕτερα μὴ χείρω. ὅτι μὲν οὖν παρά γε ἐμαυτοῦ οὐδὲν αὐτῶν ἐννενόηκα, εὖ οἶδα, συνειδὼς ἐμαυτῷ ἀμαθίαν· λείπεται δὴ οἶμαι ἐξ ἀλλοτρίων ποθὲν","st":"235c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ναμάτων διὰ τῆς ἀκοῆς πεπληρῶσθαί με δίκην ἀγγείου. ὑπὸ δὲ νωθείας αὖ καὶ αὐτὸ τοῦτο ἐπιλέλησμαι, ὅπως τε καὶ ὧντινων ἤκουσα.","st":"235d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀλλ᾽, ὦ γενναιότατε, κάλλιστα εἴρηκας. σὺ γὰρ ἐμοὶ ὧντινων μὲν καὶ ὅπως ἤκουσας μηδ᾽ ἂν κελεύω εἴπῃς, τοῦτο δὲ αὐτὸ ὃ λέγεις ποίησον· τῶν ἐν τῷ βιβλίῳ βελτίω τε καὶ μὴ ἐλάττω ἕτερα ὑπέσχησαι εἰπεῖν τούτων ἀπεχόμενος, καί σοι ἐγώ, ὥσπερ οἱ ἐννέα ἄρχοντες, ὑπισχνοῦμαι χρυσῆν εἰκόνα ἰσομέτρητον εἰς Δελφοὺς ἀναθήσειν, οὐ","st":"235d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> μόνον ἐμαυτοῦ ἀλλὰ καὶ σήν.","st":"235e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φίλτατος εἶ καὶ ὡς ἀληθῶς χρυσοῦς, ὦ Φαῖδρε, εἴ με οἴει λέγειν ὡς Λυσίας τοῦ παντὸς ἡμάρτηκεν, καὶ οἷόν τε δὴ παρὰ πάντα ταῦτα ἄλλα εἰπεῖν· τοῦτο δὲ οἶμαι οὐδ᾽ ἂν τὸν φαυλότατον παθεῖν συγγραφέα. αὐτίκα περὶ οὗ ὁ λόγος, τίνα οἴει λέγοντα ὡς χρὴ μὴ ἐρῶντι μᾶλλον ἢ ἐρῶντι χαρίζεσθαι, παρέντα τοῦ μὲν τὸ φρόνιμον ἐγκωμιάζειν,","st":"235e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦ δὲ τὸ ἄφρον ψέγειν, ἀναγκαῖα γοῦν ὄντα, εἶτ᾽ ἄλλ᾽ ἄττα ἕξειν λέγειν; ἀλλ᾽ οἶμαι τὰ μὲν τοιαῦτα ἐατέα καὶ συγγνωστέα λέγοντι· καὶ τῶν μὲν τοιούτων οὐ τὴν εὕρεσιν ἀλλὰ τὴν διάθεσιν ἐπαινετέον, τῶν δὲ μὴ ἀναγκαίων τε καὶ χαλεπῶν εὑρεῖν πρὸς τῇ διαθέσει καὶ τὴν εὕρεσιν.","st":"236a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> συγχωρῶ ὃ λέγεις· μετρίως γάρ μοι δοκεῖς εἰρηκέναι. ποιήσω οὖν καὶ ἐγὼ οὕτως· τὸ μὲν τὸν ἐρῶντα","st":"236a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοῦ μὴ ἐρῶντος μᾶλλον νοσεῖν δώσω σοι ὑποτίθεσθαι, τῶν δὲ λοιπῶν ἕτερα πλείω καὶ πλείονος ἄξια εἰπὼν τῶνδε παρὰ τὸ Κυψελιδῶν ἀνάθημα σφυρήλατος ἐν Ὀλυμπίᾳ στάθητι.","st":"236b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐσπούδακας, ὦ Φαῖδρε, ὅτι σου τῶν παιδικῶν ἐπελαβόμην ἐρεσχηλῶν σε, καὶ οἴει δή με ὡς ἀληθῶς ἐπιχειρήσειν εἰπεῖν παρὰ τὴν ἐκείνου σοφίαν ἕτερόν τι ποικιλώτερον;","st":"236b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> περὶ μὲν τούτου, ὦ φίλε, εἰς τὰς ὁμοίας λαβὰς","st":"236b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐλήλυθας. ῥητέον μὲν γάρ σοι παντὸς μᾶλλον οὕτως ὅπως οἷός τε εἶ, ἵνα μὴ τὸ τῶν κωμῳδῶν φορτικὸν πρᾶγμα ἀναγκαζώμεθα ποιεῖν ἀνταποδιδόντες ἀλλήλοις , καὶ μὴ βούλου με ἀναγκάσαι λέγειν ἐκεῖνο τὸ εἰ ἐγώ, ὦ Σώκρατες, Σωκράτην ἀγνοῶ, καὶ ἐμαυτοῦ ἐπιλέλησμαι, καὶ ὅτι ἐπεθύμει μὲν λέγειν, ἐθρύπτετο δέ· ἀλλὰ διανοήθητι ὅτι ἐντεῦθεν οὐκ ἄπιμεν πρὶν ἂν σὺ εἴπῃς ἃ ἔφησθα ἐν τῷ στήθει ἔχειν. ἐσμὲν δὲ μόνω ἐν ἐρημίᾳ,","st":"236c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἰσχυρότερος δ᾽ ἐγὼ καὶ νεώτερος, ἐκ δὲ ἁπάντων τούτων σύνες ὅ τοι λέγω, καὶ μηδαμῶς πρὸς βίαν βουληθῇς μᾶλλον ἢ ἑκὼν λέγειν.","st":"236d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽, ὦ μακάριε Φαῖδρε, γελοῖος ἔσομαι παρ᾽ ἀγαθὸν ποιητὴν ἰδιώτης αὐτοσχεδιάζων περὶ τῶν αὐτῶν.","st":"236d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οἶσθ᾽ ὡς ἔχει; παῦσαι πρός με καλλωπιζόμενος· σχεδὸν γὰρ ἔχω ὃ εἰπὼν ἀναγκάσω σε λέγειν.","st":"236d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μηδαμῶς τοίνυν εἴπῃς.","st":"236d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὔκ, ἀλλὰ καὶ δὴ λέγω· ὁ δέ μοι λόγος ὅρκος ἔσται. ὄμνυμι γάρ σοι—τίνα μέντοι, τίνα θεῶν; ἢ βούλει","st":"236d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὴν πλάτανον ταυτηνί; —ἦ μήν, ἐάν μοι μὴ εἴπῃς τὸν λόγον ἐναντίον αὐτῆς ταύτης, μηδέποτέ σοι ἕτερον λόγον μηδένα μηδενὸς μήτε ἐπιδείξειν μήτε ἐξαγγελεῖν.","st":"236e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βαβαῖ, ὦ μιαρέ, ὡς εὖ ἀνηῦρες τὴν ἀνάγκην ἀνδρὶ φιλολόγῳ ποιεῖν ὃ ἂν κελεύῃς.","st":"236e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί δῆτα ἔχων στρέφῃ;","st":"236e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδὲν ἔτι, ἐπειδὴ σύ γε ταῦτα ὀμώμοκας. πῶς γὰρ ἂν οἷός τ᾽ εἴην τοιαύτης θοίνης ἀπέχεσθαι;","st":"236e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λέγε δή.","st":"237a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶσθ᾽ οὖν ὡς ποιήσω;","st":"237a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοῦ πέρι;","st":"237a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐγκαλυψάμενος ἐρῶ, ἵν᾽ ὅτι τάχιστα διαδράμω τὸν λόγον καὶ μὴ βλέπων πρὸς σὲ ὑπ᾽ αἰσχύνης διαπορῶμαι.","st":"237a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λέγε μόνον, τὰ δ᾽ ἄλλα ὅπως βούλει ποίει.","st":"237a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄγετε δή, ὦ Μοῦσαι, εἴτε δι᾽ ᾠδῆς εἶδος λίγειαι, εἴτε διὰ γένος μουσικὸν τὸ Λιγύων ταύτην ἔσχετ᾽ ἐπωνυμίαν, ξύμ μοι λάβεσθε τοῦ μύθου, ὅν με ἀναγκάζει ὁ βέλτιστος οὑτοσὶ λέγειν, ἵν᾽ ὁ ἑταῖρος αὐτοῦ, καὶ πρότερον","st":"237a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δοκῶν τούτῳ σοφὸς εἶναι, νῦν ἔτι μᾶλλον δόξῃ. ἦν οὕτω δὴ παῖς, μᾶλλον δὲ μειρακίσκος, μάλα καλός· τούτῳ δὲ ἦσαν ἐρασταὶ πάνυ πολλοί. εἷς δέ τις αὐτῶν αἱμύλος ἦν, ὃς οὐδενὸς ἧττον ἐρῶν ἐπεπείκει τὸν παῖδα ὡς οὐκ ἐρῴη. καί ποτε αὐτὸν αἰτῶν ἔπειθεν τοῦτ᾽ αὐτό, ὡς μὴ ἐρῶντι πρὸ τοῦ ἐρῶντος δέοι χαρίζεσθαι, ἔλεγέν τε ὧδε— περὶ παντός, ὦ παῖ, μία ἀρχὴ τοῖς μέλλουσι καλῶς","st":"237b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βουλεύσεσθαι· εἰδέναι δεῖ περὶ οὗ ἂν ᾖ ἡ βουλή, ἢ παντὸς ἁμαρτάνειν ἀνάγκη. τοὺς δὲ πολλοὺς λέληθεν ὅτι οὐκ ἴσασι τὴν οὐσίαν ἑκάστου. ὡς οὖν εἰδότες οὐ διομολογοῦνται ἐν ἀρχῇ τῆς σκέψεως, προελθόντες δὲ τὸ εἰκὸς ἀποδιδόασιν· οὔτε γὰρ ἑαυτοῖς οὔτε ἀλλήλοις ὁμολογοῦσιν. ἐγὼ οὖν καὶ σὺ μὴ πάθωμεν ὃ ἄλλοις ἐπιτιμῶμεν, ἀλλ᾽ ἐπειδὴ σοὶ καὶ ἐμοὶ ὁ λόγος πρόκειται πότερα ἐρῶντι ἢ μὴ μᾶλλον εἰς φιλίαν ἰτέον, περὶ ἔρωτος οἷόν τ᾽ ἔστι καὶ ἣν ἔχει δύναμιν,","st":"237c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁμολογίᾳ θέμενοι ὅρον, εἰς τοῦτο ἀποβλέποντες καὶ ἀναφέροντες τὴν σκέψιν ποιώμεθα εἴτε ὠφελίαν εἴτε βλάβην παρέχει. ὅτι μὲν οὖν δὴ ἐπιθυμία τις ὁ ἔρως, ἅπαντι δῆλον· ὅτι δ᾽ αὖ καὶ μὴ ἐρῶντες ἐπιθυμοῦσι τῶν καλῶν, ἴσμεν. τῷ δὴ τὸν ἐρῶντά τε καὶ μὴ κρινοῦμεν; δεῖ αὖ νοῆσαι ὅτι ἡμῶν ἐν ἑκάστῳ δύο τινέ ἐστον ἰδέα ἄρχοντε καὶ ἄγοντε, οἷν ἑπόμεθα ᾗ ἂν ἄγητον, ἡ μὲν ἔμφυτος οὖσα ἐπιθυμία ἡδονῶν, ἄλλη δὲ ἐπίκτητος δόξα, ἐφιεμένη τοῦ ἀρίστου. τούτω δὲ ἐν ἡμῖν τοτὲ μὲν ὁμονοεῖτον,","st":"237d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστι δὲ ὅτε στασιάζετον· καὶ τοτὲ μὲν ἡ ἑτέρα, ἄλλοτε δὲ ἡ ἑτέρα κρατεῖ.","st":"237e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δόξης μὲν οὖν ἐπὶ τὸ ἄριστον λόγῳ ἀγούσης καὶ κρατούσης τῷ κράτει σωφροσύνη ὄνομα·","st":"237e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπιθυμίας δὲ ἀλόγως ἑλκούσης ἐπὶ ἡδονὰς καὶ ἀρξάσης ἐν ἡμῖν τῇ ἀρχῇ ὕβρις ἐπωνομάσθη. ὕβρις δὲ δὴ πολυώνυμον —πολυμελὲς γὰρ καὶ πολυμερές—καὶ τούτων τῶν ἰδεῶν ἐκπρεπὴς ἣ ἂν τύχῃ γενομένη, τὴν αὑτῆς ἐπωνυμίαν ὀνομαζόμενον τὸν ἔχοντα παρέχεται, οὔτε τινὰ καλὴν οὔτ᾽ ἐπαξίαν κεκτῆσθαι. περὶ μὲν γὰρ ἐδωδὴν κρατοῦσα τοῦ λόγου τε τοῦ ἀρίστου καὶ τῶν ἄλλων ἐπιθυμιῶν ἐπιθυμία","st":"238a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γαστριμαργία τε καὶ τὸν ἔχοντα ταὐτὸν τοῦτο κεκλημένον παρέξεται· περὶ δ᾽ αὖ μέθας τυραννεύσασα, τὸν κεκτημένον ταύτῃ ἄγουσα, δῆλον οὗ τεύξεται προσρήματος· καὶ τἆλλα δὴ τὰ τούτων ἀδελφὰ καὶ ἀδελφῶν ἐπιθυμιῶν ὀνόματα τῆς ἀεὶ δυναστευούσης ᾗ προσήκει καλεῖσθαι πρόδηλον. ἧς δ᾽ ἕνεκα πάντα τὰ πρόσθεν εἴρηται, σχεδὸν μὲν ἤδη φανερόν, λεχθὲν δὲ ἢ μὴ λεχθὲν πάντως σαφέστερον· ἡ γὰρ ἄνευ λόγου δόξης ἐπὶ τὸ ὀρθὸν ὁρμώσης κρατήσασα ἐπιθυμία","st":"238b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρὸς ἡδονὴν ἀχθεῖσα κάλλους, καὶ ὑπὸ αὖ τῶν ἑαυτῆς συγγενῶν ἐπιθυμιῶν ἐπὶ σωμάτων κάλλος ἐρρωμένως ῥωσθεῖσα νικήσασα ἀγωγῇ, ἀπ᾽ αὐτῆς τῆς ῥώμης ἐπωνυμίαν λαβοῦσα, ἔρως ἐκλήθη. ἀτάρ, ὦ φίλε Φαῖδρε, δοκῶ τι σοί, ὥσπερ ἐμαυτῷ, θεῖον πάθος πεπονθέναι;","st":"238c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πάνυ μὲν οὖν, ὦ Σώκρατες, παρὰ τὸ εἰωθὸς εὔροιά τίς σε εἴληφεν.","st":"238c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σιγῇ τοίνυν μου ἄκουε. τῷ ὄντι γὰρ θεῖος ἔοικεν","st":"238c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ τόπος εἶναι, ὥστε ἐὰν ἄρα πολλάκις νυμφόληπτος προϊόντος τοῦ λόγου γένωμαι, μὴ θαυμάσῃς· τὰ νῦν γὰρ οὐκέτι πόρρω διθυράμβων φθέγγομαι.","st":"238d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀληθέστατα λέγεις.","st":"238d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων μέντοι σὺ αἴτιος. ἀλλὰ τὰ λοιπὰ ἄκουε· ἴσως γὰρ κἂν ἀποτράποιτο τὸ ἐπιόν. ταῦτα μὲν οὖν θεῷ μελήσει, ἡμῖν δὲ πρὸς τὸν παῖδα πάλιν τῷ λόγῳ ἰτέον. εἶεν, ὦ φέριστε· ὃ μὲν δὴ τυγχάνει ὂν περὶ οὗ βουλευτέον, εἴρηταί τε καὶ ὥρισται, βλέποντες δὲ δὴ πρὸς αὐτὸ","st":"238d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ λοιπὰ λέγωμεν τίς ὠφελία ἢ βλάβη ἀπό τε ἐρῶντος καὶ μὴ τῷ χαριζομένῳ ἐξ εἰκότος συμβήσεται. τῷ δὴ ὑπὸ ἐπιθυμίας ἀρχομένῳ δουλεύοντί τε ἡδονῇ ἀνάγκη που τὸν ἐρώμενον ὡς ἥδιστον ἑαυτῷ παρασκευάζειν· νοσοῦντι δὲ πᾶν ἡδὺ τὸ μὴ ἀντιτεῖνον, κρεῖττον δὲ καὶ ἴσον ἐχθρόν.","st":"238e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔτε δὴ κρείττω οὔτε ἰσούμενον ἑκὼν ἐραστὴς παιδικὰ ἀνέξεται, ἥττω δὲ καὶ ὑποδεέστερον ἀεὶ ἀπεργάζεται· ἥττων δὲ ἀμαθὴς σοφοῦ, δειλὸς ἀνδρείου, ἀδύνατος εἰπεῖν ῥητορικοῦ, βραδὺς ἀγχίνου. τοσούτων κακῶν καὶ ἔτι πλειόνων κατὰ τὴν διάνοιαν ἐραστὴν ἐρωμένῳ ἀνάγκη γιγνομένων τε καὶ φύσει ἐνόντων μὲν ἥδεσθαι, τὰ δὲ παρασκευάζειν, ἢ στέρεσθαι τοῦ παραυτίκα ἡδέος.","st":"239a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι, καὶ πολλῶν μὲν ἄλλων συνουσιῶν ἀπείργοντα καὶ ὠφελίμων ὅθεν ἂν μάλιστ᾽ ἀνὴρ γίγνοιτο, μεγάλης αἴτιον εἶναι βλάβης, μεγίστης δὲ τῆς ὅθεν ἂν φρονιμώτατος εἴη. τοῦτο δὲ ἡ θεία φιλοσοφία τυγχάνει ὄν, ἧς ἐραστὴν παιδικὰ ἀνάγκη πόρρωθεν εἴργειν, περίφοβον ὄντα τοῦ καταφρονηθῆναι· τά τε ἄλλα μηχανᾶσθαι ὅπως ἂν ᾖ πάντα ἀγνοῶν καὶ πάντα ἀποβλέπων εἰς τὸν ἐραστήν, οἷος ὢν τῷ μὲν ἥδιστος, ἑαυτῷ δὲ βλαβερώτατος ἂν εἴη. τὰ μὲν οὖν κατὰ","st":"239b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διάνοιαν ἐπίτροπός τε καὶ κοινωνὸς οὐδαμῇ λυσιτελὴς ἀνὴρ ἔχων ἔρωτα. τὴν δὲ τοῦ σώματος ἕξιν τε καὶ θεραπείαν οἵαν τε καὶ ὡς θεραπεύσει οὗ ἂν γένηται κύριος, ὃς ἡδὺ πρὸ ἀγαθοῦ ἠνάγκασται διώκειν, δεῖ μετὰ ταῦτα ἰδεῖν. ὀφθήσεται δὴ μαλθακόν τινα καὶ οὐ στερεὸν διώκων, οὐδ᾽ ἐν ἡλίῳ καθαρῷ τεθραμμένον ἀλλὰ ὑπὸ συμμιγεῖ σκιᾷ, πόνων μὲν ἀνδρείων καὶ ἱδρώτων ξηρῶν ἄπειρον, ἔμπειρον δὲ ἁπαλῆς καὶ ἀνάνδρου","st":"239c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διαίτης, ἀλλοτρίοις χρώμασι καὶ κόσμοις χήτει οἰκείων κοσμούμενον, ὅσα τε ἄλλα τούτοις ἕπεται πάντα ἐπιτηδεύοντα, ἃ δῆλα καὶ οὐκ ἄξιον περαιτέρω προβαίνειν, ἀλλὰ ἓν κεφάλαιον ὁρισαμένους ἐπ᾽ ἄλλο ἰέναι· τὸ γὰρ τοιοῦτον σῶμα ἐν πολέμῳ τε καὶ ἄλλαις χρείαις ὅσαι μεγάλαι οἱ μὲν ἐχθροὶ θαρροῦσιν, οἱ δὲ φίλοι καὶ αὐτοὶ οἱ ἐρασταὶ φοβοῦνται. τοῦτο μὲν οὖν ὡς δῆλον ἐατέον, τὸ δ᾽ ἐφεξῆς ῥητέον,","st":"239d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίνα ἡμῖν ὠφελίαν ἢ τίνα βλάβην περὶ τὴν κτῆσιν ἡ τοῦ ἐρῶντος ὁμιλία τε καὶ ἐπιτροπεία παρέξεται.","st":"239e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σαφὲς δὴ τοῦτό γε παντὶ μέν, μάλιστα δὲ τῷ ἐραστῇ, ὅτι τῶν φιλτάτων τε καὶ εὐνουστάτων καὶ θειοτάτων κτημάτων ὀρφανὸν πρὸ παντὸς εὔξαιτ᾽ ἂν εἶναι τὸν ἐρώμενον· πατρὸς γὰρ καὶ μητρὸς καὶ συγγενῶν καὶ φίλων στέρεσθαι ἂν αὐτὸν δέξαιτο,","st":"239e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διακωλυτὰς καὶ ἐπιτιμητὰς ἡγούμενος τῆς ἡδίστης πρὸς αὐτὸν ὁμιλίας. ἀλλὰ μὴν οὐσίαν γ᾽ ἔχοντα χρυσοῦ ἤ τινος ἄλλης κτήσεως οὔτε εὐάλωτον ὁμοίως οὔτε ἁλόντα εὐμεταχείριστον ἡγήσεται· ἐξ ὧν πᾶσα ἀνάγκη ἐραστὴν παιδικοῖς φθονεῖν μὲν οὐσίαν κεκτημένοις, ἀπολλυμένης δὲ χαίρειν. ἔτι τοίνυν ἄγαμον, ἄπαιδα, ἄοικον ὅτι πλεῖστον χρόνον παιδικὰ ἐραστὴς εὔξαιτ᾽ ἂν γενέσθαι, τὸ αὑτοῦ γλυκὺ ὡς πλεῖστον χρόνον καρποῦσθαι ἐπιθυμῶν. ἔστι μὲν δὴ καὶ ἄλλα κακά, ἀλλά τις δαίμων ἔμειξε τοῖς","st":"240a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πλείστοις ἐν τῷ παραυτίκα ἡδονήν, οἷον κόλακι, δεινῷ θηρίῳ καὶ βλάβῃ μεγάλῃ, ὅμως ἐπέμειξεν ἡ φύσις ἡδονήν τινα οὐκ ἄμουσον, καί τις ἑταίραν ὡς βλαβερὸν ψέξειεν ἄν, καὶ ἄλλα πολλὰ τῶν τοιουτοτρόπων θρεμμάτων τε καὶ ἐπιτηδευμάτων, οἷς τό γε καθ᾽ ἡμέραν ἡδίστοισιν εἶναι ὑπάρχει· παιδικοῖς δὲ ἐραστὴς πρὸς τῷ βλαβερῷ καὶ εἰς τὸ συνημερεύειν πάντων","st":"240b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀηδέστατον. ἥλικα γὰρ δὴ καὶ ὁ παλαιὸς λόγος τέρπειν τὸν ἥλικα—ἡ γὰρ οἶμαι χρόνου ἰσότης ἐπ᾽ ἴσας ἡδονὰς ἄγουσα δι᾽ ὁμοιότητα φιλίαν παρέχεται—ἀλλ᾽ ὅμως κόρον γε καὶ ἡ τούτων συνουσία ἔχει. καὶ μὴν τό γε ἀναγκαῖον αὖ βαρὺ παντὶ περὶ πᾶν λέγεται· ὃ δὴ πρὸς τῇ ἀνομοιότητι μάλιστα ἐραστὴς πρὸς παιδικὰ ἔχει. νεωτέρῳ γὰρ πρεσβύτερος συνὼν οὔθ᾽ ἡμέρας οὔτε νυκτὸς ἑκὼν ἀπολείπεται, ἀλλ᾽ ὑπ᾽","st":"240c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνάγκης τε καὶ οἴστρου ἐλαύνεται, ὃς ἐκείνῳ μὲν ἡδονὰς ἀεὶ διδοὺς ἄγει, ὁρῶντι, ἀκούοντι, ἁπτομένῳ, καὶ πᾶσαν αἴσθησιν αἰσθανομένῳ τοῦ ἐρωμένου, ὥστε μεθ᾽ ἡδονῆς ἀραρότως αὐτῷ ὑπηρετεῖν· τῷ δὲ δὴ ἐρωμένῳ ποῖον παραμύθιον ἢ τίνας ἡδονὰς διδοὺς ποιήσει τὸν ἴσον χρόνον συνόντα μὴ οὐχὶ ἐπ᾽ ἔσχατον ἐλθεῖν ἀηδίας—ὁρῶντι μὲν ὄψιν πρεσβυτέραν καὶ οὐκ ἐν ὥρᾳ, ἑπομένων δὲ τῶν ἄλλων ταύτῃ, ἃ καὶ λόγῳ","st":"240d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐστὶν ἀκούειν οὐκ ἐπιτερπές, μὴ ὅτι δὴ ἔργῳ ἀνάγκης ἀεὶ προσκειμένης μεταχειρίζεσθαι, φυλακάς τε δὴ καχυποτόπους φυλαττομένῳ διὰ παντὸς καὶ πρὸς ἅπαντας, ἀκαίρους τε ἐπαίνους καὶ ὑπερβάλλοντας ἀκούοντι, ὡς δ᾽ αὕτως ψόγους νήφοντος μὲν οὐκ ἀνεκτούς, εἰς δὲ μέθην ἰόντος πρὸς τῷ μὴ ἀνεκτῷ ἐπαισχεῖς, παρρησίᾳ κατακορεῖ καὶ ἀναπεπταμένῃ χρωμένου;","st":"240e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐρῶν μὲν βλαβερός τε καὶ ἀηδής, λήξας δὲ τοῦ ἔρωτος εἰς τὸν ἔπειτα χρόνον ἄπιστος, εἰς ὃν πολλὰ καὶ μετὰ πολλῶν ὅρκων τε καὶ δεήσεων ὑπισχνούμενος μόγις","st":"240e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κατεῖχε τήν γ᾽ ἐν τῷ τότε συνουσίαν ἐπίπονον οὖσαν φέρειν δι᾽ ἐλπίδα ἀγαθῶν. τότε δὴ δέον ἐκτίνειν, μεταβαλὼν ἄλλον ἄρχοντα ἐν αὑτῷ καὶ προστάτην, νοῦν καὶ σωφροσύνην ἀντ᾽ ἔρωτος καὶ μανίας, ἄλλος γεγονὼς λέληθεν τὰ παιδικά. καὶ ὁ μὲν αὐτὸν χάριν ἀπαιτεῖ τῶν τότε, ὑπομιμνῄσκων τὰ πραχθέντα καὶ λεχθέντα, ὡς τῷ αὐτῷ διαλεγόμενος· ὁ δὲ ὑπ᾽ αἰσχύνης οὔτε εἰπεῖν τολμᾷ ὅτι ἄλλος γέγονεν, οὔθ᾽ ὅπως τὰ τῆς προτέρας ἀνοήτου ἀρχῆς ὁρκωμόσιά τε καὶ ὑποσχέσεις","st":"241a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμπεδώσῃ ἔχει, νοῦν ἤδη ἐσχηκὼς καὶ σεσωφρονηκώς, ἵνα μὴ πράττων ταὐτὰ τῷ πρόσθεν ὅμοιός τε ἐκείνῳ καὶ ὁ αὐτὸς πάλιν γένηται. φυγὰς δὴ γίγνεται ἐκ τούτων, καὶ ἀπεστερηκὼς ὑπ᾽ ἀνάγκης ὁ πρὶν ἐραστής, ὀστράκου μεταπεσόντος, ἵεται φυγῇ μεταβαλών· ὁ δὲ ἀναγκάζεται διώκειν ἀγανακτῶν καὶ ἐπιθεάζων, ἠγνοηκὼς τὸ ἅπαν ἐξ ἀρχῆς, ὅτι οὐκ ἄρα ἔδει ποτὲ ἐρῶντι καὶ ὑπ᾽ ἀνάγκης ἀνοήτῳ χαρίζεσθαι,","st":"241b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ πολὺ μᾶλλον μὴ ἐρῶντι καὶ νοῦν ἔχοντι· εἰ δὲ μή, ἀναγκαῖον εἴη ἐνδοῦναι αὑτὸν ἀπίστῳ, δυσκόλῳ, φθονερῷ, ἀηδεῖ, βλαβερῷ μὲν πρὸς οὐσίαν, βλαβερῷ δὲ πρὸς τὴν τοῦ σώματος ἕξιν, πολὺ δὲ βλαβερωτάτῳ πρὸς τὴν τῆς ψυχῆς παίδευσιν, ἧς οὔτε ἀνθρώποις οὔτε θεοῖς τῇ ἀληθείᾳ τιμιώτερον οὔτε ἔστιν οὔτε ποτὲ ἔσται. ταῦτά τε οὖν χρή, ὦ παῖ, συννοεῖν, καὶ εἰδέναι τὴν ἐραστοῦ φιλίαν ὅτι οὐ μετ᾽ εὐνοίας γίγνεται, ἀλλὰ σιτίου τρόπον, χάριν πλησμονῆς,","st":"241c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς λύκοι ἄρνας ἀγαπῶσιν, ὣς παῖδα φιλοῦσιν ἐρασταί. τοῦτ᾽ ἐκεῖνο, ὦ Φαῖδρε. οὐκέτ᾽ ἂν τὸ πέρα ἀκούσαις ἐμοῦ λέγοντος, ἀλλ᾽ ἤδη σοι τέλος ἐχέτω ὁ λόγος.","st":"241d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καίτοι ᾤμην γε μεσοῦν αὐτόν, καὶ ἐρεῖν τὰ ἴσα περὶ τοῦ μὴ ἐρῶντος, ὡς δεῖ ἐκείνῳ χαρίζεσθαι μᾶλλον, λέγων ὅσα αὖ ἔχει ἀγαθά· νῦν δὲ δή, ὦ Σώκρατες, τί ἀποπαύῃ;","st":"241d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ᾔσθου, ὦ μακάριε, ὅτι ἤδη ἔπη φθέγγομαι ἀλλ᾽ οὐκέτι διθυράμβους, καὶ ταῦτα ψέγων; ἐὰν δ᾽ ἐπαινεῖν τὸν ἕτερον ἄρξωμαι, τί με οἴει ποιήσειν; ἆρ᾽ οἶσθ᾽ ὅτι ὑπὸ τῶν Νυμφῶν, αἷς με σὺ προύβαλες ἐκ προνοίας, σαφῶς ἐνθουσιάσω; λέγω οὖν ἑνὶ λόγῳ ὅτι ὅσα τὸν ἕτερον λελοιδορήκαμεν, τῷ ἑτέρῳ τἀναντία τούτων ἀγαθὰ πρόσεστιν. καὶ τί δεῖ μακροῦ λόγου; περὶ γὰρ ἀμφοῖν ἱκανῶς εἴρηται.","st":"241e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ οὕτω δὴ ὁ μῦθος ὅτι πάσχειν προσήκει αὐτῷ, τοῦτο","st":"241e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πείσεται· κἀγὼ τὸν ποταμὸν τοῦτον διαβὰς ἀπέρχομαι πρὶν ὑπὸ σοῦ τι μεῖζον ἀναγκασθῆναι.","st":"242a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> μήπω γε, ὦ Σώκρατες, πρὶν ἂν τὸ καῦμα παρέλθῃ. ἢ οὐχ ὁρᾷς ὡς σχεδὸν ἤδη μεσημβρία ἵσταται ἡ δὴ καλουμένη σταθερά; ἀλλὰ περιμείναντες καὶ ἅμα περὶ τῶν εἰρημένων διαλεχθέντες, τάχα ἐπειδὰν ἀποψυχῇ ἴμεν.","st":"242a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> θεῖός γ᾽ εἶ περὶ τοὺς λόγους, ὦ Φαῖδρε, καὶ ἀτεχνῶς θαυμάσιος. οἶμαι γὰρ ἐγὼ τῶν ἐπὶ τοῦ σοῦ βίου γεγονότων","st":"242a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λόγων μηδένα πλείους ἢ σὲ πεποιηκέναι γεγενῆσθαι ἤτοι αὐτὸν λέγοντα ἢ ἄλλους ἑνί γέ τῳ τρόπῳ προσαναγκάζοντα —Σιμμίαν Θηβαῖον ἐξαιρῶ λόγου· τῶν δὲ ἄλλων πάμπολυ κρατεῖς—καὶ νῦν αὖ δοκεῖς αἴτιός μοι γεγενῆσθαι λόγῳ τινὶ ῥηθῆναι.","st":"242b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐ πόλεμόν γε ἀγγέλλεις. ἀλλὰ πῶς δὴ καὶ τίνι τούτῳ;","st":"242b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡνίκ᾽ ἔμελλον, ὠγαθέ, τὸν ποταμὸν διαβαίνειν, τὸ δαιμόνιόν τε καὶ τὸ εἰωθὸς σημεῖόν μοι γίγνεσθαι ἐγένετο","st":"242b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> —ἀεὶ δέ με ἐπίσχει ὃ ἂν μέλλω πράττειν—καί τινα φωνὴν ἔδοξα αὐτόθεν ἀκοῦσαι, ἥ με οὐκ ἐᾷ ἀπιέναι πρὶν ἂν ἀφοσιώσωμαι, ὡς δή τι ἡμαρτηκότα εἰς τὸ θεῖον. εἰμὶ δὴ οὖν μάντις μέν, οὐ πάνυ δὲ σπουδαῖος, ἀλλ᾽ ὥσπερ οἱ τὰ γράμματα φαῦλοι, ὅσον μὲν ἐμαυτῷ μόνον ἱκανός· σαφῶς οὖν ἤδη μανθάνω τὸ ἁμάρτημα. ὡς δή τοι, ὦ ἑταῖρε, μαντικόν γέ τι καὶ ἡ ψυχή· ἐμὲ γὰρ ἔθραξε μέν τι καὶ πάλαι λέγοντα τὸν λόγον, καί πως ἐδυσωπούμην κατ᾽ Ἴβυκον, μή τι παρὰ θεοῖς","st":"242c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀμβλακὼν τιμὰν πρὸς ἀνθρώπων ἀμείψω·<br>νῦν δ᾽ ᾔσθημαι τὸ ἁμάρτημα.","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λέγεις δὲ δὴ τί;","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεινόν, ὦ Φαῖδρε, δεινὸν λόγον αὐτός τε ἐκόμισας ἐμέ τε ἠνάγκασας εἰπεῖν.","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς δή;","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εὐήθη καὶ ὑπό τι ἀσεβῆ· οὗ τίς ἂν εἴη δεινότερος;","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐδείς, εἴ γε σὺ ἀληθῆ λέγεις.","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; τὸν ἔρωτα οὐκ Ἀφροδίτης καὶ θεόν τινα ἡγῇ;","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λέγεταί γε δή.","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔ τι ὑπό γε Λυσίου, οὐδὲ ὑπὸ τοῦ σοῦ λόγου, ὃς","st":"242d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ τοῦ ἐμοῦ στόματος καταφαρμακευθέντος ὑπὸ σοῦ ἐλέχθη.","st":"242e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ δ᾽ ἔστιν, ὥσπερ οὖν ἔστι, θεὸς ἤ τι θεῖον ὁ Ἔρως, οὐδὲν ἂν κακὸν εἴη, τὼ δὲ λόγω τὼ νυνδὴ περὶ αὐτοῦ εἰπέτην ὡς τοιούτου ὄντος· ταύτῃ τε οὖν ἡμαρτανέτην περὶ τὸν ἔρωτα, ἔτι τε ἡ εὐήθεια αὐτοῖν πάνυ ἀστεία, τὸ μηδὲν ὑγιὲς λέγοντε","st":"242e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μηδὲ ἀληθὲς σεμνύνεσθαι ὡς τὶ ὄντε, εἰ ἄρα ἀνθρωπίσκους τινὰς ἐξαπατήσαντε εὐδοκιμήσετον ἐν αὐτοῖς. ἐμοὶ μὲν οὖν, ὦ φίλε, καθήρασθαι ἀνάγκη· ἔστιν δὲ τοῖς ἁμαρτάνουσι περὶ μυθολογίαν καθαρμὸς ἀρχαῖος, ὃν Ὅμηρος μὲν οὐκ ᾔσθετο, Στησίχορος δέ. τῶν γὰρ ὀμμάτων στερηθεὶς διὰ τὴν Ἑλένης κακηγορίαν οὐκ ἠγνόησεν ὥσπερ Ὅμηρος, ἀλλ᾽ ἅτε μουσικὸς ὢν ἔγνω τὴν αἰτίαν, καὶ ποιεῖ εὐθὺς— οὐκ ἔστ᾽ ἔτυμος λόγος οὗτος,<br>οὐδ᾽ ἔβας ἐν νηυσὶν εὐσέλμοις,<br>","st":"243a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ᾽ ἵκεο Πέργαμα Τροίας·<br>καὶ ποιήσας δὴ πᾶσαν τὴν καλουμένην Παλινῳδίαν παραχρῆμα ἀνέβλεψεν. ἐγὼ οὖν σοφώτερος ἐκείνων γενήσομαι κατ᾽ αὐτό γε τοῦτο· πρὶν γάρ τι παθεῖν διὰ τὴν τοῦ Ἔρωτος κακηγορίαν πειράσομαι αὐτῷ ἀποδοῦναι τὴν παλινῳδίαν, γυμνῇ τῇ κεφαλῇ καὶ οὐχ ὥσπερ τότε ὑπ᾽ αἰσχύνης ἐγκεκαλυμμένος.","st":"243b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τουτωνί, ὦ Σώκρατες, οὐκ ἔστιν ἅττ᾽ ἂν ἐμοὶ εἶπες ἡδίω.","st":"243b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ γάρ, ὠγαθὲ Φαῖδρε, ἐννοεῖς ὡς ἀναιδῶς εἴρησθον τὼ λόγω, οὗτός τε καὶ ὁ ἐκ τοῦ βιβλίου ῥηθείς. εἰ γὰρ ἀκούων τις τύχοι ἡμῶν γεννάδας καὶ πρᾷος τὸ ἦθος, ἑτέρου δὲ τοιούτου ἐρῶν ἢ καὶ πρότερόν ποτε ἐρασθείς, λεγόντων ὡς διὰ σμικρὰ μεγάλας ἔχθρας οἱ ἐρασταὶ ἀναιροῦνται καὶ ἔχουσι πρὸς τὰ παιδικὰ φθονερῶς τε καὶ βλαβερῶς, πῶς οὐκ ἂν οἴει αὐτὸν ἡγεῖσθαι ἀκούειν ἐν ναύταις που τεθραμμένων καὶ οὐδένα ἐλεύθερον ἔρωτα ἑωρακότων, πολλοῦ δ᾽ ἂν δεῖν","st":"243c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡμῖν ὁμολογεῖν ἃ ψέγομεν τὸν ἔρωτα;","st":"243d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἴσως νὴ Δί᾽, ὦ Σώκρατες.","st":"243d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτόν γε τοίνυν ἔγωγε αἰσχυνόμενος, καὶ αὐτὸν τὸν ἔρωτα δεδιώς, ἐπιθυμῶ ποτίμῳ λόγῳ οἷον ἁλμυρὰν ἀκοὴν ἀποκλύσασθαι· συμβουλεύω δὲ καὶ Λυσίᾳ ὅτι τάχιστα γράψαι ὡς χρὴ ἐραστῇ μᾶλλον ἢ μὴ ἐρῶντι ἐκ τῶν ὁμοίων χαρίζεσθαι.","st":"243d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀλλ᾽ εὖ ἴσθι ὅτι ἕξει τοῦθ᾽ οὕτω· σοῦ γὰρ εἰπόντος τὸν τοῦ ἐραστοῦ ἔπαινον, πᾶσα ἀνάγκη Λυσίαν ὑπ᾽ ἐμοῦ","st":"243d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀναγκασθῆναι γράψαι αὖ περὶ τοῦ αὐτοῦ λόγον.","st":"243e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο μὲν πιστεύω, ἕωσπερ ἂν ᾖς ὃς εἶ.","st":"243e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λέγε τοίνυν θαρρῶν.","st":"243e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ποῦ δή μοι ὁ παῖς πρὸς ὃν ἔλεγον; ἵνα καὶ τοῦτο ἀκούσῃ, καὶ μὴ ἀνήκοος ὢν φθάσῃ χαρισάμενος τῷ μὴ ἐρῶντι.","st":"243e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὗτος παρά σοι μάλα πλησίον ἀεὶ πάρεστιν, ὅταν σὺ βούλῃ.","st":"243e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὑτωσὶ τοίνυν, ὦ παῖ καλέ, ἐννόησον, ὡς ὁ μὲν","st":"243e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρότερος ἦν λόγος Φαίδρου τοῦ Πυθοκλέους, Μυρρινουσίου ἀνδρός· ὃν δὲ μέλλω λέγειν, Στησιχόρου τοῦ Εὐφήμου, Ἱμεραίου. λεκτέος δὲ ὧδε, ὅτι οὐκ ἔστ᾽ ἔτυμος λόγος ὃς ἂν παρόντος ἐραστοῦ τῷ μὴ ἐρῶντι μᾶλλον φῇ δεῖν χαρίζεσθαι, διότι δὴ ὁ μὲν μαίνεται, ὁ δὲ σωφρονεῖ. εἰ μὲν γὰρ ἦν ἁπλοῦν τὸ μανίαν κακὸν εἶναι, καλῶς ἂν ἐλέγετο· νῦν δὲ τὰ μέγιστα τῶν ἀγαθῶν ἡμῖν γίγνεται διὰ μανίας, θείᾳ μέντοι δόσει διδομένης. ἥ τε γὰρ δὴ ἐν Δελφοῖς προφῆτις αἵ τ᾽ ἐν","st":"244a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> Δωδώνῃ ἱέρειαι μανεῖσαι μὲν πολλὰ δὴ καὶ καλὰ ἰδίᾳ τε καὶ δημοσίᾳ τὴν Ἑλλάδα ἠργάσαντο, σωφρονοῦσαι δὲ βραχέα ἢ οὐδέν· καὶ ἐὰν δὴ λέγωμεν Σίβυλλάν τε καὶ ἄλλους, ὅσοι μαντικῇ χρώμενοι ἐνθέῳ πολλὰ δὴ πολλοῖς προλέγοντες εἰς τὸ μέλλον ὤρθωσαν, μηκύνοιμεν ἂν δῆλα παντὶ λέγοντες. τόδε μὴν ἄξιον ἐπιμαρτύρασθαι, ὅτι καὶ τῶν παλαιῶν οἱ τὰ ὀνόματα τιθέμενοι οὐκ αἰσχρὸν ἡγοῦντο οὐδὲ ὄνειδος μανίαν·","st":"244b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γὰρ ἂν τῇ καλλίστῃ τέχνῃ, ᾗ τὸ μέλλον κρίνεται, αὐτὸ τοῦτο τοὔνομα ἐμπλέκοντες μανικὴν ἐκάλεσαν. ἀλλ᾽ ὡς καλοῦ ὄντος, ὅταν θείᾳ μοίρᾳ γίγνηται, οὕτω νομίσαντες ἔθεντο, οἱ δὲ νῦν ἀπειροκάλως τὸ ταῦ ἐπεμβάλλοντες μαντικὴν ἐκάλεσαν. ἐπεὶ καὶ τήν γε τῶν ἐμφρόνων, ζήτησιν τοῦ μέλλοντος διά τε ὀρνίθων ποιουμένων καὶ τῶν ἄλλων σημείων, ἅτ᾽ ἐκ διανοίας ποριζομένων ἀνθρωπίνῃ οἰήσει νοῦν τε καὶ ἱστορίαν, οἰονοϊστικὴν ἐπωνόμασαν,","st":"244c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἣν νῦν οἰωνιστικὴν τῷ ω σεμνύνοντες οἱ νέοι καλοῦσιν· ὅσῳ δὴ οὖν τελεώτερον καὶ ἐντιμότερον μαντικὴ οἰωνιστικῆς, τό τε ὄνομα τοῦ ὀνόματος ἔργον τ᾽ ἔργου, τόσῳ κάλλιον μαρτυροῦσιν οἱ παλαιοὶ μανίαν σωφροσύνης τὴν ἐκ θεοῦ τῆς παρ᾽ ἀνθρώπων γιγνομένης. ἀλλὰ μὴν νόσων γε καὶ πόνων τῶν μεγίστων, ἃ δὴ παλαιῶν ἐκ μηνιμάτων ποθὲν ἔν τισι τῶν γενῶν ἡ μανία ἐγγενομένη καὶ προφητεύσασα, οἷς ἔδει","st":"244d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀπαλλαγὴν ηὕρετο, καταφυγοῦσα πρὸς θεῶν εὐχάς τε καὶ λατρείας, ὅθεν δὴ καθαρμῶν τε καὶ τελετῶν τυχοῦσα ἐξάντη ἐποίησε τὸν ἔχοντα πρός τε τὸν παρόντα καὶ τὸν ἔπειτα χρόνον, λύσιν τῷ ὀρθῶς μανέντι τε καὶ κατασχομένῳ","st":"244e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῶν παρόντων κακῶν εὑρομένη.","st":"245a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τρίτη δὲ ἀπὸ Μουσῶν κατοκωχή τε καὶ μανία, λαβοῦσα ἁπαλὴν καὶ ἄβατον ψυχήν, ἐγείρουσα καὶ ἐκβακχεύουσα κατά τε ᾠδὰς καὶ κατὰ τὴν ἄλλην ποίησιν, μυρία τῶν παλαιῶν ἔργα κοσμοῦσα τοὺς ἐπιγιγνομένους παιδεύει· ὃς δ᾽ ἂν ἄνευ μανίας Μουσῶν ἐπὶ ποιητικὰς θύρας ἀφίκηται, πεισθεὶς ὡς ἄρα ἐκ τέχνης ἱκανὸς ποιητὴς ἐσόμενος, ἀτελὴς αὐτός τε καὶ ἡ ποίησις ὑπὸ τῆς τῶν μαινομένων ἡ τοῦ σωφρονοῦντος ἠφανίσθη.","st":"245a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοσαῦτα μέν σοι καὶ ἔτι πλείω ἔχω μανίας γιγνομένης ἀπὸ θεῶν λέγειν καλὰ ἔργα. ὥστε τοῦτό γε αὐτὸ μὴ φοβώμεθα, μηδέ τις ἡμᾶς λόγος θορυβείτω δεδιττόμενος ὡς πρὸ τοῦ κεκινημένου τὸν σώφρονα δεῖ προαιρεῖσθαι φίλον· ἀλλὰ τόδε πρὸς ἐκείνῳ δείξας φερέσθω τὰ νικητήρια, ὡς οὐκ ἐπ᾽ ὠφελίᾳ ὁ ἔρως τῷ ἐρῶντι καὶ τῷ ἐρωμένῳ ἐκ θεῶν ἐπιπέμπεται. ἡμῖν δὲ ἀποδεικτέον αὖ τοὐναντίον, ὡς ἐπ᾽ εὐτυχίᾳ τῇ μεγίστῃ","st":"245b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παρὰ θεῶν ἡ τοιαύτη μανία δίδοται· ἡ δὲ δὴ ἀπόδειξις ἔσται δεινοῖς μὲν ἄπιστος, σοφοῖς δὲ πιστή. δεῖ οὖν πρῶτον ψυχῆς φύσεως πέρι θείας τε καὶ ἀνθρωπίνης ἰδόντα πάθη τε καὶ ἔργα τἀληθὲς νοῆσαι· ἀρχὴ δὲ ἀποδείξεως ἥδε. ψυχὴ πᾶσα ἀθάνατος. τὸ γὰρ ἀεικίνητον ἀθάνατον· τὸ δ᾽ ἄλλο κινοῦν καὶ ὑπ᾽ ἄλλου κινούμενον, παῦλαν ἔχον κινήσεως, παῦλαν ἔχει ζωῆς. μόνον δὴ τὸ αὑτὸ κινοῦν, ἅτε οὐκ ἀπολεῖπον ἑαυτό, οὔποτε λήγει κινούμενον, ἀλλὰ καὶ τοῖς ἄλλοις ὅσα κινεῖται τοῦτο πηγὴ καὶ ἀρχὴ κινήσεως.","st":"245c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀρχὴ δὲ ἀγένητον. ἐξ ἀρχῆς γὰρ ἀνάγκη πᾶν τὸ γιγνόμενον γίγνεσθαι, αὐτὴν δὲ μηδ᾽ ἐξ ἑνός· εἰ γὰρ ἔκ του ἀρχὴ γίγνοιτο, οὐκ ἂν ἔτι ἀρχὴ γίγνοιτο. ἐπειδὴ δὲ ἀγένητόν ἐστιν, καὶ ἀδιάφθορον αὐτὸ ἀνάγκη εἶναι. ἀρχῆς γὰρ δὴ ἀπολομένης οὔτε αὐτή ποτε ἔκ του οὔτε ἄλλο ἐξ ἐκείνης γενήσεται, εἴπερ ἐξ ἀρχῆς δεῖ τὰ πάντα γίγνεσθαι. οὕτω δὴ κινήσεως μὲν ἀρχὴ τὸ αὐτὸ αὑτὸ κινοῦν. τοῦτο δὲ οὔτ᾽ ἀπόλλυσθαι οὔτε γίγνεσθαι δυνατόν, ἢ πάντα τε οὐρανὸν","st":"245d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πᾶσάν τε γῆν εἰς ἓν συμπεσοῦσαν στῆναι καὶ μήποτε αὖθις ἔχειν ὅθεν κινηθέντα γενήσεται. ἀθανάτου δὲ πεφασμένου τοῦ ὑφ᾽ ἑαυτοῦ κινουμένου, ψυχῆς οὐσίαν τε καὶ λόγον τοῦτον αὐτόν τις λέγων οὐκ αἰσχυνεῖται.","st":"245e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πᾶν γὰρ σῶμα, ᾧ μὲν ἔξωθεν τὸ κινεῖσθαι, ἄψυχον, ᾧ δὲ ἔνδοθεν αὐτῷ ἐξ αὑτοῦ, ἔμψυχον, ὡς ταύτης οὔσης φύσεως ψυχῆς· εἰ δ᾽ ἔστιν τοῦτο οὕτως ἔχον, μὴ ἄλλο τι εἶναι τὸ αὐτὸ ἑαυτὸ","st":"245e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κινοῦν ἢ ψυχήν, ἐξ ἀνάγκης ἀγένητόν τε καὶ ἀθάνατον ψυχὴ ἂν εἴη. περὶ μὲν οὖν ἀθανασίας αὐτῆς ἱκανῶς· περὶ δὲ τῆς ἰδέας αὐτῆς ὧδε λεκτέον. οἷον μέν ἐστι, πάντῃ πάντως θείας εἶναι καὶ μακρᾶς διηγήσεως, ᾧ δὲ ἔοικεν, ἀνθρωπίνης τε καὶ ἐλάττονος· ταύτῃ οὖν λέγωμεν. ἐοικέτω δὴ συμφύτῳ δυνάμει ὑποπτέρου ζεύγους τε καὶ ἡνιόχου. θεῶν μὲν οὖν ἵπποι τε καὶ ἡνίοχοι πάντες αὐτοί τε ἀγαθοὶ καὶ ἐξ ἀγαθῶν,","st":"246a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δὲ τῶν ἄλλων μέμεικται. καὶ πρῶτον μὲν ἡμῶν ὁ ἄρχων συνωρίδος ἡνιοχεῖ, εἶτα τῶν ἵππων ὁ μὲν αὐτῷ καλός τε καὶ ἀγαθὸς καὶ ἐκ τοιούτων, ὁ δ᾽ ἐξ ἐναντίων τε καὶ ἐναντίος· χαλεπὴ δὴ καὶ δύσκολος ἐξ ἀνάγκης ἡ περὶ ἡμᾶς ἡνιόχησις. πῇ δὴ οὖν θνητόν τε καὶ ἀθάνατον ζῷον ἐκλήθη πειρατέον εἰπεῖν. ψυχὴ πᾶσα παντὸς ἐπιμελεῖται τοῦ ἀψύχου, πάντα δὲ οὐρανὸν περιπολεῖ, ἄλλοτ᾽ ἐν ἄλλοις εἴδεσι γιγνομένη. τελέα","st":"246b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὲν οὖν οὖσα καὶ ἐπτερωμένη μετεωροπορεῖ τε καὶ πάντα τὸν κόσμον διοικεῖ, ἡ δὲ πτερορρυήσασα φέρεται ἕως ἂν στερεοῦ τινος ἀντιλάβηται, οὗ κατοικισθεῖσα, σῶμα γήϊνον λαβοῦσα, αὐτὸ αὑτὸ δοκοῦν κινεῖν διὰ τὴν ἐκείνης δύναμιν, ζῷον τὸ σύμπαν ἐκλήθη, ψυχὴ καὶ σῶμα παγέν, θνητόν τ᾽ ἔσχεν ἐπωνυμίαν· ἀθάνατον δὲ οὐδ᾽ ἐξ ἑνὸς λόγου λελογισμένου, ἀλλὰ πλάττομεν οὔτε ἰδόντες οὔτε ἱκανῶς νοήσαντες","st":"246c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> θεόν, ἀθάνατόν τι ζῷον, ἔχον μὲν ψυχήν, ἔχον δὲ σῶμα, τὸν ἀεὶ δὲ χρόνον ταῦτα συμπεφυκότα. ἀλλὰ ταῦτα μὲν δή, ὅπῃ τῷ θεῷ φίλον, ταύτῃ ἐχέτω τε καὶ λεγέσθω· τὴν δὲ αἰτίαν τῆς τῶν πτερῶν ἀποβολῆς, δι᾽ ἣν ψυχῆς ἀπορρεῖ, λάβωμεν. ἔστι δέ τις τοιάδε. πέφυκεν ἡ πτεροῦ δύναμις τὸ ἐμβριθὲς ἄγειν ἄνω μετεωρίζουσα ᾗ τὸ τῶν θεῶν γένος οἰκεῖ, κεκοινώνηκε δέ πῃ μάλιστα τῶν περὶ τὸ σῶμα τοῦ θείου , τὸ δὲ θεῖον","st":"246d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλόν, σοφόν, ἀγαθόν, καὶ πᾶν ὅτι τοιοῦτον· τούτοις δὴ τρέφεταί τε καὶ αὔξεται μάλιστά γε τὸ τῆς ψυχῆς πτέρωμα, αἰσχρῷ δὲ καὶ κακῷ καὶ τοῖς ἐναντίοις φθίνει τε καὶ διόλλυται.","st":"246e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ μὲν δὴ μέγας ἡγεμὼν ἐν οὐρανῷ Ζεύς, ἐλαύνων πτηνὸν ἅρμα, πρῶτος πορεύεται, διακοσμῶν πάντα καὶ ἐπιμελούμενος· τῷ δ᾽ ἕπεται στρατιὰ θεῶν τε καὶ δαιμόνων,","st":"246e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κατὰ ἕνδεκα μέρη κεκοσμημένη. μένει γὰρ Ἑστία ἐν θεῶν οἴκῳ μόνη· τῶν δὲ ἄλλων ὅσοι ἐν τῷ τῶν δώδεκα ἀριθμῷ τεταγμένοι θεοὶ ἄρχοντες ἡγοῦνται κατὰ τάξιν ἣν ἕκαστος ἐτάχθη. πολλαὶ μὲν οὖν καὶ μακάριαι θέαι τε καὶ διέξοδοι ἐντὸς οὐρανοῦ, ἃς θεῶν γένος εὐδαιμόνων ἐπιστρέφεται πράττων ἕκαστος αὐτῶν τὸ αὑτοῦ, ἕπεται δὲ ὁ ἀεὶ ἐθέλων τε καὶ δυνάμενος· φθόνος γὰρ ἔξω θείου χοροῦ ἵσταται. ὅταν δὲ δὴ πρὸς δαῖτα καὶ ἐπὶ θοίνην ἴωσιν, ἄκραν ἐπὶ τὴν","st":"247a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὑπουράνιον ἁψῖδα πορεύονται πρὸς ἄναντες, ᾗ δὴ τὰ μὲν θεῶν ὀχήματα ἰσορρόπως εὐήνια ὄντα ῥᾳδίως πορεύεται, τὰ δὲ ἄλλα μόγις· βρίθει γὰρ ὁ τῆς κάκης ἵππος μετέχων, ἐπὶ τὴν γῆν ῥέπων τε καὶ βαρύνων ᾧ μὴ καλῶς ἦν τεθραμμένος τῶν ἡνιόχων. ἔνθα δὴ πόνος τε καὶ ἀγὼν ἔσχατος ψυχῇ πρόκειται. αἱ μὲν γὰρ ἀθάνατοι καλούμεναι, ἡνίκ᾽ ἂν πρὸς ἄκρῳ γένωνται, ἔξω πορευθεῖσαι ἔστησαν ἐπὶ τῷ τοῦ οὐρανοῦ","st":"247b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νώτῳ, στάσας δὲ αὐτὰς περιάγει ἡ περιφορά, αἱ δὲ θεωροῦσι τὰ ἔξω τοῦ οὐρανοῦ. τὸν δὲ ὑπερουράνιον τόπον οὔτε τις ὕμνησέ πω τῶν τῇδε ποιητὴς οὔτε ποτὲ ὑμνήσει κατ᾽ ἀξίαν. ἔχει δὲ ὧδε—τολμητέον γὰρ οὖν τό γε ἀληθὲς εἰπεῖν, ἄλλως τε καὶ περὶ ἀληθείας λέγοντα—ἡ γὰρ ἀχρώματός τε καὶ ἀσχημάτιστος καὶ ἀναφὴς οὐσία ὄντως οὖσα, ψυχῆς κυβερνήτῃ μόνῳ θεατὴ νῷ, περὶ ἣν τὸ τῆς ἀληθοῦς ἐπιστήμης γένος, τοῦτον ἔχει","st":"247c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν τόπον. ἅτ᾽ οὖν θεοῦ διάνοια νῷ τε καὶ ἐπιστήμῃ ἀκηράτῳ τρεφομένη, καὶ ἁπάσης ψυχῆς ὅσῃ ἂν μέλῃ τὸ προσῆκον δέξασθαι, ἰδοῦσα διὰ χρόνου τὸ ὂν ἀγαπᾷ τε καὶ θεωροῦσα τἀληθῆ τρέφεται καὶ εὐπαθεῖ, ἕως ἂν κύκλῳ ἡ περιφορὰ εἰς ταὐτὸν περιενέγκῃ. ἐν δὲ τῇ περιόδῳ καθορᾷ μὲν αὐτὴν δικαιοσύνην, καθορᾷ δὲ σωφροσύνην, καθορᾷ δὲ ἐπιστήμην, οὐχ ᾗ γένεσις πρόσεστιν, οὐδ᾽ ἥ ἐστίν που ἑτέρα","st":"247d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν ἑτέρῳ οὖσα ὧν ἡμεῖς νῦν ὄντων καλοῦμεν, ἀλλὰ τὴν ἐν τῷ ὅ ἐστιν ὂν ὄντως ἐπιστήμην οὖσαν· καὶ τἆλλα ὡσαύτως τὰ ὄντα ὄντως θεασαμένη καὶ ἑστιαθεῖσα, δῦσα πάλιν εἰς τὸ εἴσω τοῦ οὐρανοῦ, οἴκαδε ἦλθεν. ἐλθούσης δὲ αὐτῆς ὁ ἡνίοχος πρὸς τὴν φάτνην τοὺς ἵππους στήσας παρέβαλεν ἀμβροσίαν τε καὶ ἐπ᾽ αὐτῇ νέκταρ ἐπότισεν.","st":"247e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ οὗτος μὲν θεῶν βίος· αἱ δὲ ἄλλαι ψυχαί, ἡ μὲν ἄριστα θεῷ ἑπομένη καὶ εἰκασμένη ὑπερῆρεν εἰς τὸν ἔξω τόπον τὴν τοῦ ἡνιόχου κεφαλήν, καὶ συμπεριηνέχθη τὴν περιφοράν, θορυβουμένη ὑπὸ τῶν ἵππων καὶ μόγις καθορῶσα τὰ ὄντα· ἡ δὲ τοτὲ μὲν ἦρεν, τοτὲ δ᾽ ἔδυ, βιαζομένων δὲ τῶν ἵππων τὰ μὲν εἶδεν, τὰ δ᾽ οὔ. αἱ δὲ δὴ ἄλλαι γλιχόμεναι μὲν ἅπασαι τοῦ ἄνω ἕπονται, ἀδυνατοῦσαι δέ, ὑποβρύχιαι συμπεριφέρονται, πατοῦσαι ἀλλήλας καὶ ἐπιβάλλουσαι, ἑτέρα","st":"248a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρὸ τῆς ἑτέρας πειρωμένη γενέσθαι. θόρυβος οὖν καὶ ἅμιλλα καὶ ἱδρὼς ἔσχατος γίγνεται, οὗ δὴ κακίᾳ ἡνιόχων πολλαὶ μὲν χωλεύονται, πολλαὶ δὲ πολλὰ πτερὰ θραύονται· πᾶσαι δὲ πολὺν ἔχουσαι πόνον ἀτελεῖς τῆς τοῦ ὄντος θέας ἀπέρχονται, καὶ ἀπελθοῦσαι τροφῇ δοξαστῇ χρῶνται. οὗ δ᾽ ἕνεχ᾽ ἡ πολλὴ σπουδὴ τὸ ἀληθείας ἰδεῖν πεδίον οὗ ἐστιν, ἥ τε δὴ προσήκουσα ψυχῆς τῷ ἀρίστῳ νομὴ ἐκ τοῦ ἐκεῖ","st":"248b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λειμῶνος τυγχάνει οὖσα, ἥ τε τοῦ πτεροῦ φύσις, ᾧ ψυχὴ κουφίζεται, τούτῳ τρέφεται. θεσμός τε Ἀδραστείας ὅδε. ἥτις ἂν ψυχὴ θεῷ συνοπαδὸς γενομένη κατίδῃ τι τῶν ἀληθῶν, μέχρι τε τῆς ἑτέρας περιόδου εἶναι ἀπήμονα, κἂν ἀεὶ τοῦτο δύνηται ποιεῖν, ἀεὶ ἀβλαβῆ εἶναι· ὅταν δὲ ἀδυνατήσασα ἐπισπέσθαι μὴ ἴδῃ, καί τινι συντυχίᾳ χρησαμένη λήθης τε καὶ κακίας πλησθεῖσα βαρυνθῇ, βαρυνθεῖσα δὲ πτερορρυήσῃ τε καὶ ἐπὶ τὴν γῆν πέσῃ, τότε νόμος ταύτην","st":"248c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μὴ φυτεῦσαι εἰς μηδεμίαν θήρειον φύσιν ἐν τῇ πρώτῃ γενέσει, ἀλλὰ τὴν μὲν πλεῖστα ἰδοῦσαν εἰς γονὴν ἀνδρὸς γενησομένου φιλοσόφου ἢ φιλοκάλου ἢ μουσικοῦ τινος καὶ ἐρωτικοῦ, τὴν δὲ δευτέραν εἰς βασιλέως ἐννόμου ἢ πολεμικοῦ καὶ ἀρχικοῦ, τρίτην εἰς πολιτικοῦ ἤ τινος οἰκονομικοῦ ἢ χρηματιστικοῦ, τετάρτην εἰς φιλοπόνου ἢ γυμναστικοῦ ἢ περὶ σώματος ἴασίν τινος ἐσομένου, πέμπτην μαντικὸν βίον","st":"248d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἤ τινα τελεστικὸν ἕξουσαν· ἕκτῃ ποιητικὸς ἢ τῶν περὶ μίμησίν τις ἄλλος ἁρμόσει, ἑβδόμῃ δημιουργικὸς ἢ γεωργικός, ὀγδόῃ σοφιστικὸς ἢ δημοκοπικός, ἐνάτῃ τυραννικός.","st":"248e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν δὴ τούτοις ἅπασιν ὃς μὲν ἂν δικαίως διαγάγῃ ἀμείνονος μοίρας μεταλαμβάνει, ὃς δ᾽ ἂν ἀδίκως, χείρονος· εἰς μὲν γὰρ τὸ αὐτὸ ὅθεν ἥκει ἡ ψυχὴ ἑκάστη οὐκ ἀφικνεῖται ἐτῶν μυρίων—","st":"248e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γὰρ πτεροῦται πρὸ τοσούτου χρόνου—πλὴν ἡ τοῦ φιλοσοφήσαντος ἀδόλως ἢ παιδεραστήσαντος μετὰ φιλοσοφίας, αὗται δὲ τρίτῃ περιόδῳ τῇ χιλιετεῖ, ἐὰν ἕλωνται τρὶς ἐφεξῆς τὸν βίον τοῦτον, οὕτω πτερωθεῖσαι τρισχιλιοστῷ ἔτει ἀπέρχονται. αἱ δὲ ἄλλαι, ὅταν τὸν πρῶτον βίον τελευτήσωσιν, κρίσεως ἔτυχον, κριθεῖσαι δὲ αἱ μὲν εἰς τὰ ὑπὸ γῆς δικαιωτήρια ἐλθοῦσαι δίκην ἐκτίνουσιν, αἱ δ᾽ εἰς τοὐρανοῦ τινα τόπον ὑπὸ τῆς Δίκης κουφισθεῖσαι διάγουσιν ἀξίως οὗ ἐν","st":"249a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνθρώπου εἴδει ἐβίωσαν βίου. τῷ δὲ χιλιοστῷ ἀμφότεραι ἀφικνούμεναι ἐπὶ κλήρωσίν τε καὶ αἵρεσιν τοῦ δευτέρου βίου αἱροῦνται ὃν ἂν θέλῃ ἑκάστη· ἔνθα καὶ εἰς θηρίου βίον ἀνθρωπίνη ψυχὴ ἀφικνεῖται, καὶ ἐκ θηρίου ὅς ποτε ἄνθρωπος ἦν πάλιν εἰς ἄνθρωπον. οὐ γὰρ ἥ γε μήποτε ἰδοῦσα τὴν ἀλήθειαν εἰς τόδε ἥξει τὸ σχῆμα. δεῖ γὰρ ἄνθρωπον συνιέναι κατ᾽ εἶδος λεγόμενον, ἐκ πολλῶν ἰὸν αἰσθήσεων","st":"249b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰς ἓν λογισμῷ συναιρούμενον· τοῦτο δ᾽ ἐστὶν ἀνάμνησις ἐκείνων ἅ ποτ᾽ εἶδεν ἡμῶν ἡ ψυχὴ συμπορευθεῖσα θεῷ καὶ ὑπεριδοῦσα ἃ νῦν εἶναί φαμεν, καὶ ἀνακύψασα εἰς τὸ ὂν ὄντως. διὸ δὴ δικαίως μόνη πτεροῦται ἡ τοῦ φιλοσόφου διάνοια· πρὸς γὰρ ἐκείνοις ἀεί ἐστιν μνήμῃ κατὰ δύναμιν, πρὸς οἷσπερ θεὸς ὢν θεῖός ἐστιν. τοῖς δὲ δὴ τοιούτοις ἀνὴρ ὑπομνήμασιν ὀρθῶς χρώμενος, τελέους ἀεὶ τελετὰς τελούμενος, τέλεος ὄντως μόνος γίγνεται· ἐξιστάμενος δὲ τῶν","st":"249c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀνθρωπίνων σπουδασμάτων καὶ πρὸς τῷ θείῳ γιγνόμενος, νουθετεῖται μὲν ὑπὸ τῶν πολλῶν ὡς παρακινῶν, ἐνθουσιάζων δὲ λέληθεν τοὺς πολλούς. ἔστι δὴ οὖν δεῦρο ὁ πᾶς ἥκων λόγος περὶ τῆς τετάρτης μανίας—ἣν ὅταν τὸ τῇδέ τις ὁρῶν κάλλος, τοῦ ἀληθοῦς ἀναμιμνῃσκόμενος, πτερῶταί τε καὶ ἀναπτερούμενος προθυμούμενος ἀναπτέσθαι, ἀδυνατῶν δέ, ὄρνιθος δίκην βλέπων ἄνω, τῶν κάτω δὲ ἀμελῶν, αἰτίαν ἔχει ὡς μανικῶς διακείμενος—ὡς","st":"249d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄρα αὕτη πασῶν τῶν ἐνθουσιάσεων ἀρίστη τε καὶ ἐξ ἀρίστων τῷ τε ἔχοντι καὶ τῷ κοινωνοῦντι αὐτῆς γίγνεται, καὶ ὅτι ταύτης μετέχων τῆς μανίας ὁ ἐρῶν τῶν καλῶν ἐραστὴς καλεῖται.","st":"249e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καθάπερ γὰρ εἴρηται, πᾶσα μὲν ἀνθρώπου ψυχὴ φύσει τεθέαται τὰ ὄντα, ἢ οὐκ ἂν ἦλθεν","st":"249e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰς τόδε τὸ ζῷον· ἀναμιμνῄσκεσθαι δὲ ἐκ τῶνδε ἐκεῖνα οὐ ῥᾴδιον ἁπάσῃ, οὔτε ὅσαι βραχέως εἶδον τότε τἀκεῖ, οὔθ᾽ αἳ δεῦρο πεσοῦσαι ἐδυστύχησαν, ὥστε ὑπό τινων ὁμιλιῶν ἐπὶ τὸ ἄδικον τραπόμεναι λήθην ὧν τότε εἶδον ἱερῶν ἔχειν. ὀλίγαι δὴ λείπονται αἷς τὸ τῆς μνήμης ἱκανῶς πάρεστιν· αὗται δέ, ὅταν τι τῶν ἐκεῖ ὁμοίωμα ἴδωσιν, ἐκπλήττονται καὶ οὐκέτ᾽ ἐν αὑτῶν γίγνονται, ὃ δ᾽ ἔστι τὸ πάθος ἀγνοοῦσι","st":"250a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διὰ τὸ μὴ ἱκανῶς διαισθάνεσθαι. δικαιοσύνης μὲν οὖν καὶ σωφροσύνης καὶ ὅσα ἄλλα τίμια ψυχαῖς οὐκ ἔνεστι φέγγος οὐδὲν ἐν τοῖς τῇδε ὁμοιώμασιν, ἀλλὰ δι᾽ ἀμυδρῶν ὀργάνων μόγις αὐτῶν καὶ ὀλίγοι ἐπὶ τὰς εἰκόνας ἰόντες θεῶνται τὸ τοῦ εἰκασθέντος γένος· κάλλος δὲ τότ᾽ ἦν ἰδεῖν λαμπρόν, ὅτε σὺν εὐδαίμονι χορῷ μακαρίαν ὄψιν τε καὶ θέαν, ἑπόμενοι μετὰ μὲν Διὸς ἡμεῖς, ἄλλοι δὲ μετ᾽ ἄλλου θεῶν, εἶδόν τε καὶ ἐτελοῦντο τῶν τελετῶν ἣν θέμις λέγειν","st":"250b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μακαριωτάτην, ἣν ὠργιάζομεν ὁλόκληροι μὲν αὐτοὶ ὄντες καὶ ἀπαθεῖς κακῶν ὅσα ἡμᾶς ἐν ὑστέρῳ χρόνῳ ὑπέμενεν, ὁλόκληρα δὲ καὶ ἁπλᾶ καὶ ἀτρεμῆ καὶ εὐδαίμονα φάσματα μυούμενοί τε καὶ ἐποπτεύοντες ἐν αὐγῇ καθαρᾷ, καθαροὶ ὄντες καὶ ἀσήμαντοι τούτου ὃ νῦν δὴ σῶμα περιφέροντες ὀνομάζομεν, ὀστρέου τρόπον δεδεσμευμένοι. ταῦτα μὲν οὖν μνήμῃ κεχαρίσθω, δι᾽ ἣν πόθῳ τῶν τότε νῦν μακρότερα εἴρηται· περὶ δὲ κάλλους, ὥσπερ εἴπομεν,","st":"250c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μετ᾽ ἐκείνων τε ἔλαμπεν ὄν, δεῦρό τ᾽ ἐλθόντες κατειλήφαμεν αὐτὸ διὰ τῆς ἐναργεστάτης αἰσθήσεως τῶν ἡμετέρων στίλβον ἐναργέστατα. ὄψις γὰρ ἡμῖν ὀξυτάτη τῶν διὰ τοῦ σώματος ἔρχεται αἰσθήσεων, ᾗ φρόνησις οὐχ ὁρᾶται—δεινοὺς γὰρ ἂν παρεῖχεν ἔρωτας, εἴ τι τοιοῦτον ἑαυτῆς ἐναργὲς εἴδωλον παρείχετο εἰς ὄψιν ἰόν—καὶ τἆλλα ὅσα ἐραστά· νῦν δὲ κάλλος μόνον ταύτην ἔσχε μοῖραν, ὥστ᾽ ἐκφανέστατον εἶναι","st":"250d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐρασμιώτατον.","st":"250e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ μὲν οὖν μὴ νεοτελὴς ἢ διεφθαρμένος οὐκ ὀξέως ἐνθένδε ἐκεῖσε φέρεται πρὸς αὐτὸ τὸ κάλλος, θεώμενος αὐτοῦ τὴν τῇδε ἐπωνυμίαν, ὥστ᾽ οὐ σέβεται προσορῶν, ἀλλ᾽ ἡδονῇ παραδοὺς τετράποδος νόμον βαίνειν ἐπιχειρεῖ καὶ παιδοσπορεῖν, καὶ ὕβρει προσομιλῶν οὐ δέδοικεν","st":"250e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐδ᾽ αἰσχύνεται παρὰ φύσιν ἡδονὴν διώκων· ὁ δὲ ἀρτιτελής, ὁ τῶν τότε πολυθεάμων, ὅταν θεοειδὲς πρόσωπον ἴδῃ κάλλος εὖ μεμιμημένον ἤ τινα σώματος ἰδέαν, πρῶτον μὲν ἔφριξε καί τι τῶν τότε ὑπῆλθεν αὐτὸν δειμάτων, εἶτα προσορῶν ὡς θεὸν σέβεται, καὶ εἰ μὴ ἐδεδίει τὴν τῆς σφόδρα μανίας δόξαν, θύοι ἂν ὡς ἀγάλματι καὶ θεῷ τοῖς παιδικοῖς. ἰδόντα δ᾽ αὐτὸν οἷον ἐκ τῆς φρίκης μεταβολή τε","st":"251a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἱδρὼς καὶ θερμότης ἀήθης λαμβάνει· δεξάμενος γὰρ τοῦ κάλλους τὴν ἀπορροὴν διὰ τῶν ὀμμάτων ἐθερμάνθη ᾗ ἡ τοῦ πτεροῦ φύσις ἄρδεται, θερμανθέντος δὲ ἐτάκη τὰ περὶ τὴν ἔκφυσιν, ἃ πάλαι ὑπὸ σκληρότητος συμμεμυκότα εἶργε μὴ βλαστάνειν, ἐπιρρυείσης δὲ τῆς τροφῆς ᾤδησέ τε καὶ ὥρμησε φύεσθαι ἀπὸ τῆς ῥίζης ὁ τοῦ πτεροῦ καυλὸς ὑπὸ πᾶν τὸ τῆς ψυχῆς εἶδος· πᾶσα γὰρ ἦν τὸ πάλαι πτερωτή.","st":"251b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ζεῖ οὖν ἐν τούτῳ ὅλη καὶ ἀνακηκίει, καὶ ὅπερ τὸ τῶν ὀδοντοφυούντων πάθος περὶ τοὺς ὀδόντας γίγνεται ὅταν ἄρτι φύωσιν, κνῆσίς τε καὶ ἀγανάκτησις περὶ τὰ οὖλα, ταὐτὸν δὴ πέπονθεν ἡ τοῦ πτεροφυεῖν ἀρχομένου ψυχή· ζεῖ τε καὶ ἀγανακτεῖ καὶ γαργαλίζεται φύουσα τὰ πτερά. ὅταν μὲν οὖν βλέπουσα πρὸς τὸ τοῦ παιδὸς κάλλος, ἐκεῖθεν μέρη ἐπιόντα καὶ ῥέοντ᾽—ἃ δὴ διὰ ταῦτα ἵμερος καλεῖται—δεχομένη ἄρδηταί τε καὶ θερμαίνηται, λωφᾷ τε τῆς ὀδύνης","st":"251c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ γέγηθεν· ὅταν δὲ χωρὶς γένηται καὶ αὐχμήσῃ, τὰ τῶν διεξόδων στόματα ᾗ τὸ πτερὸν ὁρμᾷ, συναυαινόμενα μύσαντα ἀποκλῄει τὴν βλάστην τοῦ πτεροῦ, ἡ δ᾽ ἐντὸς μετὰ τοῦ ἱμέρου ἀποκεκλῃμένη, πηδῶσα οἷον τὰ σφύζοντα, τῇ διεξόδῳ ἐγχρίει ἑκάστη τῇ καθ᾽ αὑτήν, ὥστε πᾶσα κεντουμένη κύκλῳ ἡ ψυχὴ οἰστρᾷ καὶ ὀδυνᾶται, μνήμην δ᾽ αὖ ἔχουσα τοῦ καλοῦ γέγηθεν. ἐκ δὲ ἀμφοτέρων μεμειγμένων ἀδημονεῖ τε τῇ ἀτοπίᾳ τοῦ πάθους καὶ ἀποροῦσα λυττᾷ, καὶ ἐμμανὴς","st":"251d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὖσα οὔτε νυκτὸς δύναται καθεύδειν οὔτε μεθ᾽ ἡμέραν οὗ ἂν ᾖ μένειν, θεῖ δὲ ποθοῦσα ὅπου ἂν οἴηται ὄψεσθαι τὸν ἔχοντα τὸ κάλλος· ἰδοῦσα δὲ καὶ ἐποχετευσαμένη ἵμερον ἔλυσε μὲν τὰ τότε συμπεφραγμένα, ἀναπνοὴν δὲ λαβοῦσα κέντρων τε καὶ ὠδίνων ἔληξεν, ἡδονὴν δ᾽ αὖ ταύτην γλυκυτάτην ἐν τῷ","st":"251e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παρόντι καρποῦται.","st":"252a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅθεν δὴ ἑκοῦσα εἶναι οὐκ ἀπολείπεται, οὐδέ τινα τοῦ καλοῦ περὶ πλείονος ποιεῖται, ἀλλὰ μητέρων τε καὶ ἀδελφῶν καὶ ἑταίρων πάντων λέλησται, καὶ οὐσίας δι᾽ ἀμέλειαν ἀπολλυμένης παρ᾽ οὐδὲν τίθεται, νομίμων δὲ καὶ εὐσχημόνων, οἷς πρὸ τοῦ ἐκαλλωπίζετο, πάντων καταφρονήσασα δουλεύειν ἑτοίμη καὶ κοιμᾶσθαι ὅπου ἂν ἐᾷ τις ἐγγυτάτω τοῦ πόθου· πρὸς γὰρ τῷ σέβεσθαι τὸν τὸ κάλλος","st":"252a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχοντα ἰατρὸν ηὕρηκε μόνον τῶν μεγίστων πόνων. τοῦτο δὲ τὸ πάθος, ὦ παῖ καλέ, πρὸς ὃν δή μοι ὁ λόγος, ἄνθρωποι μὲν ἔρωτα ὀνομάζουσιν, θεοὶ δὲ ὃ καλοῦσιν ἀκούσας εἰκότως διὰ νεότητα γελάσῃ. λέγουσι δὲ οἶμαί τινες Ὁμηριδῶν ἐκ τῶν ἀποθέτων ἐπῶν δύο ἔπη εἰς τὸν ἔρωτα, ὧν τὸ ἕτερον ὑβριστικὸν πάνυ καὶ οὐ σφόδρα τι ἔμμετρον· ὑμνοῦσι δὲ ὧδε—","st":"252b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν δ᾽ ἤτοι θνητοὶ μὲν ἔρωτα καλοῦσι ποτηνόν,<br>ἀθάνατοι δὲ Πτέρωτα, διὰ πτεροφύτορ᾽ ἀνάγκην.<br>τούτοις δὴ ἔξεστι μὲν πείθεσθαι, ἔξεστιν δὲ μή· ὅμως δὲ ἥ γε αἰτία καὶ τὸ πάθος τῶν ἐρώντων τοῦτο ἐκεῖνο τυγχάνει ὄν. τῶν μὲν οὖν Διὸς ὀπαδῶν ὁ ληφθεὶς ἐμβριθέστερον δύναται φέρειν τὸ τοῦ πτερωνύμου ἄχθος· ὅσοι δὲ Ἄρεώς τε θεραπευταὶ καὶ μετ᾽ ἐκείνου περιεπόλουν, ὅταν ὑπ᾽ Ἔρωτος ἁλῶσι καί τι οἰηθῶσιν ἀδικεῖσθαι ὑπὸ τοῦ ἐρωμένου, φονικοὶ καὶ ἕτοιμοι καθιερεύειν αὑτούς τε καὶ τὰ παιδικά.","st":"252c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ οὕτω καθ᾽ ἕκαστον θεόν, οὗ ἕκαστος ἦν χορευτής, ἐκεῖνον τιμῶν τε καὶ μιμούμενος εἰς τὸ δυνατὸν ζῇ, ἕως ἂν ᾖ ἀδιάφθορος καὶ τὴν τῇδε πρώτην γένεσιν βιοτεύῃ, καὶ τούτῳ τῷ τρόπῳ πρός τε τοὺς ἐρωμένους καὶ τοὺς ἄλλους ὁμιλεῖ τε καὶ προσφέρεται. τόν τε οὖν ἔρωτα τῶν καλῶν πρὸς τρόπου ἐκλέγεται ἕκαστος, καὶ ὡς θεὸν αὐτὸν ἐκεῖνον ὄντα ἑαυτῷ οἷον ἄγαλμα τεκταίνεταί τε καὶ κατακοσμεῖ, ὡς","st":"252d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τιμήσων τε καὶ ὀργιάσων. οἱ μὲν δὴ οὖν Διὸς δῖόν τινα εἶναι ζητοῦσι τὴν ψυχὴν τὸν ὑφ᾽ αὑτῶν ἐρώμενον· σκοποῦσιν οὖν εἰ φιλόσοφός τε καὶ ἡγεμονικὸς τὴν φύσιν, καὶ ὅταν αὐτὸν εὑρόντες ἐρασθῶσι, πᾶν ποιοῦσιν ὅπως τοιοῦτος ἔσται.","st":"252e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐὰν οὖν μὴ πρότερον ἐμβεβῶσι τῷ ἐπιτηδεύματι, τότε ἐπιχειρήσαντες μανθάνουσί τε ὅθεν ἄν τι δύνωνται καὶ αὐτοὶ μετέρχονται, ἰχνεύοντες δὲ παρ᾽ ἑαυτῶν ἀνευρίσκειν","st":"252e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὴν τοῦ σφετέρου θεοῦ φύσιν εὐποροῦσι διὰ τὸ συντόνως ἠναγκάσθαι πρὸς τὸν θεὸν βλέπειν, καὶ ἐφαπτόμενοι αὐτοῦ τῇ μνήμῃ ἐνθουσιῶντες ἐξ ἐκείνου λαμβάνουσι τὰ ἔθη καὶ τὰ ἐπιτηδεύματα, καθ᾽ ὅσον δυνατὸν θεοῦ ἀνθρώπῳ μετασχεῖν· καὶ τούτων δὴ τὸν ἐρώμενον αἰτιώμενοι ἔτι τε μᾶλλον ἀγαπῶσι, κἂν ἐκ Διὸς ἀρύτωσιν ὥσπερ αἱ βάκχαι, ἐπὶ τὴν τοῦ ἐρωμένου ψυχὴν ἐπαντλοῦντες ποιοῦσιν ὡς δυνατὸν","st":"253a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁμοιότατον τῷ σφετέρῳ θεῷ. ὅσοι δ᾽ αὖ μεθ᾽ Ἥρας εἵποντο, βασιλικὸν ζητοῦσι, καὶ εὑρόντες περὶ τοῦτον πάντα δρῶσιν τὰ αὐτά. οἱ δὲ Ἀπόλλωνός τε καὶ ἑκάστου τῶν θεῶν οὕτω κατὰ τὸν θεὸν ἰόντες ζητοῦσι τὸν σφέτερον παῖδα πεφυκέναι, καὶ ὅταν κτήσωνται, μιμούμενοι αὐτοί τε καὶ τὰ παιδικὰ πείθοντες καὶ ῥυθμίζοντες εἰς τὸ ἐκείνου ἐπιτήδευμα καὶ ἰδέαν ἄγουσιν, ὅση ἑκάστῳ δύναμις, οὐ φθόνῳ οὐδ᾽ ἀνελευθέρῳ δυσμενείᾳ χρώμενοι πρὸς τὰ παιδικά, ἀλλ᾽ εἰς ὁμοιότητα","st":"253b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὑτοῖς καὶ τῷ θεῷ ὃν ἂν τιμῶσι πᾶσαν πάντως ὅτι μάλιστα πειρώμενοι ἄγειν οὕτω ποιοῦσι. προθυμία μὲν οὖν τῶν ὡς ἀληθῶς ἐρώντων καὶ τελετή, ἐάν γε διαπράξωνται ὃ προθυμοῦνται ᾗ λέγω, οὕτω καλή τε καὶ εὐδαιμονικὴ ὑπὸ τοῦ δι᾽ ἔρωτα μανέντος φίλου τῷ φιληθέντι γίγνεται, ἐὰν αἱρεθῇ· ἁλίσκεται δὲ δὴ ὁ αἱρεθεὶς τοιῷδε τρόπῳ. καθάπερ ἐν ἀρχῇ τοῦδε τοῦ μύθου τριχῇ διείλομεν ψυχὴν ἑκάστην, ἱππομόρφω μὲν δύο τινὲ εἴδη, ἡνιοχικὸν δὲ εἶδος","st":"253c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τρίτον, καὶ νῦν ἔτι ἡμῖν ταῦτα μενέτω. τῶν δὲ δὴ ἵππων ὁ μέν, φαμέν, ἀγαθός, ὁ δ᾽ οὔ· ἀρετὴ δὲ τίς τοῦ ἀγαθοῦ ἢ κακοῦ κακία, οὐ διείπομεν, νῦν δὲ λεκτέον. ὁ μὲν τοίνυν αὐτοῖν ἐν τῇ καλλίονι στάσει ὢν τό τε εἶδος ὀρθὸς καὶ διηρθρωμένος, ὑψαύχην, ἐπίγρυπος, λευκὸς ἰδεῖν, μελανόμματος, τιμῆς ἐραστὴς μετὰ σωφροσύνης τε καὶ αἰδοῦς, καὶ ἀληθινῆς δόξης ἑταῖρος, ἄπληκτος, κελεύσματι μόνον καὶ","st":"253d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λόγῳ ἡνιοχεῖται· ὁ δ᾽ αὖ σκολιός, πολύς, εἰκῇ συμπεφορημένος, κρατεραύχην, βραχυτράχηλος, σιμοπρόσωπος, μελάγχρως, γλαυκόμματος, ὕφαιμος, ὕβρεως καὶ ἀλαζονείας ἑταῖρος, περὶ ὦτα λάσιος, κωφός, μάστιγι μετὰ κέντρων μόγις ὑπείκων.","st":"253e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν δ᾽ οὖν ὁ ἡνίοχος ἰδὼν τὸ ἐρωτικὸν ὄμμα, πᾶσαν αἰσθήσει διαθερμήνας τὴν ψυχήν, γαργαλισμοῦ τε καὶ πόθου","st":"253e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κέντρων ὑποπλησθῇ, ὁ μὲν εὐπειθὴς τῷ ἡνιόχῳ τῶν ἵππων, ἀεί τε καὶ τότε αἰδοῖ βιαζόμενος, ἑαυτὸν κατέχει μὴ ἐπιπηδᾶν τῷ ἐρωμένῳ· ὁ δὲ οὔτε κέντρων ἡνιοχικῶν οὔτε μάστιγος ἔτι ἐντρέπεται, σκιρτῶν δὲ βίᾳ φέρεται, καὶ πάντα πράγματα παρέχων τῷ σύζυγί τε καὶ ἡνιόχῳ ἀναγκάζει ἰέναι τε πρὸς τὰ παιδικὰ καὶ μνείαν ποιεῖσθαι τῆς τῶν ἀφροδισίων χάριτος. τὼ δὲ κατ᾽ ἀρχὰς μὲν ἀντιτείνετον","st":"254a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀγανακτοῦντε, ὡς δεινὰ καὶ παράνομα ἀναγκαζομένω· τελευτῶντε δέ, ὅταν μηδὲν ᾖ πέρας κακοῦ, πορεύεσθον ἀγομένω, εἴξαντε καὶ ὁμολογήσαντε ποιήσειν τὸ κελευόμενον. καὶ πρὸς αὐτῷ τ᾽ ἐγένοντο καὶ εἶδον τὴν ὄψιν τὴν τῶν παιδικῶν ἀστράπτουσαν. ἰδόντος δὲ τοῦ ἡνιόχου ἡ μνήμη πρὸς τὴν τοῦ κάλλους φύσιν ἠνέχθη, καὶ πάλιν εἶδεν αὐτὴν μετὰ σωφροσύνης ἐν ἁγνῷ βάθρῳ βεβῶσαν· ἰδοῦσα δὲ ἔδεισέ τε καὶ σεφθεῖσα ἀνέπεσεν ὑπτία, καὶ ἅμα ἠναγκάσθη εἰς","st":"254b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοὐπίσω ἑλκύσαι τὰς ἡνίας οὕτω σφόδρα, ὥστ᾽ ἐπὶ τὰ ἰσχία ἄμφω καθίσαι τὼ ἵππω, τὸν μὲν ἑκόντα διὰ τὸ μὴ ἀντιτείνειν, τὸν δὲ ὑβριστὴν μάλ᾽ ἄκοντα. ἀπελθόντε δὲ ἀπωτέρω, ὁ μὲν ὑπ᾽ αἰσχύνης τε καὶ θάμβους ἱδρῶτι πᾶσαν ἔβρεξε τὴν ψυχήν, ὁ δὲ λήξας τῆς ὀδύνης, ἣν ὑπὸ τοῦ χαλινοῦ τε ἔσχεν καὶ τοῦ πτώματος, μόγις ἐξαναπνεύσας ἐλοιδόρησεν ὀργῇ, πολλὰ κακίζων τόν τε ἡνίοχον καὶ τὸν ὁμόζυγα ὡς δειλίᾳ τε καὶ ἀνανδρίᾳ λιπόντε τὴν τάξιν καὶ","st":"254c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁμολογίαν· καὶ πάλιν οὐκ ἐθέλοντας προσιέναι ἀναγκάζων μόγις συνεχώρησεν δεομένων εἰς αὖθις ὑπερβαλέσθαι. ἐλθόντος δὲ τοῦ συντεθέντος χρόνου ἀμνημονεῖν προσποιουμένω ἀναμιμνῄσκων, βιαζόμενος, χρεμετίζων, ἕλκων ἠνάγκασεν αὖ προσελθεῖν τοῖς παιδικοῖς ἐπὶ τοὺς αὐτοὺς λόγους, καὶ ἐπειδὴ ἐγγὺς ἦσαν, ἐγκύψας καὶ ἐκτείνας τὴν κέρκον, ἐνδακὼν τὸν χαλινόν, μετ᾽ ἀναιδείας ἕλκει· ὁ δ᾽","st":"254d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡνίοχος ἔτι μᾶλλον ταὐτὸν πάθος παθών, ὥσπερ ἀπὸ ὕσπληγος ἀναπεσών, ἔτι μᾶλλον τοῦ ὑβριστοῦ ἵππου ἐκ τῶν ὀδόντων βίᾳ ὀπίσω σπάσας τὸν χαλινόν, τήν τε κακηγόρον γλῶτταν καὶ τὰς γνάθους καθῄμαξεν καὶ τὰ σκέλη τε καὶ τὰ ἰσχία πρὸς τὴν γῆν ἐρείσας ὀδύναις ἔδωκεν.","st":"254e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν δὲ ταὐτὸν πολλάκις πάσχων ὁ πονηρὸς τῆς ὕβρεως λήξῃ, ταπεινωθεὶς ἕπεται ἤδη τῇ τοῦ ἡνιόχου προνοίᾳ, καὶ ὅταν ἴδῃ τὸν καλόν, φόβῳ διόλλυται· ὥστε συμβαίνει τότ᾽ ἤδη τὴν τοῦ ἐραστοῦ ψυχὴν τοῖς παιδικοῖς αἰδουμένην τε καὶ δεδιυῖαν","st":"254e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἕπεσθαι. ἅτε οὖν πᾶσαν θεραπείαν ὡς ἰσόθεος θεραπευόμενος οὐχ ὑπὸ σχηματιζομένου τοῦ ἐρῶντος ἀλλ᾽ ἀληθῶς τοῦτο πεπονθότος, καὶ αὐτὸς ὢν φύσει φίλος τῷ θεραπεύοντι, ἐὰν ἄρα καὶ ἐν τῷ πρόσθεν ὑπὸ συμφοιτητῶν ἤ τινων ἄλλων διαβεβλημένος ᾖ, λεγόντων ὡς αἰσχρὸν ἐρῶντι πλησιάζειν, καὶ διὰ τοῦτο ἀπωθῇ τὸν ἐρῶντα, προϊόντος δὲ ἤδη τοῦ χρόνου ἥ τε ἡλικία καὶ τὸ χρεὼν ἤγαγεν εἰς","st":"255a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ προσέσθαι αὐτὸν εἰς ὁμιλίαν· οὐ γὰρ δήποτε εἵμαρται κακὸν κακῷ φίλον οὐδ᾽ ἀγαθὸν μὴ φίλον ἀγαθῷ εἶναι. προσεμένου δὲ καὶ λόγον καὶ ὁμιλίαν δεξαμένου, ἐγγύθεν ἡ εὔνοια γιγνομένη τοῦ ἐρῶντος ἐκπλήττει τὸν ἐρώμενον διαισθανόμενον ὅτι οὐδ᾽ οἱ σύμπαντες ἄλλοι φίλοι τε καὶ οἰκεῖοι μοῖραν φιλίας οὐδεμίαν παρέχονται πρὸς τὸν ἔνθεον φίλον. ὅταν δὲ χρονίζῃ τοῦτο δρῶν καὶ πλησιάζῃ μετὰ τοῦ ἅπτεσθαι ἔν τε γυμνασίοις καὶ ἐν ταῖς ἄλλαις ὁμιλίαις,","st":"255b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τότ᾽ ἤδη ἡ τοῦ ῥεύματος ἐκείνου πηγή, ὃν ἵμερον Ζεὺς Γανυμήδους ἐρῶν ὠνόμασε, πολλὴ φερομένη πρὸς τὸν ἐραστήν, ἡ μὲν εἰς αὐτὸν ἔδυ, ἡ δ᾽ ἀπομεστουμένου ἔξω ἀπορρεῖ· καὶ οἷον πνεῦμα ἤ τις ἠχὼ ἀπὸ λείων τε καὶ στερεῶν ἁλλομένη πάλιν ὅθεν ὡρμήθη φέρεται, οὕτω τὸ τοῦ κάλλους ῥεῦμα πάλιν εἰς τὸν καλὸν διὰ τῶν ὀμμάτων ἰόν, ᾗ πέφυκεν ἐπὶ τὴν ψυχὴν ἰέναι ἀφικόμενον καὶ ἀναπτερῶσαν,","st":"255c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς διόδους τῶν πτερῶν ἄρδει τε καὶ ὥρμησε πτεροφυεῖν τε καὶ τὴν τοῦ ἐρωμένου αὖ ψυχὴν ἔρωτος ἐνέπλησεν. ἐρᾷ μὲν οὖν, ὅτου δὲ ἀπορεῖ· καὶ οὔθ᾽ ὅτι πέπονθεν οἶδεν οὐδ᾽ ἔχει φράσαι, ἀλλ᾽ οἷον ἀπ᾽ ἄλλου ὀφθαλμίας ἀπολελαυκὼς πρόφασιν εἰπεῖν οὐκ ἔχει, ὥσπερ δὲ ἐν κατόπτρῳ ἐν τῷ ἐρῶντι ἑαυτὸν ὁρῶν λέληθεν. καὶ ὅταν μὲν ἐκεῖνος παρῇ, λήγει κατὰ ταὐτὰ ἐκείνῳ τῆς ὀδύνης, ὅταν δὲ ἀπῇ, κατὰ ταὐτὰ αὖ ποθεῖ καὶ ποθεῖται, εἴδωλον","st":"255d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔρωτος ἀντέρωτα ἔχων· καλεῖ δὲ αὐτὸν καὶ οἴεται οὐκ ἔρωτα ἀλλὰ φιλίαν εἶναι. ἐπιθυμεῖ δὲ ἐκείνῳ παραπλησίως μέν, ἀσθενεστέρως δέ, ὁρᾶν, ἅπτεσθαι, φιλεῖν, συγκατακεῖσθαι· καὶ δή, οἷον εἰκός, ποιεῖ τὸ μετὰ τοῦτο ταχὺ ταῦτα.","st":"255e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν οὖν τῇ συγκοιμήσει τοῦ μὲν ἐραστοῦ ὁ ἀκόλαστος ἵππος ἔχει ὅτι λέγῃ πρὸς τὸν ἡνίοχον, καὶ ἀξιοῖ ἀντὶ πολλῶν πόνων","st":"255e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σμικρὰ ἀπολαῦσαι· ὁ δὲ τῶν παιδικῶν ἔχει μὲν οὐδὲν εἰπεῖν, σπαργῶν δὲ καὶ ἀπορῶν περιβάλλει τὸν ἐραστὴν καὶ φιλεῖ, ὡς σφόδρ᾽ εὔνουν ἀσπαζόμενος, ὅταν τε συγκατακέωνται, οἷός ἐστι μὴ ἂν ἀπαρνηθῆναι τὸ αὑτοῦ μέρος χαρίσασθαι τῷ ἐρῶντι, εἰ δεηθείη τυχεῖν· ὁ δὲ ὁμόζυξ αὖ μετὰ τοῦ ἡνιόχου πρὸς ταῦτα μετ᾽ αἰδοῦς καὶ λόγου ἀντιτείνει. ἐὰν μὲν δὴ οὖν εἰς τεταγμένην τε δίαιταν καὶ φιλοσοφίαν νικήσῃ τὰ βελτίω τῆς διανοίας ἀγαγόντα, μακάριον μὲν","st":"256a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ὁμονοητικὸν τὸν ἐνθάδε βίον διάγουσιν, ἐγκρατεῖς αὑτῶν καὶ κόσμιοι ὄντες, δουλωσάμενοι μὲν ᾧ κακία ψυχῆς ἐνεγίγνετο, ἐλευθερώσαντες δὲ ᾧ ἀρετή· τελευτήσαντες δὲ δὴ ὑπόπτεροι καὶ ἐλαφροὶ γεγονότες τῶν τριῶν παλαισμάτων τῶν ὡς ἀληθῶς Ὀλυμπιακῶν ἓν νενικήκασιν, οὗ μεῖζον ἀγαθὸν οὔτε σωφροσύνη ἀνθρωπίνη οὔτε θεία μανία δυνατὴ πορίσαι ἀνθρώπῳ. ἐὰν δὲ δὴ διαίτῃ φορτικωτέρᾳ τε καὶ","st":"256b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀφιλοσόφῳ, φιλοτίμῳ δὲ χρήσωνται, τάχ᾽ ἄν που ἐν μέθαις ἤ τινι ἄλλῃ ἀμελείᾳ τὼ ἀκολάστω αὐτοῖν ὑποζυγίω λαβόντε τὰς ψυχὰς ἀφρούρους, συναγαγόντε εἰς ταὐτόν, τὴν ὑπὸ τῶν πολλῶν μακαριστὴν αἵρεσιν εἱλέσθην τε καὶ διεπραξάσθην· καὶ διαπραξαμένω τὸ λοιπὸν ἤδη χρῶνται μὲν αὐτῇ, σπανίᾳ δέ, ἅτε οὐ πάσῃ δεδογμένα τῇ διανοίᾳ πράττοντες. φίλω μὲν οὖν καὶ τούτω, ἧττον δὲ ἐκείνων, ἀλλήλοιν","st":"256c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διά τε τοῦ ἔρωτος καὶ ἔξω γενομένω διάγουσι, πίστεις τὰς μεγίστας ἡγουμένω ἀλλήλοιν δεδωκέναι τε καὶ δεδέχθαι, ἃς οὐ θεμιτὸν εἶναι λύσαντας εἰς ἔχθραν ποτὲ ἐλθεῖν. ἐν δὲ τῇ τελευτῇ ἄπτεροι μέν, ὡρμηκότες δὲ πτεροῦσθαι ἐκβαίνουσι τοῦ σώματος, ὥστε οὐ σμικρὸν ἆθλον τῆς ἐρωτικῆς μανίας φέρονται· εἰς γὰρ σκότον καὶ τὴν ὑπὸ γῆς πορείαν οὐ νόμος ἐστὶν ἔτι ἐλθεῖν τοῖς κατηργμένοις ἤδη τῆς ὑπουρανίου πορείας, ἀλλὰ φανὸν βίον διάγοντας εὐδαιμονεῖν","st":"256d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μετ᾽ ἀλλήλων πορευομένους, καὶ ὁμοπτέρους ἔρωτος χάριν, ὅταν γένωνται, γενέσθαι. ταῦτα τοσαῦτα, ὦ παῖ, καὶ θεῖα οὕτω σοι δωρήσεται ἡ παρ᾽ ἐραστοῦ φιλία· ἡ δὲ ἀπὸ τοῦ μὴ ἐρῶντος οἰκειότης, σωφροσύνῃ θνητῇ κεκραμένη, θνητά τε καὶ φειδωλὰ οἰκονομοῦσα, ἀνελευθερίαν ὑπὸ πλήθους ἐπαινουμένην ὡς ἀρετὴν","st":"256e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῇ φίλῃ ψυχῇ ἐντεκοῦσα, ἐννέα χιλιάδας ἐτῶν περὶ γῆν κυλινδουμένην αὐτὴν καὶ ὑπὸ γῆς ἄνουν παρέξει.","st":"257a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὕτη σοι, ὦ φίλε Ἔρως, εἰς ἡμετέραν δύναμιν ὅτι καλλίστη καὶ ἀρίστη δέδοταί τε καὶ ἐκτέτεισται παλινῳδία, τά τε ἄλλα καὶ τοῖς ὀνόμασιν ἠναγκασμένη ποιητικοῖς τισιν διὰ Φαῖδρον εἰρῆσθαι. ἀλλὰ τῶν προτέρων τε συγγνώμην καὶ τῶνδε χάριν ἔχων, εὐμενὴς καὶ ἵλεως τὴν ἐρωτικήν μοι τέχνην ἣν ἔδωκας μήτε ἀφέλῃ μήτε πηρώσῃς δι᾽ ὀργήν, δίδου τ᾽ ἔτι μᾶλλον ἢ νῦν παρὰ τοῖς καλοῖς τίμιον εἶναι.","st":"257a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν τῷ πρόσθεν δ᾽ εἴ τι λόγῳ σοι ἀπηχὲς εἴπομεν Φαῖδρός τε καὶ ἐγώ, Λυσίαν τὸν τοῦ λόγου πατέρα αἰτιώμενος παῦε τῶν τοιούτων λόγων, ἐπὶ φιλοσοφίαν δέ, ὥσπερ ἁδελφὸς αὐτοῦ Πολέμαρχος τέτραπται, τρέψον, ἵνα καὶ ὁ ἐραστὴς ὅδε αὐτοῦ μηκέτι ἐπαμφοτερίζῃ καθάπερ νῦν, ἀλλ᾽ ἁπλῶς πρὸς ἔρωτα μετὰ φιλοσόφων λόγων τὸν βίον ποιῆται.","st":"257b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> συνεύχομαί σοι, ὦ Σώκρατες, εἴπερ ἄμεινον ταῦθ᾽","st":"257b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἡμῖν εἶναι, ταῦτα γίγνεσθαι. τὸν λόγον δέ σου πάλαι θαυμάσας ἔχω, ὅσῳ καλλίω τοῦ προτέρου ἀπηργάσω· ὥστε ὀκνῶ μή μοι ὁ Λυσίας ταπεινὸς φανῇ, ἐὰν ἄρα καὶ ἐθελήσῃ πρὸς αὐτὸν ἄλλον ἀντιπαρατεῖναι. καὶ γάρ τις αὐτόν, ὦ θαυμάσιε, ἔναγχος τῶν πολιτικῶν τοῦτ᾽ αὐτὸ λοιδορῶν ὠνείδιζε, καὶ διὰ πάσης τῆς λοιδορίας ἐκάλει λογογράφον· τάχ᾽ οὖν ἂν ὑπὸ φιλοτιμίας ἐπίσχοι ἡμῖν ἂν τοῦ γράφειν.","st":"257c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γελοῖόν γ᾽, ὦ νεανία, τὸ δόγμα λέγεις, καὶ τοῦ","st":"257c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἑταίρου συχνὸν διαμαρτάνεις, εἰ αὐτὸν οὕτως ἡγῇ τινα ψοφοδεᾶ. ἴσως δὲ καὶ τὸν λοιδορούμενον αὐτῷ οἴει ὀνειδίζοντα λέγειν ἃ ἔλεγεν.","st":"257d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐφαίνετο γάρ, ὦ Σώκρατες· καὶ σύνοισθά που καὶ αὐτὸς ὅτι οἱ μέγιστον δυνάμενοί τε καὶ σεμνότατοι ἐν ταῖς πόλεσιν αἰσχύνονται λόγους τε γράφειν καὶ καταλείπειν συγγράμματα ἑαυτῶν, δόξαν φοβούμενοι τοῦ ἔπειτα χρόνου, μὴ σοφισταὶ καλῶνται.","st":"257d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γλυκὺς ἀγκών, ὦ Φαῖδρε, λέληθέν σε ὅτι ἀπὸ τοῦ","st":"257d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μακροῦ ἀγκῶνος τοῦ κατὰ Νεῖλον ἐκλήθη· καὶ πρὸς τῷ ἀγκῶνι λανθάνει σε ὅτι οἱ μέγιστον φρονοῦντες τῶν πολιτικῶν μάλιστα ἐρῶσι λογογραφίας τε καὶ καταλείψεως συγγραμμάτων, οἵ γε καὶ ἐπειδάν τινα γράφωσι λόγον, οὕτως ἀγαπῶσι τοὺς ἐπαινέτας, ὥστε προσπαραγράφουσι πρώτους οἳ ἂν ἑκασταχοῦ ἐπαινῶσιν αὐτούς.","st":"257e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς λέγεις τοῦτο; οὐ γὰρ μανθάνω.","st":"257e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ μανθάνεις ὅτι ἐν ἀρχῇ ἀνδρὸς πολιτικοῦ πρῶτος ὁ ἐπαινέτης γέγραπται.","st":"258a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς;","st":"258a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔδοξέ πού φησιν τῇ βουλῇ ἢ τῷ δήμῳ ἢ ἀμφοτέροις, καὶ ὃς καὶ ὃς εἶπεν —τὸν αὑτὸν δὴ λέγων μάλα σεμνῶς καὶ ἐγκωμιάζων ὁ συγγραφεύς—ἔπειτα λέγει δὴ μετὰ τοῦτο, ἐπιδεικνύμενος τοῖς ἐπαινέταις τὴν ἑαυτοῦ σοφίαν, ἐνίοτε πάνυ μακρὸν ποιησάμενος σύγγραμμα· ἤ σοι ἄλλο τι φαίνεται τὸ τοιοῦτον ἢ λόγος συγγεγραμμένος;","st":"258a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐκ ἔμοιγε.","st":"258b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἐὰν μὲν οὗτος ἐμμένῃ, γεγηθὼς ἀπέρχεται ἐκ τοῦ θεάτρου ὁ ποιητής· ἐὰν δὲ ἐξαλειφθῇ καὶ ἄμοιρος γένηται λογογραφίας τε καὶ τοῦ ἄξιος εἶναι συγγράφειν, πενθεῖ αὐτός τε καὶ οἱ ἑταῖροι.","st":"258b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα.","st":"258b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δῆλόν γε ὅτι οὐχ ὡς ὑπερφρονοῦντες τοῦ ἐπιτηδεύματος, ἀλλ᾽ ὡς τεθαυμακότες.","st":"258b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πάνυ μὲν οὖν.","st":"258b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δέ; ὅταν ἱκανὸς γένηται ῥήτωρ ἢ βασιλεύς, ὥστε","st":"258b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λαβὼν τὴν Λυκούργου ἢ Σόλωνος ἢ Δαρείου δύναμιν ἀθάνατος γενέσθαι λογογράφος ἐν πόλει, ἆρ᾽ οὐκ ἰσόθεον ἡγεῖται αὐτός τε αὑτὸν ἔτι ζῶν, καὶ οἱ ἔπειτα γιγνόμενοι ταὐτὰ ταῦτα περὶ αὐτοῦ νομίζουσι, θεώμενοι αὐτοῦ τὰ συγγράμματα;","st":"258c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα.","st":"258c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἴει τινὰ οὖν τῶν τοιούτων, ὅστις καὶ ὁπωστιοῦν δύσνους Λυσίᾳ, ὀνειδίζειν αὐτὸ τοῦτο ὅτι συγγράφει;","st":"258c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὔκουν εἰκός γε ἐξ ὧν σὺ λέγεις· καὶ γὰρ ἂν τῇ ἑαυτοῦ ἐπιθυμίᾳ, ὡς ἔοικεν, ὀνειδίζοι.","st":"258c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο μὲν ἄρα παντὶ δῆλον, ὅτι οὐκ αἰσχρὸν αὐτό γε τὸ γράφειν λόγους.","st":"258d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί γάρ;","st":"258d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ ἐκεῖνο οἶμαι αἰσχρὸν ἤδη, τὸ μὴ καλῶς λέγειν τε καὶ γράφειν ἀλλ᾽ αἰσχρῶς τε καὶ κακῶς.","st":"258d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δῆλον δή.","st":"258d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίς οὖν ὁ τρόπος τοῦ καλῶς τε καὶ μὴ γράφειν; δεόμεθά τι, ὦ Φαῖδρε, Λυσίαν τε περὶ τούτων ἐξετάσαι καὶ ἄλλον ὅστις πώποτέ τι γέγραφεν ἢ γράψει, εἴτε πολιτικὸν σύγγραμμα εἴτε ἰδιωτικόν, ἐν μέτρῳ ὡς ποιητὴς ἢ ἄνευ μέτρου ὡς ἰδιώτης;","st":"258d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐρωτᾷς εἰ δεόμεθα; τίνος μὲν οὖν ἕνεκα κἄν τις ὡς εἰπεῖν ζῴη, ἀλλ᾽ ἢ τῶν τοιούτων ἡδονῶν ἕνεκα; οὐ γάρ που ἐκείνων γε ὧν προλυπηθῆναι δεῖ ἢ μηδὲ ἡσθῆναι, ὃ δὴ ὀλίγου πᾶσαι αἱ περὶ τὸ σῶμα ἡδοναὶ ἔχουσι· διὸ καὶ δικαίως ἀνδραποδώδεις κέκληνται.","st":"258e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σχολὴ μὲν δή, ὡς ἔοικε· καὶ ἅμα μοι δοκοῦσιν ὡς ἐν τῷ πνίγει ὑπὲρ κεφαλῆς ἡμῶν οἱ τέττιγες ᾄδοντες καὶ","st":"258e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλήλοις διαλεγόμενοι καθορᾶν καὶ ἡμᾶς. εἰ οὖν ἴδοιεν καὶ νὼ καθάπερ τοὺς πολλοὺς ἐν μεσημβρίᾳ μὴ διαλεγομένους ἀλλὰ νυστάζοντας καὶ κηλουμένους ὑφ᾽ αὑτῶν δι᾽ ἀργίαν τῆς διανοίας, δικαίως ἂν καταγελῷεν, ἡγούμενοι ἀνδράποδ᾽ ἄττα σφίσιν ἐλθόντα εἰς τὸ καταγώγιον ὥσπερ προβάτια μεσημβριάζοντα περὶ τὴν κρήνην εὕδειν· ἐὰν δὲ ὁρῶσι διαλεγομένους καὶ παραπλέοντάς σφας ὥσπερ Σειρῆνας","st":"259a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀκηλήτους, ὃ γέρας παρὰ θεῶν ἔχουσιν ἀνθρώποις διδόναι, τάχ᾽ ἂν δοῖεν ἀγασθέντες.","st":"259b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἔχουσι δὲ δὴ τί τοῦτο; ἀνήκοος γάρ, ὡς ἔοικε, τυγχάνω ὤν.","st":"259b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ μὲν δὴ πρέπει γε φιλόμουσον ἄνδρα τῶν τοιούτων ἀνήκοον εἶναι. λέγεται δ᾽ ὥς ποτ᾽ ἦσαν οὗτοι ἄνθρωποι τῶν πρὶν μούσας γεγονέναι, γενομένων δὲ Μουσῶν καὶ φανείσης ᾠδῆς οὕτως ἄρα τινὲς τῶν τότε ἐξεπλάγησαν ὑφ᾽ ἡδονῆς,","st":"259b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὥστε ᾄδοντες ἠμέλησαν σίτων τε καὶ ποτῶν, καὶ ἔλαθον τελευτήσαντες αὑτούς· ἐξ ὧν τὸ τεττίγων γένος μετ᾽ ἐκεῖνο φύεται, γέρας τοῦτο παρὰ Μουσῶν λαβόν, μηδὲν τροφῆς δεῖσθαι γενόμενον, ἀλλ᾽ ἄσιτόν τε καὶ ἄποτον εὐθὺς ᾄδειν, ἕως ἂν τελευτήσῃ, καὶ μετὰ ταῦτα ἐλθὸν παρὰ μούσας ἀπαγγέλλειν τίς τίνα αὐτῶν τιμᾷ τῶν ἐνθάδε. Τερψιχόρᾳ μὲν οὖν τοὺς ἐν τοῖς χοροῖς τετιμηκότας αὐτὴν ἀπαγγέλλοντες","st":"259c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ποιοῦσι προσφιλεστέρους, τῇ δὲ Ἐρατοῖ τοὺς ἐν τοῖς ἐρωτικοῖς, καὶ ταῖς ἄλλαις οὕτως, κατὰ τὸ εἶδος ἑκάστης τιμῆς· τῇ δὲ πρεσβυτάτῃ Καλλιόπῃ καὶ τῇ μετ᾽ αὐτὴν Οὐρανίᾳ τοὺς ἐν φιλοσοφίᾳ διάγοντάς τε καὶ τιμῶντας τὴν ἐκείνων μουσικὴν ἀγγέλλουσιν, αἳ δὴ μάλιστα τῶν Μουσῶν περί τε οὐρανὸν καὶ λόγους οὖσαι θείους τε καὶ ἀνθρωπίνους ἱᾶσιν καλλίστην φωνήν. πολλῶν δὴ οὖν ἕνεκα λεκτέον τι καὶ οὐ καθευδητέον ἐν τῇ μεσημβρίᾳ.","st":"259d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λεκτέον γὰρ οὖν.","st":"259d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν, ὅπερ νῦν προυθέμεθα σκέψασθαι, τὸν λόγον ὅπῃ καλῶς ἔχει λέγειν τε καὶ γράφειν καὶ ὅπῃ μή, σκεπτέον.","st":"259e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δῆλον.","st":"259e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐχ ὑπάρχειν δεῖ τοῖς εὖ γε καὶ καλῶς ῥηθησομένοις τὴν τοῦ λέγοντος διάνοιαν εἰδυῖαν τὸ ἀληθὲς ὧν ἂν ἐρεῖν πέρι μέλλῃ;","st":"259e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὑτωσὶ περὶ τούτου ἀκήκοα, ὦ φίλε Σώκρατες, οὐκ","st":"259e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἶναι ἀνάγκην τῷ μέλλοντι ῥήτορι ἔσεσθαι τὰ τῷ ὄντι δίκαια μανθάνειν ἀλλὰ τὰ δόξαντ᾽ ἂν πλήθει οἵπερ δικάσουσιν, οὐδὲ τὰ ὄντως ἀγαθὰ ἢ καλὰ ἀλλ᾽ ὅσα δόξει· ἐκ γὰρ τούτων εἶναι τὸ πείθειν ἀλλ᾽ οὐκ ἐκ τῆς ἀληθείας.","st":"260a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔτοι ἀπόβλητον ἔπος εἶναι δεῖ, ὦ Φαῖδρε, ὃ ἂν εἴπωσι σοφοί, ἀλλὰ σκοπεῖν μή τι λέγωσι· καὶ δὴ καὶ τὸ νῦν λεχθὲν οὐκ ἀφετέον.","st":"260a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ὀρθῶς λέγεις.","st":"260a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὧδε δὴ σκοπῶμεν αὐτό.","st":"260a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς;","st":"260a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἴ σε πείθοιμι ἐγὼ πολεμίους ἀμύνειν κτησάμενον ἵππον, ἄμφω δὲ ἵππον ἀγνοοῖμεν, τοσόνδε μέντοι τυγχάνοιμι εἰδὼς περὶ σοῦ, ὅτι Φαῖδρος ἵππον ἡγεῖται τὸ τῶν ἡμέρων ζῴων μέγιστα ἔχον ὦτα—","st":"260b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> γελοῖόν γ᾽ ἄν, ὦ Σώκρατες, εἴη.","st":"260b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔπω γε· ἀλλ᾽ ὅτε δὴ σπουδῇ σε πείθοιμι, συντιθεὶς λόγον ἔπαινον κατὰ τοῦ ὄνου, ἵππον ἐπονομάζων καὶ λέγων ὡς παντὸς ἄξιον τὸ θρέμμα οἴκοι τε κεκτῆσθαι καὶ ἐπὶ στρατιᾶς, ἀποπολεμεῖν τε χρήσιμον καὶ πρός γ᾽ ἐνεγκεῖν δυνατὸν","st":"260b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκεύη καὶ ἄλλα πολλὰ ὠφέλιμον.","st":"260c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παγγέλοιόν γ᾽ ἂν ἤδη εἴη.","st":"260c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐ κρεῖττον γελοῖον καὶ φίλον ἢ δεινόν τε καὶ ἐχθρὸν ;","st":"260c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> φαίνεται.","st":"260c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν οὖν ὁ ῥητορικὸς ἀγνοῶν ἀγαθὸν καὶ κακόν, λαβὼν πόλιν ὡσαύτως ἔχουσαν πείθῃ, μὴ περὶ ὄνου σκιᾶς ὡς ἵππου τὸν ἔπαινον ποιούμενος, ἀλλὰ περὶ κακοῦ ὡς ἀγαθοῦ, δόξας δὲ πλήθους μεμελετηκὼς πείσῃ κακὰ πράττειν ἀντ᾽ ἀγαθῶν, ποῖόν τιν᾽ ἂν οἴει μετὰ ταῦτα τὴν ῥητορικὴν","st":"260c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καρπὸν ὧν ἔσπειρε θερίζειν;","st":"260d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐ πάνυ γε ἐπιεικῆ.","st":"260d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν, ὦ ἀγαθέ, ἀγροικότερον τοῦ δέοντος λελοιδορήκαμεν τὴν τῶν λόγων τέχνην; ἡ δ᾽ ἴσως ἂν εἴποι· τί ποτ᾽, ὦ θαυμάσιοι, ληρεῖτε; ἐγὼ γὰρ οὐδέν᾽ ἀγνοοῦντα τἀληθὲς ἀναγκάζω μανθάνειν λέγειν, ἀλλ᾽, εἴ τι ἐμὴ συμβουλή, κτησάμενον ἐκεῖνο οὕτως ἐμὲ λαμβάνειν· τόδε δ᾽ οὖν μέγα λέγω, ὡς ἄνευ ἐμοῦ τῷ τὰ ὄντα εἰδότι οὐδέν τι μᾶλλον ἔσται πείθειν τέχνῃ.","st":"260d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐκοῦν δίκαια ἐρεῖ, λέγουσα ταῦτα;","st":"260e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φημί, ἐὰν οἵ γ᾽ ἐπιόντες αὐτῇ λόγοι μαρτυρῶσιν εἶναι τέχνῃ. ὥσπερ γὰρ ἀκούειν δοκῶ τινων προσιόντων καὶ διαμαρτυρομένων λόγων, ὅτι ψεύδεται καὶ οὐκ ἔστι τέχνη ἀλλ᾽ ἄτεχνος τριβή· τοῦ δὲ λέγειν, φησὶν ὁ Λάκων, ἔτυμος τέχνη ἄνευ τοῦ ἀληθείας ἧφθαι οὔτ᾽ ἔστιν οὔτε μή ποτε ὕστερον γένηται.","st":"260e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τούτων δεῖ τῶν λόγων, ὦ Σώκρατες· ἀλλὰ δεῦρο αὐτοὺς παράγων ἐξέταζε τί καὶ πῶς λέγουσιν.","st":"261a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάριτε δή, θρέμματα γενναῖα, καλλίπαιδά τε Φαῖδρον πείθετε ὡς ἐὰν μὴ ἱκανῶς φιλοσοφήσῃ, οὐδὲ ἱκανός ποτε λέγειν ἔσται περὶ οὐδενός. ἀποκρινέσθω δὴ ὁ Φαῖδρος.","st":"261a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐρωτᾶτε.","st":"261a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐ τὸ μὲν ὅλον ἡ ῥητορικὴ ἂν εἴη τέχνη ψυχαγωγία τις διὰ λόγων, οὐ μόνον ἐν δικαστηρίοις καὶ ὅσοι ἄλλοι δημόσιοι σύλλογοι, ἀλλὰ καὶ ἐν ἰδίοις, ἡ αὐτὴ σμικρῶν","st":"261a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τε καὶ μεγάλων πέρι, καὶ οὐδὲν ἐντιμότερον τό γε ὀρθὸν περὶ σπουδαῖα ἢ περὶ φαῦλα γιγνόμενον; ἢ πῶς σὺ ταῦτ᾽ ἀκήκοας;","st":"261b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐ μὰ τὸν Δί᾽ οὐ παντάπασιν οὕτως, ἀλλὰ μάλιστα μέν πως περὶ τὰς δίκας λέγεταί τε καὶ γράφεται τέχνῃ, λέγεται δὲ καὶ περὶ δημηγορίας· ἐπὶ πλέον δὲ οὐκ ἀκήκοα.","st":"261b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ ἦ τὰς Νέστορος καὶ Ὀδυσσέως τέχνας μόνον περὶ λόγων ἀκήκοας, ἃς ἐν Ἰλίῳ σχολάζοντες συνεγραψάτην, τῶν δὲ Παλαμήδους ἀνήκοος γέγονας;","st":"261b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ ναὶ μὰ Δί᾽ ἔγωγε τῶν Νέστορος, εἰ μὴ Γοργίαν Νέστορά τινα κατασκευάζεις, ἤ τινα Θρασύμαχόν τε καὶ Θεόδωρον Ὀδυσσέα.","st":"261c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴσως. ἀλλὰ γὰρ τούτους ἐῶμεν· σὺ δ᾽ εἰπέ, ἐν δικαστηρίοις οἱ ἀντίδικοι τί δρῶσιν; οὐκ ἀντιλέγουσιν μέντοι; ἢ τί φήσομεν;","st":"261c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τοῦτ᾽ αὐτό.","st":"261c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> περὶ τοῦ δικαίου τε καὶ ἀδίκου;","st":"261c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί.","st":"261c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁ τέχνῃ τοῦτο δρῶν ποιήσει φανῆναι τὸ","st":"261c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτὸ τοῖς αὐτοῖς τοτὲ μὲν δίκαιον, ὅταν δὲ βούληται, ἄδικον;","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἐν δημηγορίᾳ δὴ τῇ πόλει δοκεῖν τὰ αὐτὰ τοτὲ μὲν ἀγαθά, τοτὲ δ᾽ αὖ τἀναντία;","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὕτως.","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν οὖν Ἐλεατικὸν Παλαμήδην λέγοντα οὐκ ἴσμεν τέχνῃ, ὥστε φαίνεσθαι τοῖς ἀκούουσι τὰ αὐτὰ ὅμοια καὶ ἀνόμοια, καὶ ἓν καὶ πολλά, μένοντά τε αὖ καὶ φερόμενα;","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> μάλα γε.","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα μόνον περὶ δικαστήριά τέ ἐστιν ἡ ἀντιλογικὴ","st":"261d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ περὶ δημηγορίαν, ἀλλ᾽, ὡς ἔοικε, περὶ πάντα τὰ λεγόμενα μία τις τέχνη, εἴπερ ἔστιν, αὕτη ἂν εἴη, ᾗ τις οἷός τ᾽ ἔσται πᾶν παντὶ ὁμοιοῦν τῶν δυνατῶν καὶ οἷς δυνατόν, καὶ ἄλλου ὁμοιοῦντος καὶ ἀποκρυπτομένου εἰς φῶς ἄγειν.","st":"261e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς δὴ τὸ τοιοῦτον λέγεις;","st":"261e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῇδε δοκῶ ζητοῦσιν φανεῖσθαι. ἀπάτη πότερον ἐν πολὺ διαφέρουσι γίγνεται μᾶλλον ἢ ὀλίγον;","st":"261e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἐν τοῖς ὀλίγον.","st":"262a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλά γε δὴ κατὰ σμικρὸν μεταβαίνων μᾶλλον λήσεις ἐλθὼν ἐπὶ τὸ ἐναντίον ἢ κατὰ μέγα.","st":"262a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς δ᾽ οὔ;","st":"262a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεῖ ἄρα τὸν μέλλοντα ἀπατήσειν μὲν ἄλλον, αὐτὸν δὲ μὴ ἀπατήσεσθαι, τὴν ὁμοιότητα τῶν ὄντων καὶ ἀνομοιότητα ἀκριβῶς διειδέναι.","st":"262a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀνάγκη μὲν οὖν.","st":"262a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ οὖν οἷός τε ἔσται, ἀλήθειαν ἀγνοῶν ἑκάστου, τὴν τοῦ ἀγνοουμένου ὁμοιότητα σμικράν τε καὶ μεγάλην ἐν τοῖς ἄλλοις διαγιγνώσκειν;","st":"262a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀδύνατον.","st":"262b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τοῖς παρὰ τὰ ὄντα δοξάζουσι καὶ ἀπατωμένοις δῆλον ὡς τὸ πάθος τοῦτο δι᾽ ὁμοιοτήτων τινῶν εἰσερρύη.","st":"262b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> γίγνεται γοῦν οὕτως.","st":"262b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστιν οὖν ὅπως τεχνικὸς ἔσται μεταβιβάζειν κατὰ σμικρὸν διὰ τῶν ὁμοιοτήτων ἀπὸ τοῦ ὄντος ἑκάστοτε ἐπὶ τοὐναντίον ἀπάγων, ἢ αὐτὸς τοῦτο διαφεύγειν, ὁ μὴ ἐγνωρικὼς ὃ ἔστιν ἕκαστον τῶν ὄντων;","st":"262b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐ μή ποτε.","st":"262b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λόγων ἄρα τέχνην, ὦ ἑταῖρε, ὁ τὴν ἀλήθειαν μὴ εἰδώς, δόξας δὲ τεθηρευκώς, γελοίαν τινά, ὡς ἔοικε, καὶ ἄτεχνον παρέξεται.","st":"262c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> κινδυνεύει.","st":"262c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βούλει οὖν ἐν τῷ Λυσίου λόγῳ ὃν φέρεις, καὶ ἐν οἷς ἡμεῖς εἴπομεν ἰδεῖν τι ὧν φαμεν ἀτέχνων τε καὶ ἐντέχνων εἶναι;","st":"262c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πάντων γέ που μάλιστα, ὡς νῦν γε ψιλῶς πως λέγομεν, οὐκ ἔχοντες ἱκανὰ παραδείγματα.","st":"262c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ μὴν κατὰ τύχην γέ τινα, ὡς ἔοικεν, ἐρρηθήτην","st":"262c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὼ λόγω ἔχοντέ τι παράδειγμα, ὡς ἂν ὁ εἰδὼς τὸ ἀληθὲς προσπαίζων ἐν λόγοις παράγοι τοὺς ἀκούοντας. καὶ ἔγωγε, ὦ Φαῖδρε, αἰτιῶμαι τοὺς ἐντοπίους θεούς· ἴσως δὲ καὶ οἱ τῶν Μουσῶν προφῆται οἱ ὑπὲρ κεφαλῆς ᾠδοὶ ἐπιπεπνευκότες ἂν ἡμῖν εἶεν τοῦτο τὸ γέρας· οὐ γάρ που ἔγωγε τέχνης τινὸς τοῦ λέγειν μέτοχος.","st":"262d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἔστω ὡς λέγεις· μόνον δήλωσον ὃ φῄς.","st":"262d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴθι δή μοι ἀνάγνωθι τὴν τοῦ Λυσίου λόγου ἀρχήν.","st":"262d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> περὶ μὲν τῶν ἐμῶν πραγμάτων ἐπίστασαι, καὶ ὡς νομίζω συμφέρειν ἡμῖν τούτων γενομένων, ἀκήκοας. ἀξιῶ δὲ μὴ διὰ τοῦτο ἀτυχῆσαι ὧν δέομαι, ὅτι οὐκ ἐραστὴς ὢν σοῦ τυγχάνω. ὡς ἐκείνοις μὲν τότε μεταμέλει —","st":"262e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παῦσαι. τί δὴ οὖν οὗτος ἁμαρτάνει καὶ ἄτεχνον ποιεῖ λεκτέον· ἦ γάρ;","st":"262e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί.","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἆρ᾽ οὖν οὐ παντὶ δῆλον τό γε τοιόνδε, ὡς περὶ μὲν ἔνια τῶν τοιούτων ὁμονοητικῶς ἔχομεν, περὶ δ᾽ ἔνια στασιωτικῶς;","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δοκῶ μὲν ὃ λέγεις μανθάνειν, ἔτι δ᾽ εἰπὲ σαφέστερον.","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν τις ὄνομα εἴπῃ σιδήρου ἢ ἀργύρου, ἆρ᾽ οὐ τὸ αὐτὸ πάντες διενοήθημεν;","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα.","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ ὅταν δικαίου ἢ ἀγαθοῦ; οὐκ ἄλλος ἄλλῃ φέρεται, καὶ ἀμφισβητοῦμεν ἀλλήλοις τε καὶ ἡμῖν αὐτοῖς;","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πάνυ μὲν οὖν.","st":"263a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν μὲν ἄρα τοῖς συμφωνοῦμεν, ἐν δὲ τοῖς οὔ.","st":"263b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὕτω.","st":"263b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ποτέρωθι οὖν εὐαπατητότεροί ἐσμεν, καὶ ἡ ῥητορικὴ ἐν ποτέροις μεῖζον δύναται;","st":"263b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δῆλον ὅτι ἐν οἷς πλανώμεθα.","st":"263b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸν μέλλοντα τέχνην ῥητορικὴν μετιέναι πρῶτον μὲν δεῖ ταῦτα ὁδῷ διῃρῆσθαι, καὶ εἰληφέναι τινὰ χαρακτῆρα ἑκατέρου τοῦ εἴδους, ἐν ᾧ τε ἀνάγκη τὸ πλῆθος πλανᾶσθαι καὶ ἐν ᾧ μή.","st":"263b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καλὸν γοῦν ἄν, ὦ Σώκρατες, εἶδος εἴη κατανενοηκὼς ὁ τοῦτο λαβών.","st":"263c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔπειτά γε οἶμαι πρὸς ἑκάστῳ γιγνόμενον μὴ λανθάνειν ἀλλ᾽ ὀξέως αἰσθάνεσθαι περὶ οὗ ἂν μέλλῃ ἐρεῖν ποτέρου ὂν τυγχάνει τοῦ γένους.","st":"263c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"263c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί οὖν; τὸν ἔρωτα πότερον φῶμεν εἶναι τῶν ἀμφισβητησίμων ἢ τῶν μή;","st":"263c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τῶν ἀμφισβητησίμων δήπου· ἢ οἴει ἄν σοι ἐγχωρῆσαι εἰπεῖν ἃ νυνδὴ εἶπες περὶ αὐτοῦ, ὡς βλάβη τέ ἐστι τῷ ἐρωμένῳ καὶ ἐρῶντι, καὶ αὖθις ὡς μέγιστον ὂν τῶν ἀγαθῶν τυγχάνει;","st":"263c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄριστα λέγεις· ἀλλ᾽ εἰπὲ καὶ τόδε—ἐγὼ γάρ τοι διὰ τὸ ἐνθουσιαστικὸν οὐ πάνυ μέμνημαι—εἰ ὡρισάμην ἔρωτα ἀρχόμενος τοῦ λόγου.","st":"263d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> νὴ Δία ἀμηχάνως γε ὡς σφόδρα.","st":"263d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φεῦ, ὅσῳ λέγεις τεχνικωτέρας Νύμφας τὰς Ἀχελῴου καὶ Πᾶνα τὸν Ἑρμοῦ Λυσίου τοῦ Κεφάλου πρὸς λόγους εἶναι. ἢ οὐδὲν λέγω, ἀλλὰ καὶ ὁ Λυσίας ἀρχόμενος τοῦ ἐρωτικοῦ ἠνάγκασεν ἡμᾶς ὑπολαβεῖν τὸν ἔρωτα ἕν τι τῶν ὄντων ὃ","st":"263d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτὸς ἐβουλήθη, καὶ πρὸς τοῦτο ἤδη συνταξάμενος πάντα τὸν ὕστερον λόγον διεπεράνατο; βούλει πάλιν ἀναγνῶμεν τὴν ἀρχὴν αὐτοῦ;","st":"263e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἰ σοί γε δοκεῖ· ὃ μέντοι ζητεῖς οὐκ ἔστ᾽ αὐτόθι.","st":"263e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγε, ἵνα ἀκούσω αὐτοῦ ἐκείνου.","st":"263e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> περὶ μὲν τῶν ἐμῶν πραγμάτων ἐπίστασαι, καὶ ὡς νομίζω συμφέρειν ἡμῖν τούτων γενομένων, ἀκήκοας. ἀξιῶ","st":"263e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δὲ μὴ διὰ τοῦτο ἀτυχῆσαι ὧν δέομαι, ὅτι οὐκ ἐραστὴς ὢν σοῦ τυγχάνω. ὡς ἐκείνοις μὲν τότε μεταμέλει ὧν ἂν εὖ ποιήσωσιν, ἐπειδὰν τῆς ἐπιθυμίας παύσωνται· —","st":"264a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἦ πολλοῦ δεῖν ἔοικε ποιεῖν ὅδε γε ὃ ζητοῦμεν, ὃς οὐδὲ ἀπ᾽ ἀρχῆς ἀλλ᾽ ἀπὸ τελευτῆς ἐξ ὑπτίας ἀνάπαλιν διανεῖν ἐπιχειρεῖ τὸν λόγον, καὶ ἄρχεται ἀφ᾽ ὧν πεπαυμένος ἂν ἤδη ὁ ἐραστὴς λέγοι πρὸς τὰ παιδικά. ἢ οὐδὲν εἶπον, Φαῖδρε, φίλη κεφαλή;","st":"264a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἔστιν γέ τοι δή, ὦ Σώκρατες, τελευτή, περὶ οὗ τὸν λόγον ποιεῖται.","st":"264b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ τἆλλα; οὐ χύδην δοκεῖ βεβλῆσθαι τὰ τοῦ λόγου; ἢ φαίνεται τὸ δεύτερον εἰρημένον ἔκ τινος ἀνάγκης δεύτερον δεῖν τεθῆναι, ἤ τι ἄλλο τῶν ῥηθέντων; ἐμοὶ μὲν γὰρ ἔδοξεν, ὡς μηδὲν εἰδότι, οὐκ ἀγεννῶς τὸ ἐπιὸν εἰρῆσθαι τῷ γράφοντι· σὺ δ᾽ ἔχεις τινὰ ἀνάγκην λογογραφικὴν ᾗ ταῦτα ἐκεῖνος οὕτως ἐφεξῆς παρ᾽ ἄλληλα ἔθηκεν;","st":"264b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> χρηστὸς εἶ, ὅτι με ἡγῇ ἱκανὸν εἶναι τὰ ἐκείνου","st":"264b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὕτως ἀκριβῶς διιδεῖν.","st":"264c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ τόδε γε οἶμαί σε φάναι ἄν, δεῖν πάντα λόγον ὥσπερ ζῷον συνεστάναι σῶμά τι ἔχοντα αὐτὸν αὑτοῦ, ὥστε μήτε ἀκέφαλον εἶναι μήτε ἄπουν, ἀλλὰ μέσα τε ἔχειν καὶ ἄκρα, πρέποντα ἀλλήλοις καὶ τῷ ὅλῳ γεγραμμένα.","st":"264c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς γὰρ οὔ;","st":"264c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σκέψαι τοίνυν τὸν τοῦ ἑταίρου σου λόγον εἴτε οὕτως εἴτε ἄλλως ἔχει, καὶ εὑρήσεις τοῦ ἐπιγράμματος οὐδὲν διαφέροντα, ὃ Μίδᾳ τῷ Φρυγί φασίν τινες ἐπιγεγράφθαι.","st":"264c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ποῖον τοῦτο, καὶ τί πεπονθός;","st":"264d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστι μὲν τοῦτο τόδε— χαλκῆ παρθένος εἰμί, Μίδα δ᾽ ἐπὶ σήματι κεῖμαι.<br>ὄφρ᾽ ἂν ὕδωρ τε νάῃ καὶ δένδρεα μακρὰ τεθήλῃ,<br>αὐτοῦ τῇδε μένουσα πολυκλαύτου ἐπὶ τύμβου,<br>ἀγγελέω παριοῦσι Μίδας ὅτι τῇδε τέθαπται.<br>","st":"264d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι δ᾽ οὐδὲν διαφέρει αὐτοῦ πρῶτον ἢ ὕστατόν τι λέγεσθαι, ἐννοεῖς που, ὡς ἐγᾦμαι.","st":"264e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> σκώπτεις τὸν λόγον ἡμῶν, ὦ Σώκρατες.","st":"264e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτον μὲν τοίνυν, ἵνα μὴ σὺ ἄχθῃ, ἐάσωμεν— καίτοι συχνά γε ἔχειν μοι δοκεῖ παραδείγματα πρὸς ἅ τις βλέπων ὀνίναιτ᾽ ἄν, μιμεῖσθαι αὐτὰ ἐπιχειρῶν μὴ πάνυ τι— εἰς δὲ τοὺς ἑτέρους λόγους ἴωμεν. ἦν γάρ τι ἐν αὐτοῖς, ὡς δοκῶ, προσῆκον ἰδεῖν τοῖς βουλομένοις περὶ λόγων σκοπεῖν.","st":"264e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸ ποῖον δὴ λέγεις;","st":"265a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐναντίω που ἤστην· ὁ μὲν γὰρ ὡς τῷ ἐρῶντι, ὁ δ᾽ ὡς τῷ μὴ δεῖ χαρίζεσθαι, ἐλεγέτην.","st":"265a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλ᾽ ἀνδρικῶς.","st":"265a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὤιμην σε τἀληθὲς ἐρεῖν, ὅτι μανικῶς· ὃ μέντοι ἐζήτουν ἐστὶν αὐτὸ τοῦτο. μανίαν γάρ τινα ἐφήσαμεν εἶναι τὸν ἔρωτα. ἦ γάρ;","st":"265a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί.","st":"265a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μανίας δέ γε εἴδη δύο, τὴν μὲν ὑπὸ νοσημάτων ἀνθρωπίνων, τὴν δὲ ὑπὸ θείας ἐξαλλαγῆς τῶν εἰωθότων νομίμων γιγνομένην.","st":"265a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πάνυ γε.","st":"265b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῆς δὲ θείας τεττάρων θεῶν τέτταρα μέρη διελόμενοι, μαντικὴν μὲν ἐπίπνοιαν Ἀπόλλωνος θέντες, Διονύσου δὲ τελεστικήν, Μουσῶν δ᾽ αὖ ποιητικήν, τετάρτην δὲ ἀφροδίτης καὶ Ἔρωτος, ἐρωτικὴν μανίαν ἐφήσαμέν τε ἀρίστην εἶναι, καὶ οὐκ οἶδ᾽ ὅπῃ τὸ ἐρωτικὸν πάθος ἀπεικάζοντες, ἴσως μὲν ἀληθοῦς τινος ἐφαπτόμενοι, τάχα δ᾽ ἂν καὶ ἄλλοσε παραφερόμενοι, κεράσαντες οὐ παντάπασιν ἀπίθανον λόγον,","st":"265b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μυθικόν τινα ὕμνον προσεπαίσαμεν μετρίως τε καὶ εὐφήμως τὸν ἐμόν τε καὶ σὸν δεσπότην ἔρωτα, ὦ Φαῖδρε, καλῶν παίδων ἔφορον.","st":"265c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα ἔμοιγε οὐκ ἀηδῶς ἀκοῦσαι.","st":"265c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τόδε τοίνυν αὐτόθεν λάβωμεν, ὡς ἀπὸ τοῦ ψέγειν πρὸς τὸ ἐπαινεῖν ἔσχεν ὁ λόγος μεταβῆναι.","st":"265c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς δὴ οὖν αὐτὸ λέγεις;","st":"265c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐμοὶ μὲν φαίνεται τὰ μὲν ἄλλα τῷ ὄντι παιδιᾷ πεπαῖσθαι· τούτων δέ τινων ἐκ τύχης ῥηθέντων δυοῖν εἰδοῖν,","st":"265c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ αὐτοῖν τὴν δύναμιν τέχνῃ λαβεῖν δύναιτό τις, οὐκ ἄχαρι.","st":"265d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τίνων δή;","st":"265d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰς μίαν τε ἰδέαν συνορῶντα ἄγειν τὰ πολλαχῇ διεσπαρμένα, ἵνα ἕκαστον ὁριζόμενος δῆλον ποιῇ περὶ οὗ ἂν ἀεὶ διδάσκειν ἐθέλῃ. ὥσπερ τὰ νυνδὴ περὶ Ἔρωτος—ὃ ἔστιν ὁρισθέν—εἴτ᾽ εὖ εἴτε κακῶς ἐλέχθη, τὸ γοῦν σαφὲς καὶ τὸ αὐτὸ αὑτῷ ὁμολογούμενον διὰ ταῦτα ἔσχεν εἰπεῖν ὁ λόγος.","st":"265d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸ δ᾽ ἕτερον δὴ εἶδος τί λέγεις, ὦ Σώκρατες;","st":"265d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ πάλιν κατ᾽ εἴδη δύνασθαι διατέμνειν κατ᾽ ἄρθρα ᾗ πέφυκεν, καὶ μὴ ἐπιχειρεῖν καταγνύναι μέρος μηδέν, κακοῦ μαγείρου τρόπῳ χρώμενον· ἀλλ᾽ ὥσπερ ἄρτι τὼ λόγω τὸ μὲν ἄφρον τῆς διανοίας ἕν τι κοινῇ εἶδος ἐλαβέτην, ὥσπερ","st":"265e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δὲ σώματος ἐξ ἑνὸς διπλᾶ καὶ ὁμώνυμα πέφυκε, σκαιά, τὰ δὲ δεξιὰ κληθέντα, οὕτω καὶ τὸ τῆς παρανοίας ὡς ἓν ἐν ἡμῖν πεφυκὸς εἶδος ἡγησαμένω τὼ λόγω, ὁ μὲν τὸ ἐπ᾽ ἀριστερὰ τεμνόμενος μέρος, πάλιν τοῦτο τέμνων οὐκ ἐπανῆκεν πρὶν ἐν αὐτοῖς ἐφευρὼν ὀνομαζόμενον σκαιόν τινα ἔρωτα ἐλοιδόρησεν μάλ᾽ ἐν δίκῃ, ὁ δ᾽ εἰς τὰ ἐν δεξιᾷ τῆς μανίας ἀγαγὼν ἡμᾶς, ὁμώνυμον μὲν ἐκείνῳ, θεῖον δ᾽ αὖ τινα ἔρωτα ἐφευρὼν καὶ","st":"266a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προτεινάμενος ἐπῄνεσεν ὡς μεγίστων αἴτιον ἡμῖν ἀγαθῶν.","st":"266b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀληθέστατα λέγεις.","st":"266b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τούτων δὴ ἔγωγε αὐτός τε ἐραστής, ὦ Φαῖδρε, τῶν διαιρέσεων καὶ συναγωγῶν, ἵνα οἷός τε ὦ λέγειν τε καὶ φρονεῖν· ἐάν τέ τιν᾽ ἄλλον ἡγήσωμαι δυνατὸν εἰς ἓν καὶ ἐπὶ πολλὰ πεφυκόθ᾽ ὁρᾶν, τοῦτον διώκω κατόπισθε μετ᾽ ἴχνιον ὥστε θεοῖο. καὶ μέντοι καὶ τοὺς δυναμένους αὐτὸ δρᾶν εἰ μὲν ὀρθῶς ἢ μὴ προσαγορεύω, θεὸς οἶδε, καλῶ δὲ","st":"266b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὖν μέχρι τοῦδε διαλεκτικούς. τὰ δὲ νῦν παρὰ σοῦ τε καὶ Λυσίου μαθόντας εἰπὲ τί χρὴ καλεῖν· ἢ τοῦτο ἐκεῖνό ἐστιν ἡ λόγων τέχνη, ᾗ Θρασύμαχός τε καὶ οἱ ἄλλοι χρώμενοι σοφοὶ μὲν αὐτοὶ λέγειν γεγόνασιν, ἄλλους τε ποιοῦσιν, οἳ ἂν δωροφορεῖν αὐτοῖς ὡς βασιλεῦσιν ἐθέλωσιν;","st":"266c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> βασιλικοὶ μὲν ἇνδρες, οὐ μὲν δὴ ἐπιστήμονές γε ὧν ἐρωτᾷς. ἀλλὰ τοῦτο μὲν τὸ εἶδος ὀρθῶς ἔμοιγε δοκεῖς καλεῖν, διαλεκτικὸν καλῶν· τὸ δὲ ῥητορικὸν δοκεῖ μοι διαφεύγειν ἔθ᾽ ἡμᾶς.","st":"266c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πῶς φῄς; καλόν πού τι ἂν εἴη, ὃ τούτων ἀπολειφθὲν ὅμως τέχνῃ λαμβάνεται; πάντως δ᾽ οὐκ ἀτιμαστέον αὐτὸ σοί τε καὶ ἐμοί, λεκτέον δὲ τί μέντοι καὶ ἔστι τὸ λειπόμενον τῆς ῥητορικῆς.","st":"266d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα που συχνά, ὦ Σώκρατες, τά γ᾽ ἐν τοῖς βιβλίοις τοῖς περὶ λόγων τέχνης γεγραμμένοις.","st":"266d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς γε ὑπέμνησας. προοίμιον μὲν οἶμαι πρῶτον ὡς δεῖ τοῦ λόγου λέγεσθαι ἐν ἀρχῇ· ταῦτα λέγεις —ἦ γάρ; —τὰ κομψὰ τῆς τέχνης;","st":"266d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί.","st":"266e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεύτερον δὲ δὴ διήγησίν τινα μαρτυρίας τ᾽ ἐπ᾽ αὐτῇ, τρίτον τεκμήρια, τέταρτον εἰκότα· καὶ πίστωσιν οἶμαι καὶ ἐπιπίστωσιν λέγειν τόν γε βέλτιστον λογοδαίδαλον Βυζάντιον ἄνδρα.","st":"266e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸν χρηστὸν λέγεις Θεόδωρον;","st":"266e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί μήν; καὶ ἔλεγχόν γε καὶ ἐπεξέλεγχον ὡς ποιητέον ἐν κατηγορίᾳ τε καὶ ἀπολογίᾳ. τὸν δὲ κάλλιστον Πάριον Εὐηνὸν ἐς μέσον οὐκ ἄγομεν, ὃς ὑποδήλωσίν τε πρῶτος ηὗρεν καὶ παρεπαίνους—οἱ δ᾽ αὐτὸν καὶ παραψόγους φασὶν ἐν μέτρῳ λέγειν μνήμης χάριν—σοφὸς γὰρ ἁνήρ. Τεισίαν δὲ Γοργίαν τε ἐάσομεν εὕδειν, οἳ πρὸ τῶν ἀληθῶν τὰ εἰκότα εἶδον ὡς τιμητέα μᾶλλον, τά τε αὖ σμικρὰ μεγάλα καὶ τὰ μεγάλα σμικρὰ φαίνεσθαι ποιοῦσιν διὰ ῥώμην λόγου,","st":"267a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καινά τε ἀρχαίως τά τ᾽ ἐναντία καινῶς, συντομίαν τε λόγων καὶ ἄπειρα μήκη περὶ πάντων ἀνηῦρον; ταῦτα δὲ ἀκούων ποτέ μου Πρόδικος ἐγέλασεν, καὶ μόνος αὐτὸς ηὑρηκέναι ἔφη ὧν δεῖ λόγων τέχνην· δεῖν δὲ οὔτε μακρῶν οὔτε βραχέων ἀλλὰ μετρίων.","st":"267b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> σοφώτατά γε, ὦ Πρόδικε.","st":"267b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> Ἱππίαν δὲ οὐ λέγομεν; οἶμαι γὰρ ἂν σύμψηφον αὐτῷ καὶ τὸν Ἠλεῖον ξένον γενέσθαι.","st":"267b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί δ᾽ οὔ;","st":"267b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰ δὲ Πώλου πῶς φράσωμεν αὖ μουσεῖα λόγων—ὡς","st":"267b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> διπλασιολογίαν καὶ γνωμολογίαν καὶ εἰκονολογίαν—ὀνομάτων τε Λικυμνίων ἃ ἐκείνῳ ἐδωρήσατο πρὸς ποίησιν εὐεπείας;","st":"267c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> Πρωταγόρεια δέ, ὦ Σώκρατες, οὐκ ἦν μέντοι τοιαῦτ᾽ ἄττα;","st":"267c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὀρθοέπειά γέ τις, ὦ παῖ, καὶ ἄλλα πολλὰ καὶ καλά. τῶν γε μὴν οἰκτρογόων ἐπὶ γῆρας καὶ πενίαν ἑλκομένων λόγων κεκρατηκέναι τέχνῃ μοι φαίνεται τὸ τοῦ Χαλκηδονίου σθένος, ὀργίσαι τε αὖ πολλοὺς ἅμα δεινὸς ἁνὴρ","st":"267c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γέγονεν, καὶ πάλιν ὠργισμένοις ἐπᾴδων κηλεῖν, ὡς ἔφη· διαβάλλειν τε καὶ ἀπολύσασθαι διαβολὰς ὁθενδὴ κράτιστος. τὸ δὲ δὴ τέλος τῶν λόγων κοινῇ πᾶσιν ἔοικε συνδεδογμένον εἶναι, ᾧ τινες μὲν ἐπάνοδον, ἄλλοι δ᾽ ἄλλο τίθενται ὄνομα.","st":"267d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸ ἐν κεφαλαίῳ ἕκαστα λέγεις ὑπομνῆσαι ἐπὶ τελευτῆς τοὺς ἀκούοντας περὶ τῶν εἰρημένων;","st":"267d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτα λέγω, καὶ εἴ τι σὺ ἄλλο ἔχεις εἰπεῖν λόγων τέχνης πέρι.","st":"267d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> σμικρά γε καὶ οὐκ ἄξια λέγειν.","st":"267d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐῶμεν δὴ τά γε σμικρά· ταῦτα δὲ ὑπ᾽ αὐγὰς μᾶλλον ἴδωμεν, τίνα καὶ πότ᾽ ἔχει τὴν τῆς τέχνης δύναμιν.","st":"268a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα ἐρρωμένην, ὦ Σώκρατες, ἔν γε δὴ πλήθους συνόδοις.","st":"268a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔχει γάρ. ἀλλ᾽, ὦ δαιμόνιε, ἰδὲ καὶ σὺ εἰ ἄρα καὶ σοὶ φαίνεται διεστηκὸς αὐτῶν τὸ ἤτριον ὥσπερ ἐμοί.","st":"268a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> δείκνυε μόνον.","st":"268a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰπὲ δή μοι· εἴ τις προσελθὼν τῷ ἑταίρῳ σου Ἐρυξιμάχῳ ἢ τῷ πατρὶ αὐτοῦ Ἀκουμενῷ εἴποι ὅτι ἐγὼ ἐπίσταμαι τοιαῦτ᾽ ἄττα σώμασι προσφέρειν, ὥστε θερμαίνειν","st":"268a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τ᾽ ἐὰν βούλωμαι καὶ ψύχειν, καὶ ἐὰν μὲν δόξῃ μοι, ἐμεῖν ποιεῖν, ἐὰν δ᾽ αὖ, κάτω διαχωρεῖν, καὶ ἄλλα πάμπολλα τοιαῦτα· καὶ ἐπιστάμενος αὐτὰ ἀξιῶ ἰατρικὸς εἶναι καὶ ἄλλον ποιεῖν ᾧ ἂν τὴν τούτων ἐπιστήμην παραδῶ, τί ἂν οἴει ἀκούσαντας εἰπεῖν;","st":"268b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί δ᾽ ἄλλο γε ἢ ἐρέσθαι εἰ προσεπίσταται καὶ οὕστινας δεῖ καὶ ὁπότε ἕκαστα τούτων ποιεῖν, καὶ μέχρι ὁπόσου;","st":"268b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἰ οὖν εἴποι ὅτι οὐδαμῶς· ἀλλ᾽ ἀξιῶ τὸν ταῦτα","st":"268b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παρ᾽ ἐμοῦ μαθόντα αὐτὸν οἷόν τ᾽ εἶναι ἃ ἐρωτᾷς;","st":"268c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἰπεῖν ἂν οἶμαι ὅτι μαίνεται ἅνθρωπος, καὶ ἐκ βιβλίου ποθὲν ἀκούσας ἢ περιτυχὼν φαρμακίοις ἰατρὸς οἴεται γεγονέναι, οὐδὲν ἐπαΐων τῆς τέχνης.","st":"268c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ εἰ Σοφοκλεῖ αὖ προσελθὼν καὶ Εὐριπίδῃ τις λέγοι ὡς ἐπίσταται περὶ σμικροῦ πράγματος ῥήσεις παμμήκεις ποιεῖν καὶ περὶ μεγάλου πάνυ σμικράς, ὅταν τε βούληται οἰκτράς, καὶ τοὐναντίον αὖ φοβερὰς καὶ ἀπειλητικὰς ὅσα τ᾽","st":"268c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλα τοιαῦτα, καὶ διδάσκων αὐτὰ τραγῳδίας ποίησιν οἴεται παραδιδόναι;","st":"268d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ οὗτοι ἄν, ὦ Σώκρατες, οἶμαι καταγελῷεν εἴ τις οἴεται τραγῳδίαν ἄλλο τι εἶναι ἢ τὴν τούτων σύστασιν πρέπουσαν ἀλλήλοις τε καὶ τῷ ὅλῳ συνισταμένην.","st":"268d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλ᾽ οὐκ ἂν ἀγροίκως γε οἶμαι λοιδορήσειαν, ἀλλ᾽ ὥσπερ ἂν μουσικὸς ἐντυχὼν ἀνδρὶ οἰομένῳ ἁρμονικῷ εἶναι, ὅτι δὴ τυγχάνει ἐπιστάμενος ὡς οἷόν τε ὀξυτάτην καὶ βαρυτάτην","st":"268d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χορδὴν ποιεῖν, οὐκ ἀγρίως εἴποι ἄν· ὦ μοχθηρέ, μελαγχολᾷς, ἀλλ᾽ ἅτε μουσικὸς ὢν πρᾳότερον ὅτι ὦ ἄριστε, ἀνάγκη μὲν καὶ ταῦτ᾽ ἐπίστασθαι τὸν μέλλοντα ἁρμονικὸν ἔσεσθαι, οὐδὲν μὴν κωλύει μηδὲ σμικρὸν ἁρμονίας ἐπαΐειν τὸν τὴν σὴν ἕξιν ἔχοντα· τὰ γὰρ πρὸ ἁρμονίας ἀναγκαῖα μαθήματα ἐπίστασαι ἀλλ᾽ οὐ τὰ ἁρμονικά.","st":"268e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ὀρθότατά γε.","st":"268e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν καὶ ὁ Σοφοκλῆς τόν σφισιν ἐπιδεικνύμενον τὰ πρὸ τραγῳδίας ἂν φαίη ἀλλ᾽ οὐ τὰ τραγικά, καὶ ὁ Ἀκουμενὸς τὰ πρὸ ἰατρικῆς ἀλλ᾽ οὐ τὰ ἰατρικά.","st":"269a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παντάπασι μὲν οὖν.","st":"269a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δὲ τὸν μελίγηρυν Ἄδραστον οἰόμεθα ἢ καὶ Περικλέα, εἰ ἀκούσειαν ὧν νυνδὴ ἡμεῖς διῇμεν τῶν παγκάλων τεχνημάτων—βραχυλογιῶν τε καὶ εἰκονολογιῶν καὶ ὅσα ἄλλα διελθόντες ὑπ᾽ αὐγὰς ἔφαμεν εἶναι σκεπτέα—πότερον","st":"269a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> χαλεπῶς ἂν αὐτούς, ὥσπερ ἐγώ τε καὶ σύ, ὑπ᾽ ἀγροικίας ῥῆμά τι εἰπεῖν ἀπαίδευτον εἰς τοὺς ταῦτα γεγραφότας τε καὶ διδάσκοντας ὡς ῥητορικὴν τέχνην, ἢ ἅτε ἡμῶν ὄντας σοφωτέρους κἂν νῷν ἐπιπλῆξαι εἰπόντας· ὦ Φαῖδρέ τε καὶ Σώκρατες, οὐ χρὴ χαλεπαίνειν ἀλλὰ συγγιγνώσκειν, εἴ τινες μὴ ἐπιστάμενοι διαλέγεσθαι ἀδύνατοι ἐγένοντο ὁρίσασθαι τί ποτ᾽ ἔστιν ῥητορική, ἐκ δὲ τούτου τοῦ πάθους τὰ πρὸ τῆς τέχνης ἀναγκαῖα μαθήματα ἔχοντες ῥητορικὴν ᾠήθησαν","st":"269b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ηὑρηκέναι, καὶ ταῦτα δὴ διδάσκοντες ἄλλους ἡγοῦνταί σφισιν τελέως ῥητορικὴν δεδιδάχθαι, τὸ δὲ ἕκαστα τούτων πιθανῶς λέγειν τε καὶ τὸ ὅλον συνίστασθαι, οὐδὲν ἔργον ὄν, αὐτοὺς δεῖν παρ᾽ ἑαυτῶν τοὺς μαθητὰς σφῶν πορίζεσθαι ἐν τοῖς λόγοις.","st":"269c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀλλὰ μήν, ὦ Σώκρατες, κινδυνεύει γε τοιοῦτόν τι εἶναι τὸ τῆς τέχνης ἣν οὗτοι οἱ ἄνδρες ὡς ῥητορικὴν διδάσκουσίν τε καὶ γράφουσιν, καὶ ἔμοιγε δοκεῖς ἀληθῆ εἰρηκέναι· ἀλλὰ δὴ τὴν τοῦ τῷ ὄντι ῥητορικοῦ τε καὶ πιθανοῦ","st":"269c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τέχνην πῶς καὶ πόθεν ἄν τις δύναιτο πορίσασθαι;","st":"269d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ μὲν δύνασθαι, ὦ Φαῖδρε, ὥστε ἀγωνιστὴν τέλεον γενέσθαι, εἰκός—ἴσως δὲ καὶ ἀναγκαῖον—ἔχειν ὥσπερ τἆλλα· εἰ μέν σοι ὑπάρχει φύσει ῥητορικῷ εἶναι, ἔσῃ ῥήτωρ ἐλλόγιμος, προσλαβὼν ἐπιστήμην τε καὶ μελέτην, ὅτου δ᾽ ἂν ἐλλείπῃς τούτων, ταύτῃ ἀτελὴς ἔσῃ. ὅσον δὲ αὐτοῦ τέχνη, οὐχ ᾗ Λυσίας τε καὶ Θρασύμαχος πορεύεται δοκεῖ μοι φαίνεσθαι ἡ μέθοδος.","st":"269d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀλλὰ πῇ δή;","st":"269d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κινδυνεύει, ὦ ἄριστε, εἰκότως ὁ Περικλῆς πάντων τελεώτατος εἰς τὴν ῥητορικὴν γενέσθαι.","st":"269e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί δή;","st":"269e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πᾶσαι ὅσαι μεγάλαι τῶν τεχνῶν προσδέονται","st":"269e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀδολεσχίας καὶ μετεωρολογίας φύσεως πέρι· τὸ γὰρ ὑψηλόνουν τοῦτο καὶ πάντῃ τελεσιουργὸν ἔοικεν ἐντεῦθέν ποθεν εἰσιέναι. ὃ καὶ Περικλῆς πρὸς τῷ εὐφυὴς εἶναι ἐκτήσατο· προσπεσὼν γὰρ οἶμαι τοιούτῳ ὄντι Ἀναξαγόρᾳ, μετεωρολογίας ἐμπλησθεὶς καὶ ἐπὶ φύσιν νοῦ τε καὶ διανοίας ἀφικόμενος, ὧν δὴ πέρι τὸν πολὺν λόγον ἐποιεῖτο Ἀναξαγόρας, ἐντεῦθεν εἵλκυσεν ἐπὶ τὴν τῶν λόγων τέχνην τὸ πρόσφορον αὐτῇ.","st":"270a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς τοῦτο λέγεις;","st":"270a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ αὐτός που τρόπος τέχνης ἰατρικῆς ὅσπερ καὶ ῥητορικῆς.","st":"270b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πῶς δή;","st":"270b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐν ἀμφοτέραις δεῖ διελέσθαι φύσιν, σώματος μὲν ἐν τῇ ἑτέρᾳ, ψυχῆς δὲ ἐν τῇ ἑτέρᾳ, εἰ μέλλεις, μὴ τριβῇ μόνον καὶ ἐμπειρίᾳ ἀλλὰ τέχνῃ, τῷ μὲν φάρμακα καὶ τροφὴν προσφέρων ὑγίειαν καὶ ῥώμην ἐμποιήσειν, τῇ δὲ λόγους τε καὶ ἐπιτηδεύσεις νομίμους πειθὼ ἣν ἂν βούλῃ καὶ ἀρετὴν παραδώσειν.","st":"270b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸ γοῦν εἰκός, ὦ Σώκρατες, οὕτως.","st":"270b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ψυχῆς οὖν φύσιν ἀξίως λόγου κατανοῆσαι οἴει δυνατὸν εἶναι ἄνευ τῆς τοῦ ὅλου φύσεως;","st":"270c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> εἰ μὲν Ἱπποκράτει γε τῷ τῶν Ἀσκληπιαδῶν δεῖ τι πιθέσθαι, οὐδὲ περὶ σώματος ἄνευ τῆς μεθόδου ταύτης.","st":"270c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς γάρ, ὦ ἑταῖρε, λέγει· χρὴ μέντοι πρὸς τῷ Ἱπποκράτει τὸν λόγον ἐξετάζοντα σκοπεῖν εἰ συμφωνεῖ.","st":"270c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> φημί.","st":"270c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ τοίνυν περὶ φύσεως σκόπει τί ποτε λέγει Ἱπποκράτης τε καὶ ὁ ἀληθὴς λόγος. ἆρ᾽ οὐχ ὧδε δεῖ διανοεῖσθαι","st":"270c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> περὶ ὁτουοῦν φύσεως· πρῶτον μέν, ἁπλοῦν ἢ πολυειδές ἐστιν οὗ πέρι βουλησόμεθα εἶναι αὐτοὶ τεχνικοὶ καὶ ἄλλον δυνατοὶ ποιεῖν, ἔπειτα δέ, ἂν μὲν ἁπλοῦν ᾖ, σκοπεῖν τὴν δύναμιν αὐτοῦ, τίνα πρὸς τί πέφυκεν εἰς τὸ δρᾶν ἔχον ἢ τίνα εἰς τὸ παθεῖν ὑπὸ τοῦ, ἐὰν δὲ πλείω εἴδη ἔχῃ, ταῦτα ἀριθμησάμενον, ὅπερ ἐφ᾽ ἑνός, τοῦτ᾽ ἰδεῖν ἐφ᾽ ἑκάστου, τῷ τί ποιεῖν αὐτὸ πέφυκεν ἢ τῷ τί παθεῖν ὑπὸ τοῦ;","st":"270d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> κινδυνεύει, ὦ Σώκρατες.","st":"270d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἡ γοῦν ἄνευ τούτων μέθοδος ἐοίκοι ἂν ὥσπερ","st":"270d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τυφλοῦ πορείᾳ. ἀλλ᾽ οὐ μὴν ἀπεικαστέον τόν γε τέχνῃ μετιόντα ὁτιοῦν τυφλῷ οὐδὲ κωφῷ, ἀλλὰ δῆλον ὡς, ἄν τῴ τις τέχνῃ λόγους διδῷ, τὴν οὐσίαν δείξει ἀκριβῶς τῆς φύσεως τούτου πρὸς ὃ τοὺς λόγους προσοίσει· ἔσται δέ που ψυχὴ τοῦτο.","st":"270e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"270e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἡ ἅμιλλα αὐτῷ τέταται πρὸς τοῦτο πᾶσα· πειθὼ γὰρ ἐν τούτῳ ποιεῖν ἐπιχειρεῖ. ἦ γάρ;","st":"271a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί.","st":"271a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δῆλον ἄρα ὅτι ὁ Θρασύμαχός τε καὶ ὃς ἂν ἄλλος σπουδῇ τέχνην ῥητορικὴν διδῷ, πρῶτον πάσῃ ἀκριβείᾳ γράψει τε καὶ ποιήσει ψυχὴν ἰδεῖν, πότερον ἓν καὶ ὅμοιον πέφυκεν ἢ κατὰ σώματος μορφὴν πολυειδές· τοῦτο γάρ φαμεν φύσιν εἶναι δεικνύναι.","st":"271a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παντάπασι μὲν οὖν.","st":"271a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεύτερον δέ γε, ὅτῳ τί ποιεῖν ἢ παθεῖν ὑπὸ τοῦ πέφυκεν.","st":"271a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"271a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τρίτον δὲ δὴ διαταξάμενος τὰ λόγων τε καὶ ψυχῆς γένη καὶ τὰ τούτων παθήματα δίεισι πάσας αἰτίας, προσαρμόττων ἕκαστον ἑκάστῳ καὶ διδάσκων οἵα οὖσα ὑφ᾽ οἵων λόγων δι᾽ ἣν αἰτίαν ἐξ ἀνάγκης ἡ μὲν πείθεται, ἡ δὲ ἀπειθεῖ.","st":"271b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> κάλλιστα γοῦν ἄν, ὡς ἔοικ᾽, ἔχοι οὕτως.","st":"271b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὔτοι μὲν οὖν, ὦ φίλε, ἄλλως ἐνδεικνύμενον ἢ λεγόμενον τέχνῃ ποτὲ λεχθήσεται ἢ γραφήσεται οὔτε τι","st":"271b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἄλλο οὔτε τοῦτο. ἀλλ᾽ οἱ νῦν γράφοντες, ὧν σὺ ἀκήκοας, τέχνας λόγων πανοῦργοί εἰσιν καὶ ἀποκρύπτονται, εἰδότες ψυχῆς πέρι παγκάλως· πρὶν ἂν οὖν τὸν τρόπον τοῦτον λέγωσί τε καὶ γράφωσι, μὴ πειθώμεθα αὐτοῖς τέχνῃ γράφειν.","st":"271c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τίνα τοῦτον;","st":"271c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> αὐτὰ μὲν τὰ ῥήματα εἰπεῖν οὐκ εὐπετές· ὡς δὲ δεῖ γράφειν, εἰ μέλλει τεχνικῶς ἔχειν καθ᾽ ὅσον ἐνδέχεται, λέγειν ἐθέλω.","st":"271c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> λέγε δή.","st":"271c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐπειδὴ λόγου δύναμις τυγχάνει ψυχαγωγία οὖσα,","st":"271c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν μέλλοντα ῥητορικὸν ἔσεσθαι ἀνάγκη εἰδέναι ψυχὴ ὅσα εἴδη ἔχει. ἔστιν οὖν τόσα καὶ τόσα, καὶ τοῖα καὶ τοῖα, ὅθεν οἱ μὲν τοιοίδε, οἱ δὲ τοιοίδε γίγνονται· τούτων δὲ δὴ οὕτω διῃρημένων, λόγων αὖ τόσα καὶ τόσα ἔστιν εἴδη, τοιόνδε ἕκαστον. οἱ μὲν οὖν τοιοίδε ὑπὸ τῶν τοιῶνδε λόγων διὰ τήνδε τὴν αἰτίαν ἐς τὰ τοιάδε εὐπειθεῖς, οἱ δὲ τοιοίδε διὰ τάδε δυσπειθεῖς· δεῖ δὴ ταῦτα ἱκανῶς νοήσαντα, μετὰ ταῦτα θεώμενον αὐτὰ ἐν ταῖς πράξεσιν ὄντα τε καὶ πραττόμενα,","st":"271d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὀξέως τῇ αἰσθήσει δύνασθαι ἐπακολουθεῖν, ἢ μηδὲν εἶναί πω πλέον αὐτῷ ὧν τότε ἤκουεν λόγων συνών.","st":"271e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅταν δὲ εἰπεῖν τε ἱκανῶς ἔχῃ οἷος ὑφ᾽ οἵων πείθεται, παραγιγνόμενόν τε δυνατὸς ᾖ διαισθανόμενος ἑαυτῷ ἐνδείκνυσθαι ὅτι","st":"271e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὗτός ἐστι καὶ αὕτη ἡ φύσις περὶ ἧς τότε ἦσαν οἱ λόγοι, νῦν ἔργῳ παροῦσά οἱ, ᾗ προσοιστέον τούσδε ὧδε τοὺς λόγους ἐπὶ τὴν τῶνδε πειθώ, ταῦτα δ᾽ ἤδη πάντα ἔχοντι, προσλαβόντι καιροὺς τοῦ πότε λεκτέον καὶ ἐπισχετέον, βραχυλογίας τε αὖ καὶ ἐλεινολογίας καὶ δεινώσεως ἑκάστων τε ὅσα ἂν εἴδη μάθῃ λόγων, τούτων τὴν εὐκαιρίαν τε καὶ ἀκαιρίαν διαγνόντι, καλῶς τε καὶ τελέως ἐστὶν ἡ τέχνη ἀπειργασμένη, πρότερον δ᾽ οὔ· ἀλλ᾽ ὅτι ἂν αὐτῶν τις","st":"272a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἐλλείπῃ λέγων ἢ διδάσκων ἢ γράφων, φῇ δὲ τέχνῃ λέγειν, ὁ μὴ πειθόμενος κρατεῖ. τί δὴ οὖν; φήσει ἴσως ὁ συγγραφεύς, ὦ Φαῖδρέ τε καὶ Σώκρατες, δοκεῖ οὕτως; μὴ ἄλλως πως ἀποδεκτέον λεγομένης λόγων τέχνης;","st":"272b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἀδύνατόν που, ὦ Σώκρατες, ἄλλως· καίτοι οὐ σμικρόν γε φαίνεται ἔργον.","st":"272b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθῆ λέγεις. τούτου τοι ἕνεκα χρὴ πάντας τοὺς λόγους ἄνω καὶ κάτω μεταστρέφοντα ἐπισκοπεῖν εἴ τίς πῃ","st":"272b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ῥᾴων καὶ βραχυτέρα φαίνεται ἐπ᾽ αὐτὴν ὁδός, ἵνα μὴ μάτην πολλὴν ἀπίῃ καὶ τραχεῖαν, ἐξὸν ὀλίγην τε καὶ λείαν. ἀλλ᾽ εἴ τινά πῃ βοήθειαν ἔχεις ἐπακηκοὼς Λυσίου ἤ τινος ἄλλου, πειρῶ λέγειν ἀναμιμνῃσκόμενος.","st":"272c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἕνεκα μὲν πείρας ἔχοιμ᾽ ἄν, ἀλλ᾽ οὔτι νῦν γ᾽ οὕτως ἔχω.","st":"272c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βούλει οὖν ἐγώ τιν᾽ εἴπω λόγον ὃν τῶν περὶ ταῦτά τινων ἀκήκοα;","st":"272c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"272c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγεται γοῦν, ὦ Φαῖδρε, δίκαιον εἶναι καὶ τὸ τοῦ λύκου εἰπεῖν.","st":"272c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ σύ γε οὕτω ποίει.","st":"272d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φασὶ τοίνυν οὐδὲν οὕτω ταῦτα δεῖν σεμνύνειν οὐδ᾽ ἀνάγειν ἄνω μακρὰν περιβαλλομένους· παντάπασι γάρ, ὃ καὶ κατ᾽ ἀρχὰς εἴπομεν τοῦδε τοῦ λόγου, ὅτι οὐδὲν ἀληθείας μετέχειν δέοι δικαίων ἢ ἀγαθῶν πέρι πραγμάτων, ἢ καὶ ἀνθρώπων γε τοιούτων φύσει ὄντων ἢ τροφῇ, τὸν μέλλοντα ἱκανῶς ῥητορικὸν ἔσεσθαι. τὸ παράπαν γὰρ οὐδὲν ἐν τοῖς δικαστηρίοις τούτων ἀληθείας μέλειν οὐδενί, ἀλλὰ τοῦ πιθανοῦ·","st":"272d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο δ᾽ εἶναι τὸ εἰκός, ᾧ δεῖν προσέχειν τὸν μέλλοντα τέχνῃ ἐρεῖν. οὐδὲ γὰρ αὐτὰ τὰ πραχθέντα δεῖν λέγειν ἐνίοτε, ἐὰν μὴ εἰκότως ᾖ πεπραγμένα, ἀλλὰ τὰ εἰκότα, ἔν τε κατηγορίᾳ καὶ ἀπολογίᾳ, καὶ πάντως λέγοντα τὸ δὴ εἰκὸς διωκτέον εἶναι, πολλὰ εἰπόντα χαίρειν τῷ ἀληθεῖ· τοῦτο γὰρ διὰ","st":"272e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παντὸς τοῦ λόγου γιγνόμενον τὴν ἅπασαν τέχνην πορίζειν.","st":"273a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> αὐτά γε, ὦ Σώκρατες, διελήλυθας ἃ λέγουσιν οἱ περὶ τοὺς λόγους τεχνικοὶ προσποιούμενοι εἶναι· ἀνεμνήσθην γὰρ ὅτι ἐν τῷ πρόσθεν βραχέως τοῦ τοιούτου ἐφηψάμεθα, δοκεῖ δὲ τοῦτο πάμμεγα εἶναι τοῖς περὶ ταῦτα.","st":"273a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ μὴν τόν γε Τεισίαν αὐτὸν πεπάτηκας ἀκριβῶς· εἰπέτω τοίνυν καὶ τόδε ἡμῖν ὁ Τεισίας, μή τι ἄλλο λέγει","st":"273a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ εἰκὸς ἢ τὸ τῷ πλήθει δοκοῦν.","st":"273b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί γὰρ ἄλλο;","st":"273b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τοῦτο δή, ὡς ἔοικε, σοφὸν εὑρὼν ἅμα καὶ τεχνικὸν ἔγραψεν ὡς ἐάν τις ἀσθενὴς καὶ ἀνδρικὸς ἰσχυρὸν καὶ δειλὸν συγκόψας, ἱμάτιον ἤ τι ἄλλο ἀφελόμενος, εἰς δικαστήριον ἄγηται, δεῖ δὴ τἀληθὲς μηδέτερον λέγειν, ἀλλὰ τὸν μὲν δειλὸν μὴ ὑπὸ μόνου φάναι τοῦ ἀνδρικοῦ συγκεκόφθαι, τὸν δὲ τοῦτο μὲν ἐλέγχειν ὡς μόνω ἤστην, ἐκείνῳ δὲ καταχρήσασθαι","st":"273b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῷ πῶς δ᾽ ἂν ἐγὼ τοιόσδε τοιῷδε ἐπεχείρησα; ὁ δ᾽ οὐκ ἐρεῖ δὴ τὴν ἑαυτοῦ κάκην, ἀλλά τι ἄλλο ψεύδεσθαι ἐπιχειρῶν τάχ᾽ ἂν ἔλεγχόν πῃ παραδοίη τῷ ἀντιδίκῳ. καὶ περὶ τἆλλα δὴ τοιαῦτ᾽ ἄττα ἐστὶ τὰ τέχνῃ λεγόμενα. οὐ γάρ, ὦ Φαῖδρε;","st":"273c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"273c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> φεῦ, δεινῶς γ᾽ ἔοικεν ἀποκεκρυμμένην τέχνην ἀνευρεῖν ὁ Τεισίας ἢ ἄλλος ὅστις δή ποτ᾽ ὢν τυγχάνει καὶ ὁπόθεν χαίρει ὀνομαζόμενος. ἀτάρ, ὦ ἑταῖρε, τούτῳ ἡμεῖς πότερον λέγωμεν ἢ μὴ—","st":"273c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸ ποῖον;","st":"273d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὅτι, ὦ Τεισία, πάλαι ἡμεῖς, πρὶν καὶ σὲ παρελθεῖν, τυγχάνομεν λέγοντες ὡς ἄρα τοῦτο τὸ εἰκὸς τοῖς πολλοῖς δι᾽ ὁμοιότητα τοῦ ἀληθοῦς τυγχάνει ἐγγιγνόμενον· τὰς δὲ ὁμοιότητας ἄρτι διήλθομεν ὅτι πανταχοῦ ὁ τὴν ἀλήθειαν εἰδὼς κάλλιστα ἐπίσταται εὑρίσκειν. ὥστ᾽ εἰ μὲν ἄλλο τι περὶ τέχνης λόγων λέγεις, ἀκούοιμεν ἄν· εἰ δὲ μή, οἷς νυνδὴ διήλθομεν πεισόμεθα, ὡς ἐὰν μή τις τῶν τε ἀκουσομένων","st":"273d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὰς φύσεις διαριθμήσηται, καὶ κατ᾽ εἴδη τε διαιρεῖσθαι τὰ ὄντα καὶ μιᾷ ἰδέᾳ δυνατὸς ᾖ καθ᾽ ἓν ἕκαστον περιλαμβάνειν, οὔ ποτ᾽ ἔσται τεχνικὸς λόγων πέρι καθ᾽ ὅσον δυνατὸν ἀνθρώπῳ. ταῦτα δὲ οὐ μή ποτε κτήσηται ἄνευ πολλῆς πραγματείας· ἣν οὐχ ἕνεκα τοῦ λέγειν καὶ πράττειν πρὸς ἀνθρώπους δεῖ διαπονεῖσθαι τὸν σώφρονα, ἀλλὰ τοῦ θεοῖς κεχαρισμένα μὲν λέγειν δύνασθαι, κεχαρισμένως δὲ πράττειν τὸ πᾶν εἰς δύναμιν.","st":"273e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γὰρ δὴ ἄρα, ὦ Τεισία, φασὶν οἱ σοφώτεροι ἡμῶν, ὁμοδούλοις δεῖ χαρίζεσθαι","st":"273e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> μελετᾶν τὸν νοῦν ἔχοντα, ὅτι μὴ πάρεργον, ἀλλὰ δεσπόταις ἀγαθοῖς τε καὶ ἐξ ἀγαθῶν. ὥστ᾽ εἰ μακρὰ ἡ περίοδος, μὴ θαυμάσῃς· μεγάλων γὰρ ἕνεκα περιιτέον, οὐχ ὡς σὺ δοκεῖς. ἔσται μήν, ὡς ὁ λόγος φησίν, ἐάν τις ἐθέλῃ, καὶ ταῦτα κάλλιστα ἐξ ἐκείνων γιγνόμενα.","st":"274a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παγκάλως ἔμοιγε δοκεῖ λέγεσθαι, ὦ Σώκρατες, εἴπερ οἷός τέ τις εἴη.","st":"274a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀλλὰ καὶ ἐπιχειροῦντί τοι τοῖς καλοῖς καλὸν καὶ","st":"274a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πάσχειν ὅτι ἄν τῳ συμβῇ παθεῖν.","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ μάλα.","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν τὸ μὲν τέχνης τε καὶ ἀτεχνίας λόγων πέρι ἱκανῶς ἐχέτω.","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ δ᾽ εὐπρεπείας δὴ γραφῆς πέρι καὶ ἀπρεπείας, πῇ γιγνόμενον καλῶς ἂν ἔχοι καὶ ὅπῃ ἀπρεπῶς, λοιπόν. ἦ γάρ;","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ναί.","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἶσθ᾽ οὖν ὅπῃ μάλιστα θεῷ χαριῇ λόγων πέρι πράττων ἢ λέγων;","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐδαμῶς· σὺ δέ;","st":"274b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀκοήν γ᾽ ἔχω λέγειν τῶν προτέρων, τὸ δ᾽ ἀληθὲς αὐτοὶ ἴσασιν. εἰ δὲ τοῦτο εὕροιμεν αὐτοί, ἆρά γ᾽ ἂν ἔθ᾽ ἡμῖν μέλοι τι τῶν ἀνθρωπίνων δοξασμάτων;","st":"274c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> γελοῖον ἤρου· ἀλλ᾽ ἃ φῂς ἀκηκοέναι λέγε.","st":"274c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἤκουσα τοίνυν περὶ Ναύκρατιν τῆς Αἰγύπτου γενέσθαι τῶν ἐκεῖ παλαιῶν τινα θεῶν, οὗ καὶ τὸ ὄρνεον ἱερὸν ὃ δὴ καλοῦσιν Ἶβιν· αὐτῷ δὲ ὄνομα τῷ δαίμονι εἶναι Θεύθ. τοῦτον δὴ πρῶτον ἀριθμόν τε καὶ λογισμὸν εὑρεῖν καὶ","st":"274c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γεωμετρίαν καὶ ἀστρονομίαν, ἔτι δὲ πεττείας τε καὶ κυβείας, καὶ δὴ καὶ γράμματα. βασιλέως δ᾽ αὖ τότε ὄντος Αἰγύπτου ὅλης Θαμοῦ περὶ τὴν μεγάλην πόλιν τοῦ ἄνω τόπου ἣν οἱ Ἕλληνες Αἰγυπτίας Θήβας καλοῦσι, καὶ τὸν θεὸν Ἄμμωνα, παρὰ τοῦτον ἐλθὼν ὁ Θεὺθ τὰς τέχνας ἐπέδειξεν, καὶ ἔφη δεῖν διαδοθῆναι τοῖς ἄλλοις Αἰγυπτίοις· ὁ δὲ ἤρετο ἥντινα ἑκάστη ἔχοι ὠφελίαν, διεξιόντος δέ, ὅτι καλῶς ἢ μὴ","st":"274d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καλῶς δοκοῖ λέγειν, τὸ μὲν ἔψεγεν, τὸ δ᾽ ἐπῄνει. πολλὰ μὲν δὴ περὶ ἑκάστης τῆς τέχνης ἐπ᾽ ἀμφότερα Θαμοῦν τῷ Θεὺθ λέγεται ἀποφήνασθαι, ἃ λόγος πολὺς ἂν εἴη διελθεῖν· ἐπειδὴ δὲ ἐπὶ τοῖς γράμμασιν ἦν, τοῦτο δέ, ὦ βασιλεῦ, τὸ μάθημα, ἔφη ὁ Θεύθ, σοφωτέρους Αἰγυπτίους καὶ μνημονικωτέρους παρέξει· μνήμης τε γὰρ καὶ σοφίας φάρμακον ηὑρέθη.","st":"274e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δ᾽ εἶπεν· ὦ τεχνικώτατε Θεύθ, ἄλλος μὲν τεκεῖν δυνατὸς τὰ τέχνης, ἄλλος δὲ κρῖναι τίν᾽ ἔχει μοῖραν βλάβης τε καὶ ὠφελίας τοῖς μέλλουσι χρῆσθαι· καὶ νῦν","st":"274e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> σύ, πατὴρ ὢν γραμμάτων, δι᾽ εὔνοιαν τοὐναντίον εἶπες ἢ δύναται. τοῦτο γὰρ τῶν μαθόντων λήθην μὲν ἐν ψυχαῖς παρέξει μνήμης ἀμελετησίᾳ, ἅτε διὰ πίστιν γραφῆς ἔξωθεν ὑπ᾽ ἀλλοτρίων τύπων, οὐκ ἔνδοθεν αὐτοὺς ὑφ᾽ αὑτῶν ἀναμιμνῃσκομένους· οὔκουν μνήμης ἀλλὰ ὑπομνήσεως φάρμακον ηὗρες. σοφίας δὲ τοῖς μαθηταῖς δόξαν, οὐκ ἀλήθειαν πορίζεις· πολυήκοοι γάρ σοι γενόμενοι ἄνευ διδαχῆς πολυγνώμονες","st":"275a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναι δόξουσιν, ἀγνώμονες ὡς ἐπὶ τὸ πλῆθος ὄντες, καὶ χαλεποὶ συνεῖναι, δοξόσοφοι γεγονότες ἀντὶ σοφῶν.","st":"275b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ὦ Σώκρατες, ῥᾳδίως σὺ Αἰγυπτίους καὶ ὁποδαποὺς ἂν ἐθέλῃς λόγους ποιεῖς.","st":"275b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οἱ δέ γ᾽, ὦ φίλε, ἐν τῷ τοῦ Διὸς τοῦ Δωδωναίου ἱερῷ δρυὸς λόγους ἔφησαν μαντικοὺς πρώτους γενέσθαι. τοῖς μὲν οὖν τότε, ἅτε οὐκ οὖσι σοφοῖς ὥσπερ ὑμεῖς οἱ νέοι, ἀπέχρη δρυὸς καὶ πέτρας ἀκούειν ὑπ᾽ εὐηθείας, εἰ μόνον","st":"275b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἀληθῆ λέγοιεν· σοὶ δ᾽ ἴσως διαφέρει τίς ὁ λέγων καὶ ποδαπός. οὐ γὰρ ἐκεῖνο μόνον σκοπεῖς, εἴτε οὕτως εἴτε ἄλλως ἔχει;","st":"275c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ὀρθῶς ἐπέπληξας, καί μοι δοκεῖ περὶ γραμμάτων ἔχειν ᾗπερ ὁ Θηβαῖος λέγει.","st":"275c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ὁ τέχνην οἰόμενος ἐν γράμμασι καταλιπεῖν, καὶ αὖ ὁ παραδεχόμενος ὥς τι σαφὲς καὶ βέβαιον ἐκ γραμμάτων ἐσόμενον, πολλῆς ἂν εὐηθείας γέμοι καὶ τῷ ὄντι τὴν Ἄμμωνος μαντείαν ἀγνοοῖ, πλέον τι οἰόμενος εἶναι λόγους","st":"275c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γεγραμμένους τοῦ τὸν εἰδότα ὑπομνῆσαι περὶ ὧν ἂν ᾖ τὰ γεγραμμένα.","st":"275d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ὀρθότατα.","st":"275d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δεινὸν γάρ που, ὦ Φαῖδρε, τοῦτ᾽ ἔχει γραφή, καὶ ὡς ἀληθῶς ὅμοιον ζωγραφίᾳ. καὶ γὰρ τὰ ἐκείνης ἔκγονα ἕστηκε μὲν ὡς ζῶντα, ἐὰν δ᾽ ἀνέρῃ τι, σεμνῶς πάνυ σιγᾷ. ταὐτὸν δὲ καὶ οἱ λόγοι· δόξαις μὲν ἂν ὥς τι φρονοῦντας αὐτοὺς λέγειν, ἐὰν δέ τι ἔρῃ τῶν λεγομένων βουλόμενος μαθεῖν, ἕν τι σημαίνει μόνον ταὐτὸν ἀεί. ὅταν δὲ ἅπαξ","st":"275d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γραφῇ, κυλινδεῖται μὲν πανταχοῦ πᾶς λόγος ὁμοίως παρὰ τοῖς ἐπαΐουσιν, ὡς δ᾽ αὕτως παρ᾽ οἷς οὐδὲν προσήκει, καὶ οὐκ ἐπίσταται λέγειν οἷς δεῖ γε καὶ μή. πλημμελούμενος δὲ καὶ οὐκ ἐν δίκῃ λοιδορηθεὶς τοῦ πατρὸς ἀεὶ δεῖται βοηθοῦ· αὐτὸς γὰρ οὔτ᾽ ἀμύνασθαι οὔτε βοηθῆσαι δυνατὸς αὑτῷ.","st":"275e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ ταῦτά σοι ὀρθότατα εἴρηται.","st":"275e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽; ἄλλον ὁρῶμεν λόγον τούτου ἀδελφὸν γνήσιον, τῷ τρόπῳ τε γίγνεται, καὶ ὅσῳ ἀμείνων καὶ δυνατώτερος τούτου φύεται;","st":"276a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τίνα τοῦτον καὶ πῶς λέγεις γιγνόμενον;","st":"276a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὃς μετ᾽ ἐπιστήμης γράφεται ἐν τῇ τοῦ μανθάνοντος ψυχῇ, δυνατὸς μὲν ἀμῦναι ἑαυτῷ, ἐπιστήμων δὲ λέγειν τε καὶ σιγᾶν πρὸς οὓς δεῖ.","st":"276a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸν τοῦ εἰδότος λόγον λέγεις ζῶντα καὶ ἔμψυχον, οὗ ὁ γεγραμμένος εἴδωλον ἄν τι λέγοιτο δικαίως.","st":"276a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> παντάπασι μὲν οὖν. τόδε δή μοι εἰπέ· ὁ νοῦν ἔχων γεωργός, ὧν σπερμάτων κήδοιτο καὶ ἔγκαρπα βούλοιτο γενέσθαι, πότερα σπουδῇ ἂν θέρους εἰς Ἀδώνιδος κήπους ἀρῶν χαίροι θεωρῶν καλοὺς ἐν ἡμέραισιν ὀκτὼ γιγνομένους, ἢ ταῦτα μὲν δὴ παιδιᾶς τε καὶ ἑορτῆς χάριν δρῴη ἄν, ὅτε καὶ ποιοῖ· ἐφ᾽ οἷς δὲ ἐσπούδακεν, τῇ γεωργικῇ χρώμενος ἂν τέχνῃ, σπείρας εἰς τὸ προσῆκον, ἀγαπῴη ἂν ἐν ὀγδόῳ μηνὶ ὅσα ἔσπειρεν τέλος λαβόντα;","st":"276b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὕτω που, ὦ Σώκρατες, τὰ μὲν σπουδῇ, τὰ δὲ ὡς ἑτέρως ἂν ᾗ λέγεις ποιοῖ.","st":"276c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸν δὲ δικαίων τε καὶ καλῶν καὶ ἀγαθῶν ἐπιστήμας ἔχοντα τοῦ γεωργοῦ φῶμεν ἧττον νοῦν ἔχειν εἰς τὰ ἑαυτοῦ σπέρματα;","st":"276c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἥκιστά γε.","st":"276c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκ ἄρα σπουδῇ αὐτὰ ἐν ὕδατι γράψει μέλανι σπείρων διὰ καλάμου μετὰ λόγων ἀδυνάτων μὲν αὑτοῖς λόγῳ βοηθεῖν, ἀδυνάτων δὲ ἱκανῶς τἀληθῆ διδάξαι.","st":"276c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὔκουν δὴ τό γ᾽ εἰκός.","st":"276c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐ γάρ· ἀλλὰ τοὺς μὲν ἐν γράμμασι κήπους, ὡς ἔοικε, παιδιᾶς χάριν σπερεῖ τε καὶ γράψει, ὅταν γράφῃ, ἑαυτῷ τε ὑπομνήματα θησαυριζόμενος, εἰς τὸ λήθης γῆρας ἐὰν ἵκηται, καὶ παντὶ τῷ ταὐτὸν ἴχνος μετιόντι, ἡσθήσεταί τε αὐτοὺς θεωρῶν φυομένους ἁπαλούς· ὅταν δὲ ἄλλοι παιδιαῖς ἄλλαις χρῶνται, συμποσίοις τε ἄρδοντες αὑτοὺς ἑτέροις τε ὅσα τούτων ἀδελφά, τότ᾽ ἐκεῖνος, ὡς ἔοικεν, ἀντὶ τούτων οἷς λέγω παίζων διάξει.","st":"276d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παγκάλην λέγεις παρὰ φαύλην παιδιάν, ὦ Σώκρατες, τοῦ ἐν λόγοις δυναμένου παίζειν, δικαιοσύνης τε καὶ ἄλλων ὧν λέγεις πέρι μυθολογοῦντα.","st":"276e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἔστι γάρ, ὦ φίλε Φαῖδρε, οὕτω· πολὺ δ᾽ οἶμαι καλλίων σπουδὴ περὶ αὐτὰ γίγνεται, ὅταν τις τῇ διαλεκτικῇ τέχνῃ χρώμενος, λαβὼν ψυχὴν προσήκουσαν, φυτεύῃ τε καὶ σπείρῃ μετ᾽ ἐπιστήμης λόγους, οἳ ἑαυτοῖς τῷ τε φυτεύσαντι","st":"276e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> βοηθεῖν ἱκανοὶ καὶ οὐχὶ ἄκαρποι ἀλλὰ ἔχοντες σπέρμα, ὅθεν ἄλλοι ἐν ἄλλοις ἤθεσι φυόμενοι τοῦτ᾽ ἀεὶ ἀθάνατον παρέχειν ἱκανοί, καὶ τὸν ἔχοντα εὐδαιμονεῖν ποιοῦντες εἰς ὅσον ἀνθρώπῳ δυνατὸν μάλιστα.","st":"277a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> πολὺ γὰρ τοῦτ᾽ ἔτι κάλλιον λέγεις.","st":"277a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νῦν δὴ ἐκεῖνα ἤδη, ὦ Φαῖδρε, δυνάμεθα κρίνειν, τούτων ὡμολογημένων.","st":"277a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὰ ποῖα;","st":"277a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὧν δὴ πέρι βουληθέντες ἰδεῖν ἀφικόμεθα εἰς τόδε, ὅπως τὸ Λυσίου τε ὄνειδος ἐξετάσαιμεν τῆς τῶν λόγων","st":"277a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> γραφῆς πέρι, καὶ αὐτοὺς τοὺς λόγους οἳ τέχνῃ καὶ ἄνευ τέχνης γράφοιντο. τὸ μὲν οὖν ἔντεχνον καὶ μὴ δοκεῖ μοι δεδηλῶσθαι μετρίως.","st":"277b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ἔδοξέ γε δή· πάλιν δὲ ὑπόμνησόν με πῶς.","st":"277b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> πρὶν ἄν τις τό τε ἀληθὲς ἑκάστων εἰδῇ πέρι ὧν λέγει ἢ γράφει, κατ᾽ αὐτό τε πᾶν ὁρίζεσθαι δυνατὸς γένηται, ὁρισάμενός τε πάλιν κατ᾽ εἴδη μέχρι τοῦ ἀτμήτου τέμνειν ἐπιστηθῇ, περί τε ψυχῆς φύσεως διιδὼν κατὰ ταὐτά, τὸ","st":"277b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> προσαρμόττον ἑκάστῃ φύσει εἶδος ἀνευρίσκων, οὕτω τιθῇ καὶ διακοσμῇ τὸν λόγον, ποικίλῃ μὲν ποικίλους ψυχῇ καὶ παναρμονίους διδοὺς λόγους, ἁπλοῦς δὲ ἁπλῇ, οὐ πρότερον δυνατὸν τέχνῃ ἔσεσθαι καθ᾽ ὅσον πέφυκε μεταχειρισθῆναι τὸ λόγων γένος, οὔτε τι πρὸς τὸ διδάξαι οὔτε τι πρὸς τὸ πεῖσαι, ὡς ὁ ἔμπροσθεν πᾶς μεμήνυκεν ἡμῖν λόγος.","st":"277c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παντάπασι μὲν οὖν τοῦτό γε οὕτω πως ἐφάνη.","st":"277c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τί δ᾽ αὖ περὶ τοῦ καλὸν ἢ αἰσχρὸν εἶναι τὸ λόγους λέγειν τε καὶ γράφειν, καὶ ὅπῃ γιγνόμενον ἐν δίκῃ λέγοιτ᾽ ἂν ὄνειδος ἢ μή, ἆρα οὐ δεδήλωκεν τὰ λεχθέντα ὀλίγον ἔμπροσθεν—","st":"277d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὰ ποῖα;","st":"277d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὡς εἴτε Λυσίας ἤ τις ἄλλος πώποτε ἔγραψεν ἢ γράψει ἰδίᾳ ἢ δημοσίᾳ νόμους τιθείς, σύγγραμμα πολιτικὸν γράφων καὶ μεγάλην τινὰ ἐν αὐτῷ βεβαιότητα ἡγούμενος καὶ σαφήνειαν, οὕτω μὲν ὄνειδος τῷ γράφοντι, εἴτε τίς φησιν εἴτε μή· τὸ γὰρ ἀγνοεῖν ὕπαρ τε καὶ ὄναρ δικαίων","st":"277d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> καὶ ἀδίκων πέρι καὶ κακῶν καὶ ἀγαθῶν οὐκ ἐκφεύγει τῇ ἀληθείᾳ μὴ οὐκ ἐπονείδιστον εἶναι, οὐδὲ ἂν ὁ πᾶς ὄχλος αὐτὸ ἐπαινέσῃ.","st":"277e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> οὐ γὰρ οὖν.","st":"277e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὁ δέ γε ἐν μὲν τῷ γεγραμμένῳ λόγῳ περὶ ἑκάστου παιδιάν τε ἡγούμενος πολλὴν ἀναγκαῖον εἶναι, καὶ οὐδένα πώποτε λόγον ἐν μέτρῳ οὐδ᾽ ἄνευ μέτρου μεγάλης ἄξιον σπουδῆς γραφῆναι, οὐδὲ λεχθῆναι ὡς οἱ ῥαψῳδούμενοι ἄνευ ἀνακρίσεως καὶ διδαχῆς πειθοῦς ἕνεκα ἐλέχθησαν, ἀλλὰ τῷ","st":"277e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὄντι αὐτῶν τοὺς βελτίστους εἰδότων ὑπόμνησιν γεγονέναι, ἐν δὲ τοῖς διδασκομένοις καὶ μαθήσεως χάριν λεγομένοις καὶ τῷ ὄντι γραφομένοις ἐν ψυχῇ περὶ δικαίων τε καὶ καλῶν καὶ ἀγαθῶν μόνοις ἡγούμενος τό τε ἐναργὲς εἶναι καὶ τέλεον καὶ ἄξιον σπουδῆς· δεῖν δὲ τοὺς τοιούτους λόγους αὑτοῦ λέγεσθαι οἷον ὑεῖς γνησίους εἶναι, πρῶτον μὲν τὸν ἐν αὑτῷ, ἐὰν εὑρεθεὶς ἐνῇ, ἔπειτα εἴ τινες τούτου ἔκγονοί","st":"278a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τε καὶ ἀδελφοὶ ἅμα ἐν ἄλλαισιν ἄλλων ψυχαῖς κατ᾽ ἀξίαν ἐνέφυσαν· τοὺς δὲ ἄλλους χαίρειν ἐῶν—οὗτος δὲ ὁ τοιοῦτος ἀνὴρ κινδυνεύει, ὦ Φαῖδρε, εἶναι οἷον ἐγώ τε καὶ σὺ εὐξαίμεθ᾽ ἂν σέ τε καὶ ἐμὲ γενέσθαι.","st":"278b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> παντάπασι μὲν οὖν ἔγωγε βούλομαί τε καὶ εὔχομαι ἃ λέγεις.","st":"278b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν ἤδη πεπαίσθω μετρίως ἡμῖν τὰ περὶ λόγων· καὶ σύ τε ἐλθὼν φράζε Λυσίᾳ ὅτι νὼ καταβάντε ἐς τὸ Νυμφῶν νᾶμά τε καὶ μουσεῖον ἠκούσαμεν λόγων, οἳ ἐπέστελλον","st":"278b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγειν Λυσίᾳ τε καὶ εἴ τις ἄλλος συντίθησι λόγους, καὶ Ὁμήρῳ καὶ εἴ τις ἄλλος αὖ ποίησιν ψιλὴν ἢ ἐν ᾠδῇ συντέθηκε, τρίτον δὲ Σόλωνι καὶ ὅστις ἐν πολιτικοῖς λόγοις νόμους ὀνομάζων συγγράμματα ἔγραψεν· εἰ μὲν εἰδὼς ᾗ τὸ ἀληθὲς ἔχει συνέθηκε ταῦτα, καὶ ἔχων βοηθεῖν, εἰς ἔλεγχον ἰὼν περὶ ὧν ἔγραψε, καὶ λέγων αὐτὸς δυνατὸς τὰ γεγραμμένα φαῦλα ἀποδεῖξαι, οὔ τι τῶνδε ἐπωνυμίαν ἔχοντα δεῖ","st":"278c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> λέγεσθαι τὸν τοιοῦτον, ἀλλ᾽ ἐφ᾽ οἷς ἐσπούδακεν ἐκείνων.","st":"278d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τίνας οὖν τὰς ἐπωνυμίας αὐτῷ νέμεις;","st":"278d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τὸ μὲν σοφόν, ὦ Φαῖδρε, καλεῖν ἔμοιγε μέγα εἶναι δοκεῖ καὶ θεῷ μόνῳ πρέπειν· τὸ δὲ ἢ φιλόσοφον ἢ τοιοῦτόν τι μᾶλλόν τε ἂν αὐτῷ καὶ ἁρμόττοι καὶ ἐμμελεστέρως ἔχοι.","st":"278d"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ οὐδέν γε ἀπὸ τρόπου.","st":"278d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν αὖ τὸν μὴ ἔχοντα τιμιώτερα ὧν συνέθηκεν ἢ ἔγραψεν ἄνω κάτω στρέφων ἐν χρόνῳ, πρὸς ἄλληλα","st":"278d"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κολλῶν τε καὶ ἀφαιρῶν, ἐν δίκῃ που ποιητὴν ἢ λόγων συγγραφέα ἢ νομογράφον προσερεῖς;","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ταῦτα τοίνυν τῷ ἑταίρῳ φράζε.","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί δὲ σύ; πῶς ποιήσεις; οὐδὲ γὰρ οὐδὲ τὸν σὸν ἑταῖρον δεῖ παρελθεῖν.","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τίνα τοῦτον;","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> Ἰσοκράτη τὸν καλόν· ᾧ τί ἀπαγγελεῖς, ὦ Σώκρατες; τίνα αὐτὸν φήσομεν εἶναι;","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> νέος ἔτι, ὦ Φαῖδρε, Ἰσοκράτης· ὃ μέντοι μαντεύομαι","st":"278e"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> κατ᾽ αὐτοῦ, λέγειν ἐθέλω.","st":"279a"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τὸ ποῖον δή;","st":"279a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> δοκεῖ μοι ἀμείνων ἢ κατὰ τοὺς περὶ Λυσίαν εἶναι λόγους τὰ τῆς φύσεως, ἔτι τε ἤθει γεννικωτέρῳ κεκρᾶσθαι· ὥστε οὐδὲν ἂν γένοιτο θαυμαστὸν προϊούσης τῆς ἡλικίας εἰ περὶ αὐτούς τε τοὺς λόγους, οἷς νῦν ἐπιχειρεῖ, πλέον ἢ παίδων διενέγκοι τῶν πώποτε ἁψαμένων λόγων, ἔτι τε εἰ αὐτῷ μὴ ἀποχρήσαι ταῦτα, ἐπὶ μείζω δέ τις αὐτὸν ἄγοι ὁρμὴ θειοτέρα· φύσει γάρ, ὦ φίλε, ἔνεστί τις φιλοσοφία","st":"279a"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> τῇ τοῦ ἀνδρὸς διανοίᾳ. ταῦτα δὴ οὖν ἐγὼ μὲν παρὰ τῶνδε τῶν θεῶν ὡς ἐμοῖς παιδικοῖς Ἰσοκράτει ἐξαγγέλλω, σὺ δ᾽ ἐκεῖνα ὡς σοῖς Λυσίᾳ.","st":"279b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> ταῦτ᾽ ἔσται· ἀλλὰ ἴωμεν, ἐπειδὴ καὶ τὸ πνῖγος ἠπιώτερον γέγονεν.","st":"279b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> οὐκοῦν εὐξαμένῳ πρέπει τοῖσδε πορεύεσθαι;","st":"279b"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> τί μήν;","st":"279b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ὦ φίλε Πάν τε καὶ ἄλλοι ὅσοι τῇδε θεοί, δοίητέ μοι καλῷ γενέσθαι τἄνδοθεν· ἔξωθεν δὲ ὅσα ἔχω, τοῖς ἐντὸς","st":"279b"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> εἶναί μοι φίλια. πλούσιον δὲ νομίζοιμι τὸν σοφόν· τὸ δὲ χρυσοῦ πλῆθος εἴη μοι ὅσον μήτε φέρειν μήτε ἄγειν δύναιτο ἄλλος ἢ ὁ σώφρων. ἔτ᾽ ἄλλου του δεόμεθα, ὦ Φαῖδρε; ἐμοὶ μὲν γὰρ μετρίως ηὖκται.","st":"279c"},{"sp":"N","t":"<span class=\"speaker-label\">Φαῖδρος:<\/span> καὶ ἐμοὶ ταῦτα συνεύχου· κοινὰ γὰρ τὰ τῶν φίλων.","st":"279c"},{"sp":"N","t":"<span class=\"speaker-label\">Σωκράτης:<\/span> ἴωμεν.","st":"279c"}],[]);})();